async function gwRenderQr(el, text, opts) {
  if (!el || !text) return;
  el.innerHTML = '';
  const size = Math.max(96, Math.min(320, Number(opts && opts.width) || 240));
  /* Paint remote QR immediately, then upgrade to local canvas when the lib is ready.
   * Avoids blank "Prep… QR…" while waiting solely on CDN. */
  const img = document.createElement('img');
  img.src = 'https://api.qrserver.com/v1/create-qr-code/?size=' + size + 'x' + size + '&margin=8&data=' + encodeURIComponent(text);
  img.alt = 'QR';
  img.width = size;
  img.height = size;
  img.decoding = 'async';
  img.loading = 'eager';
  img.style.display = 'block';
  img.style.width = '100%';
  img.style.height = '100%';
  el.appendChild(img);
  try {
    const lib = await gwLoadQrLib();
    if (!el.isConnected) return;
    const canvas = document.createElement('canvas');
    await lib.toCanvas(canvas, text, {
      width: size, margin: 1, color: { dark: '#1f2a38', light: '#ffffff' },
    });
    if (!el.isConnected) return;
    canvas.style.display = 'block';
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    el.innerHTML = '';
    el.appendChild(canvas);
  } catch (_) { /* keep img */ }
}
