function gwWakeConnectedWalletDeepLink(walletKey) {
  const key = String(walletKey || 'trust').toLowerCase();
  if (key === 'trust') {
    const ua = navigator.userAgent || '';
    const ios = /iPhone|iPad|iPod/i.test(ua);
    const android = /Android/i.test(ua);
    /* Open Trust app only — WC request is already on the relay. */
    if (android) return 'intent://open#Intent;scheme=trust;package=com.wallet.crypto.trustapp;end';
    if (ios) {
      /* Universal Link → Trust home. NOT open_url→grom.exchange. */
      return 'https://link.trustwallet.com/open_url?coin_id=60&url=' + encodeURIComponent('https://trustwallet.com');
    }
    return '';
  }
  const cfg = typeof gwWalletCfg === 'function' ? gwWalletCfg(key) : null;
  if (key === 'metamask') return 'metamask://';
  if (key === 'okx') return 'okx://main';
  if (key === 'binance') return 'bnc://app.binance.com/cedefi/wc';
  if (key === 'coinbase') return 'cbwallet://';
  if (cfg?.nativeScheme && !/^https?:/i.test(cfg.nativeScheme)) {
    const s = String(cfg.nativeScheme);
    if (/:\/\/$/.test(s) || /^[a-z0-9+-]+:\/\/$/i.test(s)) return s + 'wc';
    return s;
  }
  return '';
}
