/** True when signing goes through WalletConnect (Safari), not in-app injected. */
function gwIsRemoteWcSigner(provider) {
  if (!provider?.request) return false;
  try {
    const key = gwConnectedWcWalletKey();
    if (key && isInsideWalletBrowser(key)) return false;
    if (isInsideWalletBrowser('trust') || isInsideWalletBrowser('metamask')
      || isInsideWalletBrowser('binance') || isInsideWalletBrowser('okx')
      || isInsideWalletBrowser('coinbase')) {
      return false;
    }
  } catch (_) {}
  if (provider.isWalletConnect || provider.session) return true;
  try {
    if (window.gromWallet?.wcProvider && provider === window.gromWallet.wcProvider) return true;
  } catch (_) {}
  try {
    if (wcProvider && provider === wcProvider) return true;
  } catch (_) {}
  try {
    if (typeof isMobileUA === 'function' && isMobileUA()
      && typeof gwHasPersistedWcSession === 'function' && gwHasPersistedWcSession()) {
      return true;
    }
  } catch (_) {}
  return false;
}

