/**
 * Open wallet via native deep-link without unloading grom.exchange.
 * Chrome Android kills the WC relay if we assign location.href to trust:// —
 * Intent + hidden iframe keeps the tab alive so approval can finish.
 */
function gwOpenNativeDeepLink(link) {
  if (!link) return;
  const ua = navigator.userAgent || '';
  const android = /Android/i.test(ua);
  const ios = /iPhone|iPad|iPod/i.test(ua);
  let href = link;
  if (android && /^trust:\/\/wc\?/i.test(link)) {
    const path = link.replace(/^trust:\/\//i, '');
    href = 'intent://' + path
      + '#Intent;scheme=trust;package=com.wallet.crypto.trustapp;S.browser_fallback_url='
      + encodeURIComponent('https://grom.exchange')
      + ';end';
  }
  try {
    const iframe = document.createElement('iframe');
    iframe.setAttribute('aria-hidden', 'true');
    iframe.style.cssText = 'display:none;width:0;height:0;border:0;position:absolute';
    iframe.src = href;
    document.body.appendChild(iframe);
    setTimeout(() => { try { iframe.remove(); } catch (_) {} }, 2500);
  } catch (_) {}
  // iOS: custom schemes usually need a top-level navigation. Android Chrome:
  // never location.href — it unloads the page and WC approval never arrives.
  if (ios || (!android && !ios)) {
    try { window.location.href = link; } catch (_) {}
  }
}

function openWalletWcApp(walletKey, wcUri) {
  const cfg = gwWalletCfg(walletKey) || GW_WALLET_WC.generic;
  let link = typeof cfg.mobileScheme === 'function' ? cfg.mobileScheme(wcUri) : null;
  if (!link) return;
  if (walletKey === 'trust' && gwIsHttpsWalletHop(link)) link = trustWcDeepLink(wcUri);
  /* Desktop: only https hops in a new tab; native schemes break Safari. */
  const phone = typeof isPhoneUA === 'function' ? isPhoneUA() : isMobileUA();
  if (!phone) {
    if (!gwIsHttpsWalletHop(link)) return;
  }
  try { setWalletWcDeepLinkChoice(walletKey); } catch (_) {}
  // https universal links must NEVER replace this tab: if the app isn't
  // installed (or iOS UL hand-off fails) the wallet's website loads over
  // grom.exchange and the pending WC session dies. New tab keeps us alive.
  if (gwIsHttpsWalletHop(link)) {
    try {
      const w = window.open(link, '_blank', 'noopener');
      if (!w) window.location.href = link; // popup blocked — last resort
    } catch (_) {}
    return;
  }
  gwOpenNativeDeepLink(link);
}
