function openTrustWcApp(uri) { openWalletWcApp('trust', uri); }
function standardWcNamespaces() {
  // Required: Arbitrum only (our default). Optional: other EVM chains + SOL + TRX.
  // One QR / one approval. Wallets that support the namespace (Trust, OKX,
  // TokenPocket) show TRX next to EVM and Solana. Wallets that ignore unknown
  // optional namespaces (MetaMask) still connect EVM. TRX stays optional so a
  // missing Tron account never blocks the EVM session.
  const requiredMethods = ['eth_sendTransaction', 'personal_sign', 'eth_signTypedData_v4'];
  const optionalMethods = [
    'eth_sendTransaction', 'personal_sign',
    'eth_signTypedData', 'eth_signTypedData_v4',
    'eth_call', 'eth_getBalance', 'eth_chainId', 'eth_accounts',
    'wallet_switchEthereumChain', 'wallet_addEthereumChain',
  ];
  const events = ['chainChanged', 'accountsChanged'];
  const required = (CHAINS.required || [42161]).map((id) => 'eip155:' + id);
  const optional = (CHAINS.optional || [1, 8453, 137, 56, 10, 43114, 59144]).map((id) => 'eip155:' + id);
  const SOLANA_MAINNET = 'solana:5eykt4UsFv8P8NJdTREpY1vzqKqZKvdp';
  const TRON_MAINNET = 'tron:0x2b6653dc';
  return {
    requiredNamespaces: {
      eip155: { methods: requiredMethods, chains: required, events },
    },
    optionalNamespaces: {
      eip155: { methods: optionalMethods, chains: optional, events },
      solana: {
        methods: ['solana_signTransaction', 'solana_signMessage', 'solana_signAndSendTransaction'],
        chains: [SOLANA_MAINNET],
        events: [],
      },
      tron: {
        methods: ['tron_signTransaction', 'tron_signMessage'],
        chains: [TRON_MAINNET],
        events: [],
      },
    },
  };
}

/** EVM + Solana, no TRX — fallback if a wallet rejects the tron namespace. */
function standardWcNamespacesNoTron() {
  const full = standardWcNamespaces();
  const opt = Object.assign({}, full.optionalNamespaces);
  delete opt.tron;
  return {
    requiredNamespaces: full.requiredNamespaces,
    optionalNamespaces: opt,
  };
}

/** EVM-only proposal — fallback if a wallet chokes on solana or tron optional ns. */
function standardWcNamespacesEvmOnly() {
  const full = standardWcNamespaces();
  return {
    requiredNamespaces: full.requiredNamespaces,
    optionalNamespaces: { eip155: full.optionalNamespaces.eip155 },
  };
}

/** Propose EVM+SOL+TRX, then drop TRX, then EVM only. connect() throws before the QR. */
async function gwWcClientConnect(client) {
  const tries = [standardWcNamespaces, standardWcNamespacesNoTron, standardWcNamespacesEvmOnly];
  let lastErr;
  const perTryMs = window.GROM_SAFARI ? 12000 : (gwIsChromeFamily() ? 8000 : 10000);
  for (let i = 0; i < tries.length; i++) {
    try {
      return await Promise.race([
        client.connect(tries[i]()),
        new Promise((_, rej) => setTimeout(
          () => rej(new Error('WalletConnect QR timeout — close and try again')),
          perTryMs,
        )),
      ]);
    } catch (e) {
      lastErr = e;
      console.warn('[GROM] WC propose fallback', i, e?.message || e);
    }
  }
  throw lastErr || new Error('WalletConnect propose failed');
}

/** CAIP account → bare address: `eip155:1:0x…` / `solana:…:Base58` / `tron:…:T…` */
function gwCaipAccountAddress(entry) {
  const s = String(entry || '');
  const parts = s.split(':');
  if (parts.length >= 3) return parts.slice(2).join(':');
  if (parts.length === 2 && /^0x/i.test(parts[1])) return parts[1];
  return s;
}

function gwWcSessionSideAccounts(session) {
  const ns = session?.namespaces || {};
  const pick = (key) => {
    const accs = ns[key]?.accounts || [];
    for (const a of accs) {
      const addr = gwCaipAccountAddress(a);
      if (addr && addr.length >= 32) return addr;
    }
    return '';
  };
  return {
    solana: pick('solana'),
    tron: pick('tron'),
  };
}

/**
 * Bind TRX/SOL without overwriting the EVM chip label.
 * Used after multi-namespace WC approve or silent inject fan-out.
 */
function gwBindSideChainAddress(kind, address, opts) {
  opts = opts || {};
  const k = String(kind || '').toLowerCase();
  const addr = String(address || '').trim();
  if (!addr) return false;
  if (k === 'tron') {
    if (!/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(addr)) return false;
    try {
      localStorage.setItem('grom_tron_addr', addr);
      window.__gwTronAddr = addr;
      if (window.GROM_CONN) window.GROM_CONN.tron = addr;
    } catch (_) {}
    try {
      document.dispatchEvent(new CustomEvent('grom:tron-connected', { detail: { address: addr } }));
    } catch (_) {}
    if (typeof gwTronActivateUi === 'function' && opts.activateUi) {
      try { gwTronActivateUi(addr); } catch (_) {}
    }
    return true;
  }
  if (k === 'solana' || k === 'sol') {
    if (!/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(addr)) return false;
    try {
      localStorage.setItem('grom_sol_addr', addr);
      window.__gwSolAddr = addr;
      window.__gwSolPubkey = addr;
      if (window.GROM_CONN) window.GROM_CONN.solana = addr;
    } catch (_) {}
    try {
      document.dispatchEvent(new CustomEvent('grom:solana-connected', { detail: { address: addr } }));
    } catch (_) {}
    return true;
  }
  return false;
}
try { window.gwBindSideChainAddress = gwBindSideChainAddress; } catch (_) {}

function gwBindSideChainsFromWcSession(session) {
  if (!session) return { solana: '', tron: '' };
  const side = gwWcSessionSideAccounts(session);
  if (side.solana) gwBindSideChainAddress('solana', side.solana);
  if (side.tron) gwBindSideChainAddress('tron', side.tron);
  if (side.solana || side.tron) {
    console.log('[GROM] WC multi-ns sides', {
      sol: side.solana ? side.solana.slice(0, 6) + '…' : '',
      tron: side.tron ? side.tron.slice(0, 6) + '…' : '',
    });
  }
  return side;
}

function gwSolGetInjected() {
  try {
    return window.trustwallet?.solana
      || window.okxwallet?.solana
      || window.bitkeep?.solana
      || window.solana
      || window.phantom?.solana
      || null;
  } catch (_) { return null; }
}

/** Silent SOL bind — no popup when possible (onlyIfTrusted / already connected). */
async function gwSolTrySilentConnect() {
  const p = gwSolGetInjected();
  if (!p) return null;
  try {
    const existing = p.publicKey?.toString?.() || p.publicKey;
    if (existing) return String(existing);
    if (typeof p.connect !== 'function') return null;
    await Promise.race([
      p.connect({ onlyIfTrusted: true }).catch(() => null),
      new Promise((r) => setTimeout(r, 1800)),
    ]);
    const pk = p.publicKey?.toString?.() || p.publicKey;
    return pk ? String(pk) : null;
  } catch (_) {
    return null;
  }
}

/**
 * After EVM Connect (inject or WC): attach every other chain the wallet
 * already exposes — WC multi-ns session first, then silent inject probes.
 * Never opens a second QR / TronLink sheet. Safe no-op for MetaMask-only etc.
 */
async function gwFanOutSideChains(opts) {
  opts = opts || {};
  if (window.__gwFanOutBusy) return window.__gwFanOutBusy;
  const work = (async () => {
    let hadTron = '';
    let hadSol = '';
    try {
      hadTron = String(window.GROM_CONN?.tron || window.__gwTronAddr || localStorage.getItem('grom_tron_addr') || '');
      hadSol = String(window.GROM_CONN?.solana || window.__gwSolAddr || localStorage.getItem('grom_sol_addr') || '');
    } catch (_) {}

    const session = opts.session
      || wcProvider?.session
      || wcProvider?.signer?.session
      || null;
    try { if (session) window.__gwWcSession = session; } catch (_) {}

    const fromWc = gwBindSideChainsFromWcSession(session);
    let tron = fromWc.tron || hadTron || '';
    let sol = fromWc.solana || hadSol || '';
    /* Bind Tron WC signer from the same Trust session — prevents TronLink sheet on swap. */
    if (fromWc.tron || session?.namespaces?.tron) {
      try {
        let client = typeof gwTronWcClientCandidate === 'function'
          ? gwTronWcClientCandidate()
          : (_wcClient || null);
        if (!client && typeof gwWcClient === 'function') {
          try { client = await Promise.race([gwWcClient(), new Promise((r) => setTimeout(() => r(null), 2000))]); } catch (_) {}
        }
        gwTronBindFromWcSession(session, client);
        try {
          if (window.__gwTkHoldingsCache) {
            window.__gwTkHoldingsCache.at = 0;
            window.__gwTkHoldingsCache.rows = [];
          }
        } catch (_) {}
      } catch (_) {}
    }

    if (!fromWc.tron) {
      try {
        const t = (await gwTronMaybeAutolink()) || '';
        if (t) {
          gwBindSideChainAddress('tron', t);
          tron = t;
        }
      } catch (_) {}
    }
    if (!fromWc.solana) {
      try {
        const s = (await gwSolTrySilentConnect()) || '';
        if (s) {
          gwBindSideChainAddress('solana', s);
          sol = s;
        }
      } catch (_) {}
    }

    const newly = [];
    if (tron && tron !== hadTron) newly.push('TRX');
    if (sol && sol !== hadSol) newly.push('SOL');
    if (newly.length && opts.toast !== false && typeof window.toast === 'function') {
      try { window.toast('Also linked · ' + newly.join(' · '), 'success'); } catch (_) {}
    }
    if (newly.length || fromWc.tron || fromWc.solana) {
      try { gwRefreshCombinedPortfolioTotals?.(); } catch (_) {}
      try { gwDsSimRenderBalances?.(); } catch (_) {}
    }
    return { tron: tron || '', solana: sol || '' };
  })();
  window.__gwFanOutBusy = work;
  try { return await work; }
  finally {
    if (window.__gwFanOutBusy === work) window.__gwFanOutBusy = null;
  }
}
try { window.gwFanOutSideChains = gwFanOutSideChains; } catch (_) {}

function sessionEip155ChainIds(session) {
  const ids = [];
  const add = (id) => {
    const n = Number(id);
    if (n && !ids.includes(n)) ids.push(n);
  };
  const accs = session?.namespaces?.eip155?.accounts || [];
  for (const a of accs) add(parseInt(String(a).split(':')[1], 10));
  const chains = session?.namespaces?.eip155?.chains || [];
  for (const c of chains) add(parseInt(String(c).split(':')[1], 10));
  return ids;
}
function primaryChainRef(session) {
  const ids = sessionEip155ChainIds(session);
  if (!ids.length) return 'eip155:' + (CHAINS.required?.[0] || 42161);
  // Prefer Arbitrum, then Ethereum, then whatever the session has.
  const prefer = [42161, 1, 56, 8453, 137, 10, 43114];
  const hit = prefer.find((id) => ids.includes(id)) || ids[0];
  return 'eip155:' + hit;
}
function chainIdFromWcSession(session) {
  const ref = primaryChainRef(session);
  return parseInt(ref.split(':')[1], 10) || 42161;
}
/** WC SignClient must tag the chain the tx is built for — not always eip155:1. */
function wcChainRefForRequest(session, method) {
  const ids = sessionEip155ChainIds(session);
  const want = Number(currentChainId) || 0;
  if (want && (method === 'eth_sendTransaction' || method === 'wallet_switchEthereumChain'
    || method === 'wallet_addEthereumChain')) {
    if (ids.includes(want) || method !== 'eth_sendTransaction') return 'eip155:' + want;
    return 'eip155:' + want;
  }
  if (method === 'eth_chainId' && want) return 'eip155:' + want;
  return primaryChainRef(session);
}
/** After WC connect: provider may still target eip155:1 while session has no ETH. */
async function gwAlignWcProviderChain(provider) {
  if (!provider) return;
  const session = provider.session || provider.signer?.session || null;
  const ids = sessionEip155ChainIds(session);
  if (!ids.length) return;
  let current = Number(provider.chainId) || currentChainId || 0;
  try {
    if (!current) {
      const hex = await provider.request({ method: 'eth_chainId' });
      current = parseInt(hex, 16) || 0;
    }
  } catch (_) {}
  if (ids.includes(current)) {
    currentChainId = current;
    return;
  }
  const target = ids.includes(42161) ? 42161 : (ids.includes(1) ? 1 : ids[0]);
  currentChainId = target;
  try {
    if (typeof provider.setDefaultChain === 'function') {
      provider.setDefaultChain('eip155:' + target);
    }
  } catch (_) {}
  try {
    await provider.request({
      method: 'wallet_switchEthereumChain',
      params: [{ chainId: '0x' + target.toString(16) }],
    });
  } catch (_) {
    // Switch may reopen Trust UI — keep currentChainId for SIWE anyway.
  }
}
/**
 * Keep exactly one live WC session per wallet. Every reconnect used to leave the
 * old session alive, so Trust kept a queue of requests from dead sessions and
 * surfaced those instead of the current one (e.g. a 2h-old oversized top-up).
 */
function gwWcPruneStaleSessions(signClient, keepTopic) {
  if (!signClient?.session?.getAll) return;
  let all = [];
  try { all = signClient.session.getAll() || []; } catch (_) { return; }
  const stale = all.filter((s) => s?.topic && s.topic !== keepTopic);
  if (!stale.length) return;
  console.log('[GROM] pruning ' + stale.length + ' stale WC session(s)');
  for (const s of stale) {
    signClient.disconnect({
      topic: s.topic,
      reason: { code: 6000, message: 'Replaced by new session' },
    }).catch(() => {});
  }
}
try { window.gwWcPruneStaleSessions = gwWcPruneStaleSessions; } catch (_) {}

function buildSignClientEip1193(signClient, session) {
  const accounts = (session?.namespaces?.eip155?.accounts || [])
    .map((a) => {
      const parts = String(a || '').split(':');
      if (parts.length >= 3 && gwAddrOk(parts[2])) return parts[2];
      return gwWcAddressFromAccountRef(a);
    }).filter(Boolean);
  const chainId = chainIdFromWcSession(session);
  currentChainId = chainId;
  const uniqAccounts = [...new Set(accounts)];
  return {
    accounts: uniqAccounts,
    session,
    signClient,
    request: async ({ method, params }) => {
      /* WC sessions rarely list eth_requestAccounts — Futures/Predict used to
       * throw "Missing or invalid. request() method: eth_requestAccounts"
       * while the chip still showed a connected address. */
      if (method === 'eth_accounts' || method === 'eth_requestAccounts') return uniqAccounts;
      if (method === 'eth_chainId') {
        const active = Number(currentChainId) || chainIdFromWcSession(session);
        return '0x' + active.toString(16);
      }
      const chainRef = wcChainRefForRequest(session, method);
      let reqParams = params;
      if (method === 'eth_sendTransaction' && Array.isArray(params) && params[0] && typeof params[0] === 'object') {
        reqParams = [typeof gwNormalizeEvmTxForWallet === 'function'
          ? gwNormalizeEvmTxForWallet(params[0])
          : params[0]];
      }
      return signClient.request({
        topic: session.topic,
        chainId: chainRef,
        request: { method, params: reqParams },
      });
    },
    on: (ev, cb) => signClient.on(ev, cb),
    removeListener: (ev, cb) => signClient.off(ev, cb),
    disconnect: async () => {
      await signClient.disconnect({
        topic: session.topic,
        reason: { code: 6000, message: 'User disconnected' },
      });
    },
  };
}

/** Wrap EIP-1193 provider so eth_requestAccounts works on live WC sessions. */
function gwPatchProviderRequestAccounts(provider) {
  if (!provider || typeof provider.request !== 'function') return provider;
  /* v2 adds eth_sendTransaction value guard — re-wrap even if older patch applied. */
  if (provider.__gwPatchedReqAccV2) return provider;
  const orig = provider.__gwPatchedReqAcc && provider.__gwOrigRequest
    ? provider.__gwOrigRequest.bind(provider)
    : provider.request.bind(provider);
  try { provider.__gwOrigRequest = orig; } catch (_) {}
  provider.request = async (args) => {
    const method = (args && args.method) || args;
    if (method === 'eth_sendTransaction') {
      const params = Array.isArray(args?.params) ? args.params.slice() : [];
      const tx0 = params[0];
      if (tx0 && typeof tx0 === 'object') {
        if (typeof gwNormalizeEvmTxForWallet === 'function') {
          params[0] = gwNormalizeEvmTxForWallet(tx0);
        }
        if (typeof gwGuardProviderTxParams === 'function') {
          gwGuardProviderTxParams(params[0], 'provider.request');
        }
        args = Object.assign({}, args, { params });
      }
    }
    if (method === 'eth_requestAccounts') {
      try {
        if (Array.isArray(provider.accounts) && provider.accounts.length) {
          return provider.accounts.slice();
        }
      } catch (_) {}
      try {
        const accs = await orig({ method: 'eth_accounts', params: (args && args.params) || [] });
        if (accs && accs.length) return accs;
      } catch (_) {}
      try {
        return await orig(args);
      } catch (e) {
        const msg = String(e?.message || e || '');
        if (/missing or invalid.*eth_requestAccounts/i.test(msg)) {
          try {
            if (Array.isArray(provider.accounts) && provider.accounts.length) {
              return provider.accounts.slice();
            }
          } catch (_) {}
          try {
            const label = localStorage.getItem('grom_wallet_label') || '';
            if (/^0x[a-fA-F0-9]{40}$/.test(label)) return [label];
          } catch (_) {}
        }
        throw e;
      }
    }
    return orig(args);
  };
  provider.__gwPatchedReqAcc = true;
  provider.__gwPatchedReqAccV2 = true;
  return provider;
}
try { window.gwPatchProviderRequestAccounts = gwPatchProviderRequestAccounts; } catch (_) {}
function trustWcNamespaces() { return standardWcNamespaces(); }
/**
 * Legacy name (was EthereumProvider). Now: single SignClient + URI callback.
 * URI comes from client.connect(), not display_uri events.
 */
async function connectViaEthereumProvider(walletKey, uriHandler) {
  const cfg = GW_WALLET_WC[walletKey];
  const client = await gwWcClient();
  gwPatchWcVerify(client);
  await new Promise((r) => setTimeout(r, window.GROM_SAFARI ? 180 : 350));
  const { uri, approval } = await gwWcClientConnect(client);
  if (!uri) throw new Error('Could not start ' + (cfg?.label || 'wallet') + ' session');
  if (typeof uriHandler === 'function') uriHandler(uri);
  const session = await approval();
  gwWcPruneStaleSessions(client, session?.topic);
  const p = gwPatchProviderRequestAccounts(buildSignClientEip1193(client, session));
  wcProvider = p;
  wcRecommendedForKey = walletKey || null;
  if (walletKey) gwRememberWcWalletKey(walletKey);
  p.on('accountsChanged', (accs) => updateChip(accs?.[0] || null));
  p.on('chainChanged', (hex) => { currentChainId = parseInt(hex, 16); });
  p.on('disconnect', () => updateChip(null));
  await gwAlignWcProviderChain(p);
  let accs = Array.isArray(p.accounts) ? p.accounts.slice() : [];
  if (!accs.length) {
    try { accs = await p.request({ method: 'eth_accounts' }); } catch (_) {}
  }
  if (!accs?.length) throw new Error('No accounts returned');
  return { provider: p, account: accs[0] };
}
async function finalizeWcConnection(provider, account) {
  window.__gromConnecting = true;
  try {
    const key = String(account || '').toLowerCase();
    if (window.__gwFinalizeWcInflight && window.__gwFinalizeWcAddr === key) {
      await window.__gwFinalizeWcInflight;
      return account;
    }
    const work = (async () => {
      try { gwNotifyWalletConnected(account, { toast: true }); } catch (_) {}
      try {
        if (typeof isMobileUA === 'function' && !isMobileUA()) gwClearWcDeepLinkChoice();
      } catch (_) {}
      try {
        await gwFanOutSideChains({
          session: provider?.session || provider?.signer?.session || null,
          toast: true,
        });
      } catch (e) {
        console.log('[GROM] side-chain fan-out:', e?.message || e);
      }
      return account;
    })();
    window.__gwFinalizeWcInflight = work;
    window.__gwFinalizeWcAddr = key;
    try { return await work; }
    finally {
      if (window.__gwFinalizeWcInflight === work) {
        window.__gwFinalizeWcInflight = null;
        window.__gwFinalizeWcAddr = null;
      }
    }
  } catch (err) {
    gwSiweFailToast(err);
    throw err;
  } finally {
    window.__gromConnecting = false;
  }
}

/** Pending SignClient state — resume WC after iOS app-switch. */
let _gwMobileWcState = null;
let _gwMobileWcResolving = false;
function gwClearMobileWcState() { _gwMobileWcState = null; }

async function gwTryResumeMobileWc() {
  if (_gwMobileWcResolving) return false;
  const st = _gwMobileWcState;
  // NOTE: do not require __gromConnecting — when iOS kills the relay socket,
  // approval() rejects and the connect flow's finally block already reset the
  // flag. The 180s freshness window below is the real guard.
  if (!st?.client) return false;
  if (Date.now() - st.startedAt > 180000) return false;
  _gwMobileWcResolving = true;
  try {
    // iOS kills the relay websocket during app-switch; the wallet's approval
    // never arrives on the dead socket. Restart transport so pending session
    // messages get delivered, then give the relay a beat to sync.
    try {
      const relayer = st.client.core?.relayer;
      if (relayer && typeof relayer.restartTransport === 'function') {
        await Promise.race([
          relayer.restartTransport(),
          new Promise((r) => setTimeout(r, 3000)),
        ]);
        await new Promise((r) => setTimeout(r, 700));
      }
    } catch (e) { console.log('[GROM] relay restart:', e?.message || e); }
    const sessions = (st.client.session.getAll() || []).filter(
      (s) => s?.active !== false && s?.namespaces?.eip155?.accounts?.length
    );
    if (!sessions.length) return false;
    sessions.sort((a, b) => (Number(b?.expiry) || 0) - (Number(a?.expiry) || 0));
    const session = sessions[0];
    gwWcPruneStaleSessions(st.client, session?.topic);
    const provider = gwPatchProviderRequestAccounts(buildSignClientEip1193(st.client, session));
    wcProvider = provider;
    gwRememberWcWalletKey(st.walletKey);
    provider.on('accountsChanged', (accs) => updateChip(accs?.[0] || null));
    provider.on('disconnect', () => updateChip(null));
    const acc = provider.accounts?.[0];
    if (!acc) return false;
    gwHideWcModalOnly();
    gwClearWcPending();
    gwClearMobileWcState();
    await finalizeWcConnection(provider, acc);
    return true;
  } catch (e) {
    console.log('[GROM] mobile WC resume:', e?.message || e);
    return false;
  } finally {
    _gwMobileWcResolving = false;
  }
}

function gwInstallMobileWcHandlers() {
  if (gwInstallMobileWcHandlers._done) return;
  gwInstallMobileWcHandlers._done = true;
  // One debounced resume per return-to-browser. Old 4-timer × focus+visibility
  // storm could start multiple finalize/SIWE flows → 3–4 Trust confirms.
  let kickTimer = null;
  let _wcHiddenAt = 0;
  const kick = (delay) => {
    if (kickTimer) clearTimeout(kickTimer);
    kickTimer = setTimeout(() => {
      kickTimer = null;
      // Skip WC resume storm if no pending mobile flow — idle return shouldn't hammer Trust
      if (!_gwMobileWcState && !window.__gromConnecting) return;
      gwTryResumeMobileWc().then((ok) => {
        if (!ok && _gwMobileWcState) {
          setTimeout(() => { gwTryResumeMobileWc(); }, 2800);
        }
      }).catch(() => {});
    }, delay != null ? delay : 900);
  };
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) { _wcHiddenAt = Date.now(); return; }
    const slept = _wcHiddenAt ? (Date.now() - _wcHiddenAt) : 0;
    _wcHiddenAt = 0;
    // Longer background → later soft resume (lets Safari finish paints first)
    kick(slept > 20000 ? 1400 : slept > 5000 ? 1000 : 700);
  });
  window.addEventListener('pageshow', (ev) => { if (ev.persisted) kick(1000); });
}
async function finalizeTrustWcConnection(provider, account) {
  return finalizeWcConnection(provider, account);
}
function isBinanceProvider(p) {
  return !!(p?.isBinance || p?.isBinanceWallet || p?.bbcSignTx);
}
function isCoinbaseProvider(p) {
  return !!p?.isCoinbaseWallet;
}

async function connectWithProvider(provider, label) {
  if (!provider?.request) throw new Error(label + ' provider unavailable');
  window.__gromConnecting = true;
  try {
    const accounts = await provider.request({ method: 'eth_requestAccounts' });
    if (!accounts?.length) throw new Error('User rejected');
    const acc = accounts[0];
    gwRememberInjectedSigner(provider, acc);
    provider.on?.('accountsChanged', (accs) => {
      const next = accs?.[0] || null;
      if (next) gwRememberInjectedSigner(provider, next);
      updateChip(next);
    });
    provider.on?.('chainChanged', (hex) => { currentChainId = parseInt(hex, 16); });
    try {
      const hex = await provider.request({ method: 'eth_chainId' });
      currentChainId = parseInt(hex, 16);
    } catch (_) {}
    /* Chip first — extension is already the signer. SIWE is optional for swap. */
    updateChip(acc);
    try {
      await authenticateWithSIWE(acc, provider);
    } catch (e) {
      console.log('[GROM] SIWE after injected connect:', e?.message || e);
    }
    try {
      await gwFanOutSideChains({ toast: true });
    } catch (e) {
      console.log('[GROM] inject side-chain fan-out:', e?.message || e);
    }
    return acc;
  } catch (err) {
    gwSiweFailToast(err);
    throw err;
  } finally {
    window.__gromConnecting = false;
  }
}

function gwRememberInjectedSigner(provider, addr) {
  if (!provider || typeof provider.request !== 'function') return;
  window.__gwLiveInjectedProvider = provider;
  window.__gwSoftInjectedProvider = provider;
  window.__gwInjectedRestored = true;
  try {
    const wcAcc = String(
      wcProvider?.accounts?.[0] || (typeof gwWcSessionAddress === 'function' ? gwWcSessionAddress(wcProvider?.session) : '') || '',
    ).toLowerCase();
    const inj = String(addr || provider.selectedAddress || '').toLowerCase();
    if (inj && wcAcc && wcAcc !== inj) {
      console.log('[GROM] injected signer differs from WC — prefer extension');
      wcProvider = null;
    }
  } catch (_) {}
}
try { window.gwRememberInjectedSigner = gwRememberInjectedSigner; } catch (_) {}

/* Show a friendly, actionable toast when SIWE fails. Called by all wallet
 * connectors so a silent signature-reject never leaves the user staring at
 * "Sign in to view balance" with no explanation. */
function gwSiweFailToast(err) {
  const rawMsg = String(err?.message || err || '').toLowerCase();
  if (/chainid:\s*eip155:1|missing or invalid\.?\s*request\(\)\s*chainid/i.test(rawMsg)) {
    console.warn('[GROM] SIWE chainId mismatch (suppressed):', err?.message || err);
    return;
  }
  const rejected =
    rawMsg.includes('reject') ||
    rawMsg.includes('cancel') ||
    rawMsg.includes('denied') ||
    err?.code === 4001 || err?.code === -32000;
  const msg = rejected
    ? (isMobileUA()
      ? gwTx('wc_toast_siwe_rejected_mobile', null, 'Sign the message in your wallet (open Trust) — sign-in cannot finish without it.')
      : gwTx('wc_toast_siwe_rejected_desktop', null, 'Sign the message in your wallet to finish signing in.'))
    : 'Sign-in failed: ' + (err?.message || 'signature not verified');
  if (!rejected) {
    try { window.gwSentryCapture?.(err, { tags: { flow: 'siwe' } }); } catch (_) {}
  }
  try {
    gromReportIssue({
      product: 'wallet',
      action: rejected ? 'siwe_rejected' : 'siwe_failed',
      message: String(err?.message || err || msg).slice(0, 500),
      code: err?.code,
      detail: {
        rejected: !!rejected,
        kind: rejected ? 'cancelled' : 'failed',
        admin_brief: rejected
          ? 'Отклонил SIWE-подпись входа в кошельке'
          : 'SIWE / вход не завершился',
      },
    });
  } catch (_) {}
  try { gwToast(msg, rejected ? 'warn' : 'error'); } catch (_) {}
}

