/**
 * ensureWC — return live EIP-1193 provider from the single SignClient Core.
 * No EthereumProvider (would spawn a second Core). New sessions use
 * connectViaSignClientCustomQr / connectViaEthereumProvider (alias).
 */
async function ensureWC(forceNew, opts) {
  const walletKey = opts?.walletKey || null;
  if (wcProvider?.accounts?.length && !forceNew) {
    if (walletKey) gwRememberWcWalletKey(walletKey);
    return wcProvider;
  }
  if (forceNew && wcProvider) {
    try { await wcProvider.disconnect?.(); } catch (_) {}
    wcProvider = null;
  }
  const restored = await gwRestoreSignClientSession();
  if (restored?.accounts?.length) {
    if (walletKey) {
      gwRememberWcWalletKey(walletKey);
      wcRecommendedForKey = walletKey;
    }
    return restored;
  }
  await gwWcClient();
  if (wcProvider?.accounts?.length) return wcProvider;
  throw new Error('No WalletConnect session — connect a wallet first');
}

/** Peek at localStorage for the WC v2 session marker. If any key starts
 *  with `wc@2:` and looks fresh, we can silently re-init the provider
 *  without popping a QR modal — the underlying session is already there. */
function gwHasPersistedWcSession() {
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.startsWith('wc@2:')) return true;
    }
  } catch (_) {}
  return false;
}
window.gwHasWcSession = gwHasPersistedWcSession;

/** Drop WC v2 cache keys only (keep JWT/chip). Used when QR mint is stuck. */
function gwPurgeWcSessionKeys() {
  try {
    const keysToRemove = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k) continue;
      if (k.startsWith('wc@2:') || k.startsWith('WCM_') || k.startsWith('wagmi.')
          || k.startsWith('@w3m') || k.startsWith('@reown') || k === 'WALLETCONNECT_DEEPLINK_CHOICE') {
        keysToRemove.push(k);
      }
    }
    keysToRemove.forEach((k) => { try { localStorage.removeItem(k); } catch (_) {} });
    return keysToRemove.length;
  } catch (_) { return 0; }
}
try { window.gwPurgeWcSessionKeys = gwPurgeWcSessionKeys; } catch (_) {}

/** Drop WC IndexedDB DBs that MetaMask/Chrome often leave locked (blocks SignClient.init). */
function gwWipeWcIndexedDb() {
  return (async () => {
    try {
      if (!indexedDB || typeof indexedDB.databases !== 'function') return 0;
      const dbs = await indexedDB.databases();
      let n = 0;
      for (const db of dbs || []) {
        const name = String(db && db.name || '');
        if (!name) continue;
        if (!/walletconnect|WALLET_CONNECT|wc@|@w3m|@reown|grom-wc|WALLETCONNECT/i.test(name)) continue;
        try {
          indexedDB.deleteDatabase(name);
          n += 1;
        } catch (_) {}
      }
      return n;
    } catch (_) { return 0; }
  })();
}
try { window.gwWipeWcIndexedDb = gwWipeWcIndexedDb; } catch (_) {}

/**
 * Pure Map KV for WalletConnect Core.
 * Stock SignClient always migrates to IndexedDB (idb-keyval "keyval-store") even when
 * storageOptions.database is ":memory:" — and MetaMask locks that DB in Chrome, so
 * SignClient.init hangs until our timeout ("Creating QR…" forever).
 */
function gwMakeMemoryKvStorage() {
  const map = new Map();
  return {
    getKeys: async () => Array.from(map.keys()),
    getEntries: async () => Array.from(map.entries()),
    getItem: async (key) => (map.has(key) ? map.get(key) : undefined),
    setItem: async (key, value) => { map.set(key, value); },
    removeItem: async (key) => { map.delete(key); },
  };
}
