/** Pull 0x… from `eip155:1:0xabc` or a bare address. */
function gwWcAddressFromAccountRef(ref) {
  const s = String(ref || '').trim();
  const m = s.match(/0x[a-fA-F0-9]{40}/);
  return m ? m[0] : '';
}

function gwWcSessionAddress(session) {
  if (!session) return '';
  const lists = [];
  try {
    const ns = session.namespaces || {};
    Object.keys(ns).forEach((k) => { lists.push(ns[k]?.accounts); });
  } catch (_) {}
  try { lists.push(session.namespaces?.eip155?.accounts); } catch (_) {}
  for (const list of lists) {
    if (!Array.isArray(list)) continue;
    for (const a of list) {
      const addr = gwWcAddressFromAccountRef(a);
      if (gwAddrOk(addr)) return addr;
    }
  }
  return '';
}
try { window.gwWcSessionAddress = gwWcSessionAddress; } catch (_) {}

function gwHasInjectedEthAddress() {
  try {
    const a = window.ethereum?.selectedAddress;
    if (a && /^0x[a-fA-F0-9]{40}$/i.test(a)) return true;
  } catch (_) {}
  try {
    const t = window.trustwallet?.selectedAddress;
    if (t && /^0x[a-fA-F0-9]{40}$/i.test(t)) return true;
  } catch (_) {}
  return false;
}

/** All injected EVM providers (Trust / MM / OKX / Binance / Coinbase / ethereum). */
function gwAllInjectedProviders() {
  const out = [];
  const seen = new Set();
  const add = (p) => {
    if (!p || typeof p.request !== 'function') return;
    if (seen.has(p)) return;
    seen.add(p);
    out.push(p);
  };
  try { add(resolveTrustProvider()); } catch (_) {}
  try { add(window.trustwallet); } catch (_) {}
  try {
    for (const p of legacyProviders()) add(p);
  } catch (_) {}
  try {
    EIP6963.forEach((entry) => { try { add(entry?.provider); } catch (_) {} });
  } catch (_) {}
  try { add(window.ethereum); } catch (_) {}
  return out;
}
try { window.gwAllInjectedProviders = gwAllInjectedProviders; } catch (_) {}

function gwPickBestInjectedProvider() {
  try {
    const trust = resolveTrustProvider();
    if (trust) return trust;
  } catch (_) {}
  const all = gwAllInjectedProviders();
  if (!all.length) return null;
  /* Prefer non-MetaMask when user last used Trust / Binance (MetaMask hijacks ethereum). */
  let method = '';
  try { method = localStorage.getItem('grom_wc_wallet_key') || localStorage.getItem('grom_wallet_method') || ''; } catch (_) {}
  if (/trust/i.test(method)) {
    const t = all.find((p) => isTrustProvider(p));
    if (t) return t;
  }
  const nonMm = all.find((p) => !isMetaMaskProvider(p));
  return nonMm || all[0];
}
try { window.gwPickBestInjectedProvider = gwPickBestInjectedProvider; } catch (_) {}

function gwJwtPayload(token) {
  try {
    const jwt = String(token || localStorage.getItem('grom_jwt') || '');
    if (!jwt || jwt.split('.').length !== 3) return null;
    const b64 = jwt.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
    const pad = b64 + '='.repeat((4 - (b64.length % 4)) % 4);
    return JSON.parse(atob(pad));
  } catch (_) { return null; }
}

function gwJwtValid() {
  try {
    const jwt = localStorage.getItem('grom_jwt') || '';
    if (!jwt || jwt.split('.').length !== 3
      || jwt === 'demo-session') return false;
    const payload = gwJwtPayload(jwt);
    if (!payload) return false;
    if (payload.exp && Number(payload.exp) * 1000 < Date.now() - 5000) {
      try { localStorage.removeItem('grom_jwt'); } catch (_) {}
      return false;
    }
    return true;
  } catch (_) {}
  return false;
}
try { window.gwJwtValid = gwJwtValid; } catch (_) {}
try { window.gwJwtPayload = gwJwtPayload; } catch (_) {}

function gwAuthPurgeBlocked() {
  return gwConnectSheetVisible();
}

function gwAddrOk(a) {
  return typeof a === 'string' && /^0x[a-fA-F0-9]{40}$/i.test(a.trim());
}

/** EVM + Tron + Solana — for chip / connect modal (not for eth_sign / SIWE). */
function gwAnyChainAddrOk(a) {
  if (typeof a !== 'string') return false;
  const s = a.trim();
  if (!s) return false;
  if (/^0x[a-fA-F0-9]{40}$/i.test(s)) return true;
  if (/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(s)) return true; // Tron base58
  // Solana base58 pubkeys (exclude Tron T… already matched)
  if (/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(s)) return true;
  return false;
}
window.gwAnyChainAddrOk = gwAnyChainAddrOk;

function gwDetectWalletMethod(addr) {
  const s = String(addr || '').trim();
  if (/^0x[a-fA-F0-9]{40}$/i.test(s)) return 'evm';
  if (/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(s)) return 'tron';
  if (/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(s)) return 'solana';
  return 'wallet';
}

function gwShortWalletLabel(addr) {
  const s = String(addr || '').trim();
  if (s.length <= 12) return s;
  return s.slice(0, 6) + '…' + s.slice(-4);
}

/** Live provider that can sign right now (WC with accounts or injected extension). */
function gwActiveSigningProvider() {
  try {
    let chip = '';
    try {
      chip = String(
        currentAccount
        || window.GROM_CONN?.label
        || localStorage.getItem('grom_wallet_label')
        || '',
      ).toLowerCase();
    } catch (_) {}
    const inj = window.__gwLiveInjectedProvider || window.__gwSoftInjectedProvider;
    if (inj?.request) {
      const a = String(inj.selectedAddress || inj.accounts?.[0] || '').toLowerCase();
      if (gwAddrOk(a) && (!gwAddrOk(chip) || a === chip)) {
        return gwPatchProviderRequestAccounts(inj);
      }
      if (gwAddrOk(chip) && inj === window.__gwLiveInjectedProvider) {
        return gwPatchProviderRequestAccounts(inj);
      }
    }
    if (wcProvider) {
      gwPatchProviderRequestAccounts(wcProvider);
      const wcAcc = String(
        wcProvider.accounts?.[0] || gwWcSessionAddress(wcProvider.session) || '',
      ).toLowerCase();
      if (gwAddrOk(wcAcc) && (!gwAddrOk(chip) || wcAcc === chip)) return wcProvider;
    }
    if (window.gromWallet?.wcProvider?.accounts?.length) {
      gwPatchProviderRequestAccounts(window.gromWallet.wcProvider);
      return window.gromWallet.wcProvider;
    }
    const best = typeof gwPickBestInjectedProvider === 'function' ? gwPickBestInjectedProvider() : null;
    if (best && gwHasInjectedEthAddress()) {
      return gwPatchProviderRequestAccounts(best);
    }
    if (gwHasInjectedEthAddress()) {
      const p = best || window.ethereum;
      if (p) return gwPatchProviderRequestAccounts(p);
    }
  } catch (_) {}
  return null;
}
