window.gwPurgeStaleWalletAuth = gwPurgeStaleWalletAuth;

async function gwRestoreSignClientSession() {
  try {
    // Don't spawn a Core just to discover an empty session store.
    if (!gwHasPersistedWcSession() && !_wcClient && !_wcClientPromise) return null;
    const client = await gwWcClient();
    const all = client.session.getAll() || [];
    const nowSec = Math.floor(Date.now() / 1000);
    const sessions = all.filter((s) => {
      if (!s) return false;
      if (s.active === false) return false;
      if (Number(s.expiry) && Number(s.expiry) < nowSec - 5) return false;
      return !!(gwWcSessionAddress(s) || s?.namespaces?.eip155?.accounts?.length);
    });
    if (!sessions.length) {
      console.log('[GROM] SignClient restore: no usable session (' + all.length + ' stored)');
      return null;
    }
    sessions.sort((a, b) => (Number(b?.expiry) || 0) - (Number(a?.expiry) || 0));
    const session = sessions[0];
    /* Do not prune siblings on restore — that used to kill the live Trust pairing
     * and force a new WalletConnect QR on the next Swap. */
    const provider = gwPatchProviderRequestAccounts(buildSignClientEip1193(client, session));
    wcProvider = provider;
    if (!provider.__gromSessionDeleteBound) {
      provider.on?.('session_delete', () => {
        try {
          /* Trust/WC relay flaps must not wipe the chip after F5 soft-restore. */
          console.log('[GROM] WC session_delete — keep identity, drop provider only');
          wcProvider = null;
          /* Attempt silent restore if keys still in storage (relay flap, not user logout). */
          setTimeout(() => {
            try {
              if (window.__gwForceDisconnect || localStorage.getItem('grom:logged_out') === '1') return;
              if (typeof gwRestorePersistedWcSession === 'function') {
                gwRestorePersistedWcSession().then((p) => {
                  if (p?.accounts?.[0]) {
                    console.log('[GROM] WC session_delete — restored after flap');
                    try { updateChip(p.accounts[0]); } catch (_) {}
                  }
                }).catch(() => {});
              }
            } catch (_) {}
          }, 800);
          return;
        } catch (_) {}
        updateChip(null);
      });
      provider.__gromSessionDeleteBound = true;
    }
    const acc = provider.accounts?.[0] || gwWcSessionAddress(session);
    if (gwAddrOk(acc)) {
      if (!provider.accounts?.length) provider.accounts = [acc];
      currentAccount = acc;
      try { localStorage.setItem('grom_wallet_label', acc); } catch (_) {}
      if (window.GROM_CONN) {
        window.GROM_CONN.connected = true;
        window.GROM_CONN.label = acc;
        window.GROM_CONN.method = 'wc-signclient';
      }
      try {
        document.dispatchEvent(new CustomEvent('grom:wallet-connected', { detail: { address: acc } }));
      } catch (_) {}
      try { if (typeof window.updateAuthUi === 'function') window.updateAuthUi(); } catch (_) {}
      return provider;
    }
  } catch (e) {
    console.log('[GROM] SignClient restore skipped:', e?.message || e);
  }
  return null;
}

async function gwRestorePersistedWcSession() {
  if (wcProvider?.accounts?.length) return wcProvider;
  return gwRestoreSignClientSession();
}

/** Silent restore for Trust / MetaMask / OKX / Binance / any injected EVM. */
async function gwRestoreInjectedEthereum() {
  try {
    if (localStorage.getItem('grom:logged_out') === '1') return null;
  } catch (_) {}

  const providers = (typeof gwAllInjectedProviders === 'function')
    ? gwAllInjectedProviders()
    : [];
  if (!providers.length) {
    window.__gwInjectedAccountsChecked = true;
    return null;
  }

  const applyRestored = (addr, provider, how) => {
    const a = String(addr || '').trim();
    if (!gwAddrOk(a)) return null;
    currentAccount = a;
    window.__gwInjectedRestored = true;
    window.__gwSoftInjectedProvider = provider || null;
    if (how !== 'soft-label' && provider?.request) {
      window.__gwLiveInjectedProvider = provider;
    }
    try { localStorage.setItem('grom_wallet_label', a); } catch (_) {}
    try { localStorage.removeItem('grom:logged_out'); } catch (_) {}
    if (window.GROM_CONN) {
      window.GROM_CONN.connected = true;
      window.GROM_CONN.label = a;
      if (!window.GROM_CONN.method || window.GROM_CONN.method === 'restored-wallet') {
        window.GROM_CONN.method = how || 'injected';
      }
    }
    try { updateChip(a); } catch (_) {}
    try {
      document.dispatchEvent(new CustomEvent('grom:wallet-connected', {
        detail: { address: a, method: how || 'injected-restore' },
      }));
    } catch (_) {}
    // Re-attach TRX/SOL if the same multi-chain extension still exposes them.
    setTimeout(() => {
      try { gwFanOutSideChains({ toast: false }); } catch (_) {}
    }, 350);
    console.log('[GROM] injected restored via', how || 'eth_accounts', a.slice(0, 10));
    return a;
  };

  /* 1) Live eth_accounts / selectedAddress on every provider (Trust first). */
  const ordered = [];
  try {
    const trust = resolveTrustProvider();
    if (trust) ordered.push(trust);
  } catch (_) {}
  providers.forEach((p) => { if (!ordered.includes(p)) ordered.push(p); });

  for (const eth of ordered) {
    try {
      if (gwAddrOk(eth.selectedAddress)) {
        const hit = applyRestored(eth.selectedAddress, eth, 'selectedAddress');
        if (hit) {
          window.__gwInjectedAccountsChecked = true;
          return hit;
        }
      }
    } catch (_) {}
    try {
      const accs = await eth.request({ method: 'eth_accounts' });
      const a = Array.isArray(accs) ? accs[0] : null;
      if (gwAddrOk(a)) {
        window.__gwInjectedAccountsChecked = true;
        return applyRestored(a, eth, 'eth_accounts');
      }
    } catch (_) {}
  }

  window.__gwInjectedAccountsChecked = true;

  /* 2) Soft restore: Trust/MM still installed but eth_accounts empty after F5.
   * Keep chip + wire provider so the next sign can re-prompt. */
  let label = '';
  try { label = localStorage.getItem('grom_wallet_label') || ''; } catch (_) {}
  if (gwAddrOk(label)) {
    const best = (typeof gwPickBestInjectedProvider === 'function')
      ? gwPickBestInjectedProvider()
      : ordered[0];
    return applyRestored(label, best, 'soft-label');
  }
  return null;
}
try { window.gwRestoreInjectedEthereum = gwRestoreInjectedEthereum; } catch (_) {}

/** Boot: warm-restore injected + WC so chip/swap stay in sync after F5. */
async function gwBootWalletSession() {
  __gwWalletBootUntil = Date.now() + 20000;
  window.__gwBootRestoreDone = false;
  try {
    if (localStorage.getItem('grom:logged_out') === '1') {
      gwSyncRestoredIdentityUi();
      window.__gwBootRestoreDone = true;
      return;
    }
  } catch (_) {}

  /* Always paint saved label first so Trust users never see a flash of "Connect". */
  gwSyncRestoredIdentityUi();

  if (gwHasSigningProvider()) {
    window.__gwBootRestoreDone = true;
    return;
  }

  try { await gwRestoreInjectedEthereum(); } catch (_) {}
  if (gwHasSigningProvider() || window.__gwInjectedRestored) {
    console.log('[GROM] injected session warm-restored');
    gwSyncRestoredIdentityUi();
  }

  /* WC restore even when soft-injected — Trust QR users need SignClient back. */
  if (!wcProvider?.accounts?.length && gwHasPersistedWcSession()) {
    try { await gwRestorePersistedWcSession(); } catch (_) {}
    if (gwHasSigningProvider()) {
      console.log('[GROM] WC session warm-restored');
      gwSyncRestoredIdentityUi();
    }
  } else if (!window.__gwInjectedRestored && gwHasRestoredWalletIdentity()) {
    /* Label without WC keys yet — still try WC in case keys appear late. */
    try { await gwRestorePersistedWcSession(); } catch (_) {}
    gwSyncRestoredIdentityUi();
  }

  window.__gwBootRestoreDone = true;
  gwSyncRestoredIdentityUi();
}

function gwSyncRestoredIdentityUi() {
  const addr = gwDisplayAddress();
  if (addr) {
    if (window.GROM_CONN) {
      window.GROM_CONN.connected = true;
      window.GROM_CONN.label = addr;
      if (!window.GROM_CONN.method) window.GROM_CONN.method = 'restored-wallet';
    }
    /* Soft label only — never invent currentAccount without a live signer.
     * Soft currentAccount made Tron Start show «Confirm in Trust» with zero WC requests. */
    try {
      document.dispatchEvent(new CustomEvent('grom:wallet-address-known', { detail: { address: addr } }));
    } catch (_) {}
  }
  try { if (typeof window.updateAuthUi === 'function') window.updateAuthUi(); } catch (_) {}
  try { gwDsSimRenderBalances(); } catch (_) {}
  try { gwRefreshCombinedPortfolioTotals(); } catch (_) {}
}
window.gwSyncRestoredIdentityUi = gwSyncRestoredIdentityUi;

/* Prefetch WC provider on page load. Only fires when we already have a
 * persisted session — that way we never pop the Reown QR modal
 * unprompted (which was the original bug that led to the skip). Users
 * with an existing session get their provider hot-loaded before the
 * first swap click. */
function gwPrefetchWc() {
  try { if (localStorage.getItem('grom:logged_out') === '1') return; } catch (_) {}
  const kick = () => {
    gwBootWalletSession()
      .catch((e) => console.log('[GROM] WC boot skipped:', e?.message || e))
      .finally(() => { try { gwSyncRestoredIdentityUi(); } catch (_) {} });
  };
  kick();
  if ('requestIdleCallback' in window) requestIdleCallback(kick, { timeout: 1500 });
  else setTimeout(kick, 400);
}

/** More wallets — our wallet explorer (no Reown modal). */
async function connectViaReownExplorer() {
  gwOpenMoreWalletsExplorer();
}

