const TOKEN_DECIMALS = { USDT: 6, USDC: 6 };

/** BSC USDT/USDC use 18 decimals — global 6 would hide balances (e.g. 3 USDT → dust). */
function gwTokenDecimals(chainId, sym) {
  const id = Number(chainId);
  if (id === 56 && (sym === 'USDT' || sym === 'USDC')) return 18;
  return TOKEN_DECIMALS[sym] || 18;
}

async function rpcCall(url, method, params, timeoutMs = 3500) {
  const ctrl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
  const t = ctrl ? setTimeout(() => { try { ctrl.abort(); } catch (_) {} }, timeoutMs) : null;
  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }),
      signal: ctrl ? ctrl.signal : undefined,
    });
    const json = await res.json().catch(() => ({}));
    if (json.error) throw new Error(json.error.message || 'rpc error');
    return json.result;
  } finally {
    if (t) clearTimeout(t);
  }
}

function padAddressData(address) {
  return '0x70a08231' + address.slice(2).toLowerCase().padStart(64, '0');
}

/** Try primary RPC then fallbacks in order until one returns a non-error
 *  response. Prevents "flickering" balance where a rate-limited primary
 *  returned 0x0 for balanceOf() and the UI showed \$0.81 instead of \$3.81. */
async function gwRpcTry(chainId, method, params) {
  const urls = [ONCHAIN_RPC[chainId], ...(ONCHAIN_RPC_FALLBACK[chainId] || [])].filter(Boolean);
  let lastErr;
  for (const url of urls) {
    try {
      const res = await rpcCall(url, method, params);
      // rpcCall throws on JSON-RPC error, so if we're here it's a valid response.
      return res;
    } catch (e) { lastErr = e; }
  }
  throw lastErr || new Error('all RPCs failed');
}

window.gromFetchOnchainBalances = async function gromFetchOnchainBalances(address, chainId) {
  if (!address || !/^0x[a-fA-F0-9]{40}$/.test(address)) return null;
  chainId = Number(chainId || currentChainId || 42161);
  if (!ONCHAIN_RPC[chainId]) return { chainId, nativeEth: null, tokens: {} };

  window.__gwOcBalCache = window.__gwOcBalCache || {};
  const ck = String(chainId) + ':' + address.toLowerCase();
  const cached = window.__gwOcBalCache[ck];
  if (cached && Date.now() - cached.at < 30000) return cached.data;

  window.__gwOcBalInflight = window.__gwOcBalInflight || {};
  if (window.__gwOcBalInflight[ck]) return window.__gwOcBalInflight[ck];

  window.__gwOcBalInflight[ck] = (async () => {
    let nativeEth = 0;
    try {
      const nativeWei = await gwRpcTry(chainId, 'eth_getBalance', [address, 'latest']);
      nativeEth = Number(BigInt(nativeWei || '0x0')) / 1e18;
    } catch (_) { /* leave nativeEth = 0 */ }

    const tokens = {};
    const tokenMap = ONCHAIN_TOKENS[chainId] || {};
    await Promise.all(Object.entries(tokenMap).map(async ([sym, contract]) => {
      try {
        const raw = await gwRpcTry(chainId, 'eth_call', [{ to: contract, data: padAddressData(address) }, 'latest']);
        const dec = gwTokenDecimals(chainId, sym);
        tokens[sym] = Number(BigInt(raw || '0x0')) / (10 ** dec);
      } catch (_) {
        tokens[sym] = 0;
      }
    }));
    const data = { chainId, nativeEth, tokens };
    window.__gwOcBalCache[ck] = { at: Date.now(), data };
    return data;
  })().finally(() => { try { delete window.__gwOcBalInflight[ck]; } catch (_) {} });

  return window.__gwOcBalInflight[ck];
};

/* ----- Wallet connect router (used by index.html cnConnect) ----- */
async function connectPhantomWallet() {
  try { await gwEnsureFeeConfig(); } catch (_) {}
  if (!gwJupiterReady()) {
    try { gwToast('Solana Instant Swap is temporarily unavailable', 'warn'); } catch (_) {}
    throw new Error('Solana Instant Swap unavailable');
  }
  const pk = await gwSolConnect();
  window.__gwSolAddr = pk;
  if (window.GROM_CONN) window.GROM_CONN.method = 'solana';
  gwNotifyWalletConnected(pk, { method: 'solana', toast: true });
  return pk;
}
try { window.connectPhantomWallet = connectPhantomWallet; } catch (_) {}
try { window.gwSolPubkey = gwSolPubkey; } catch (_) {}
async function connectTronWallet() {
  const addr = await gwTronConnect();
  window.__gwTronAddr = addr;
  if (window.GROM_CONN) window.GROM_CONN.method = 'tron';
  gwNotifyWalletConnected(addr, { method: 'tron', toast: true });
  try { gwTronActivateUi(addr); } catch (_) {}
  try { __gwTronBalCache.delete?.(String(addr).trim()); } catch (_) {}
  try { if (typeof gwRenderOnchainCard === 'function') await gwRenderOnchainCard(); } catch (_) {}
  try { if (typeof gwHydrateWalletPageAssets === 'function') await gwHydrateWalletPageAssets(); } catch (_) {}
  try { if (typeof gwRefreshCombinedPortfolioTotals === 'function') await gwRefreshCombinedPortfolioTotals(); } catch (_) {}
  try { if (typeof window.renderConnectedWalletsList === 'function') await window.renderConnectedWalletsList(); } catch (_) {}
  return addr;
}
function gwSetConnectRowsBusy(busy, activeKind) {
  try {
    document.querySelectorAll('#connectModal .cn-list button.cn-row').forEach((btn) => {
      btn.disabled = !!busy;
      btn.classList.toggle('gw-cn-busy', !!busy);
      const kind = (btn.getAttribute('onclick') || '').match(/cnConnect\('(?:[^']*)','([^']+)'/);
      const k = kind?.[1];
      if (busy && k === activeKind) {
        const lbl = btn.querySelector('.lbl');
        if (lbl && !lbl.dataset.prevLbl) {
          lbl.dataset.prevLbl = lbl.textContent || '';
          lbl.textContent = 'Connecting…';
        }
      } else if (!busy) {
        const lbl = btn.querySelector('.lbl');
        if (lbl?.dataset?.prevLbl) {
          lbl.textContent = lbl.dataset.prevLbl;
          delete lbl.dataset.prevLbl;
        }
      }
    });
  } catch (_) {}
}
async function gromWalletConnect(kind, name) {
  // Normalize — never let a missing/wrong kind fall through to EVM WalletConnect.
  const k = String(kind || '').toLowerCase().trim();
  if (!k) {
    console.warn('[GROM] gromWalletConnect called without kind', name);
    return;
  }
  // Stuck busy after cancel/timeout → unblock reconnect without full reload.
  if (window.__gwCnBusy) {
    const stuckMs = Date.now() - (Number(window.__gwCnBusyAt) || 0);
    if (stuckMs > 8000 || !window.__gwCnBusyAt) {
      console.warn('[GROM] clearing stuck connect busy (' + stuckMs + 'ms)');
      gwResetConnectBusyFlags();
    } else {
      return;
    }
  }
  try { localStorage.removeItem('grom:logged_out'); } catch (_) {}
  window.__gwCnBusy = true;
  window.__gwCnBusyAt = Date.now();
  gwSetConnectRowsBusy(true, k);
  if (k === 'tron' || k === 'phantom' || k === 'wc' || k === 'ghost') {
    try { if (typeof window.closeConnectModal === 'function') window.closeConnectModal(); } catch (_) {}
    try {
      if (typeof window.toast === 'function' && k !== 'tron') {
        window.toast(
          k === 'phantom' ? 'Connecting Phantom…'
              : 'Opening wallet…',
          'info',
        );
      }
    } catch (_) {}
  }
  if (k === 'tron') {
    try { gwKillReownModals(); } catch (_) {}
  }
  try {
    if (k === 'mm') await connectMetaMask();
    else if (k === 'trust') await connectTrust();
    else if (k === 'bnw3') await connectBinanceWeb3();
    else if (k === 'okx') await connectOkx();
    else if (k === 'cb') await connectCoinbase();
    else if (k === 'phantom') await connectPhantomWallet();
    else if (k === 'tron') await connectTronWallet();
    else if (k === 'wc' || k === 'ghost') await connectWC();
    else {
      console.warn('[GROM] unknown wallet kind — not opening EVM WC:', k, name);
      throw new Error('Unknown wallet: ' + (name || k));
    }
  } catch (e) {
    failToast(e);
  } finally {
    window.__gwCnBusy = false;
    window.__gwCnBusyAt = 0;
    gwSetConnectRowsBusy(false);
  }
}

/* ----- Hook chip disconnect ----- */
function hook() {
  window.gromWalletConnect = gromWalletConnect;

  // Disconnect при повторном клике на чип
  window.disconnectWallet = disconnect;

  // Bridge: disconnect() fires 'wallet-disconnected' on WINDOW, but every
  // injected widget (Meta-Portfolio, Simple-swap balances, Referral) listens
  // for 'grom:wallet-disconnected' on DOCUMENT. Without this bridge the
  // on-chain balance stays on screen until a full page refresh.
  window.addEventListener('wallet-disconnected', () => {
    try { document.dispatchEvent(new CustomEvent('grom:wallet-disconnected')); } catch (_) {}
    // Defer heavy re-renders so logout feels instant on mobile.
    const kick = () => {
      try { gwDsSimRenderBalances(); } catch (_) {}
    };
    if (typeof requestAnimationFrame === 'function') requestAnimationFrame(() => setTimeout(kick, 0));
    else setTimeout(kick, 0);
  });

  // Boot: sync UI immediately. WC 2.4MB libs only when session/JWT/device-SIWE —
  // cold chart viewers must not pay that cost. Connect modal forces via {force:true}.
  __gwWalletBootUntil = Date.now() + 20000;
  gwSyncRestoredIdentityUi();
  /* Always try silent restore when a label or any injected wallet exists. */
  try {
    const needInject = !!(
      localStorage.getItem('grom_wallet_label')
      || window.ethereum
      || window.trustwallet
      || (typeof gwAllInjectedProviders === 'function' && gwAllInjectedProviders().length)
    );
    if (needInject && localStorage.getItem('grom:logged_out') !== '1') {
      gwRestoreInjectedEthereum().then((a) => {
        if (a) gwSyncRestoredIdentityUi();
      }).catch(() => {});
      /* Trust / EIP-6963 often announce late — retry twice. */
      setTimeout(() => {
        gwRestoreInjectedEthereum().then((a) => { if (a) gwSyncRestoredIdentityUi(); }).catch(() => {});
      }, 1200);
      setTimeout(() => {
        gwRestoreInjectedEthereum().then((a) => { if (a) gwSyncRestoredIdentityUi(); }).catch(() => {});
      }, 3500);
    }
  } catch (_) {}
  if (gwShouldWarmWcLibs()) {
    gwPrefetchWc();
    gwPrefetchWcLibs({ force: true });
  } else {
    /* Still warm SignClient + QR lib so first Trust click isn't a cold 3–6s wait. */
    try {
      const warm = () => {
        try { gwPrefetchSignClient({ force: true }); } catch (_) {}
        try { gwLoadQrLib().catch(function () {}); } catch (_) {}
      };
      if ('requestIdleCallback' in window) requestIdleCallback(warm, { timeout: 900 });
      else setTimeout(warm, 200);
    } catch (_) {}
  }

  // Подписка на сетевые ивенты window.ethereum (если юзер подключал ранее)
  try {
    const best = typeof gwPickBestInjectedProvider === 'function' ? gwPickBestInjectedProvider() : window.ethereum;
    const addr = best?.selectedAddress || window.ethereum?.selectedAddress;
    if (addr) updateChip(addr);
  } catch (_) {}

  console.log('[grom-wallet] ready · project:', WC_PROJECT_ID.slice(0, 8) + '…');
  try { window.__gromWalletReadyResolve?.(); } catch (_) {}
  try { gwInjectMobilePerfCss(); } catch (_) {}
  try { gwInjectDexPagesCss(); } catch (_) {}
}

