/* Native token addresses on each EVM chain (for native send vs ERC-20).
 * ERC-20 contract addresses for USDT/USDC by chain.
 * For Send: ETH/BNB/MATIC/AVAX etc are native; USDT/USDC are ERC-20 calls. */
const GROM_ERC20 = {
  ETH:      { USDT: '0xdAC17F958D2ee523a2206206994597C13D831ec7', USDC: '0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48' },
  ARBITRUM: { USDT: '0xFd086bC7CD5C481DCC9C85ebE478A1C0b69FCbb9', USDC: '0xaf88d065e77c8cC2239327C5EDb3A432268e5831' },
  OPTIMISM: { USDT: '0x94b008aA00579c1307B0EF2c499aD98a8ce58e58', USDC: '0x0b2c639c533813f4aa9d7837caf62653d097ff85' },
  POLYGON:  { USDT: '0xc2132D05D31c914a87C6611C10748AEb04B58e8F', USDC: '0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359' },
  BASE:     { USDC: '0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913', USDT: '0xfde4C96c8593536E31F229EA8f37b2ADa2699bb2' },
  BSC:      { USDT: '0x55d398326f99059fF775485246999027B3197955', USDC: '0x8AC76a51cc950d9822D68b83fE1Ad97B32Cd580d' },
  AVAXC:    { USDT: '0x9702230A8Ea53601f5cD2dc00fDBc13d4dF4A8c7', USDC: '0xB97EF9Ef8734C71904D8002F8b6Bc66Dd9c48a6E' },
};

/* Helpers ----------------------------------------------------------------- */

/** Alias → account-aware signing provider (never prefer stale WC over active injected). */
function gwActiveEvmProvider() {
  if (typeof gwActiveSigningProvider === 'function') return gwActiveSigningProvider();
  try {
    if (window.gromWallet?.provider) return window.gromWallet.provider;
  } catch (_) {}
  return window.ethereum || null;
}
try { window.gwActiveEvmProvider = gwActiveEvmProvider; } catch (_) {}

function gwToast(msg, type) {
  if (typeof window.toast === 'function') return window.toast(msg, type || 'info');
  console.log('[grom-toast]', type || 'info', msg);
}
function gwUserAddress() {
  try { return (currentAccount || localStorage.getItem('grom_wallet_label') || '').toString(); }
  catch (_) { return ''; }
}
function gwFmtAmount(n, dp) {
  const v = Number(n);
  if (!Number.isFinite(v)) return '0';
  return v.toFixed(dp ?? 6).replace(/\.?0+$/, '');
}

/* === SEND pane: on-chain transfer via window.ethereum ==================== */
/* Per-chain per-asset ERC-20 decimals. USDT on BSC is 18 dp, on Ethereum 6 dp
 * — the classic footgun. USDC follows the same pattern. Native tokens are
 * always 18. */
const GW_SEND_DECIMALS = {
  ETH:       { USDT: 6, USDC: 6, DAI: 18, WBTC: 8 },
  BSC:       { USDT: 18, USDC: 18, BUSD: 18, ETH: 18, BTC: 18, CAKE: 18 },
  ARBITRUM:  { USDT: 6, USDC: 6, DAI: 18 },
  POLYGON:   { USDT: 6, USDC: 6, DAI: 18, WBTC: 8 },
  BASE:      { USDC: 6 },
  OPTIMISM:  { USDT: 6, USDC: 6 },
  AVAXC:     { USDT: 6, USDC: 6 },
};
const GW_NATIVE_FOR = { ETH: 'ETH', ARBITRUM: 'ETH', BASE: 'ETH', OPTIMISM: 'ETH', BSC: 'BNB', POLYGON: 'MATIC', AVAXC: 'AVAX' };

async function gwSubmitSend() {
  const asset = String(document.getElementById('wmSendAsset')?.value || 'USDT').toUpperCase();
  const to = String(document.getElementById('wmSendTo')?.value || '').trim();
  const amtStr = String(document.getElementById('wmSendAmt')?.value || '').trim();
  if (!to || !amtStr) { gwToast('Recipient and amount required', 'warn'); return; }
  if (!/^0x[a-fA-F0-9]{40}$/.test(to)) {
    gwToast('Send currently supports EVM 0x… addresses only', 'warn'); return;
  }
  if (!/^\d+(\.\d+)?$/.test(amtStr) || /^0+(\.0+)?$/.test(amtStr)) {
    gwToast('Invalid amount', 'warn'); return;
  }

  const provider = (typeof gwActiveSigningProvider === 'function')
    ? gwActiveSigningProvider()
    : ((window.gromWallet?.wcProvider && window.gromWallet.wcProvider.accounts?.[0])
      ? window.gromWallet.wcProvider
      : window.ethereum);
  if (!provider) { gwPromptSignIn('Connect MetaMask / Trust / WalletConnect to send.'); return; }
  const accounts = await provider.request({ method: 'eth_accounts' }).catch(() => []);
  const from = String(accounts?.[0] || '').toLowerCase();
  if (!accounts?.length || !/^0x[a-f0-9]{40}$/.test(from)) {
    gwToast('Active wallet has no accounts — reconnect and retry', 'warn'); return;
  }

  try {
    const chainHex = await provider.request({ method: 'eth_chainId' });
    const chainKey = Object.entries(GROM_NETWORKS).find(([k, v]) => v.hex === chainHex && v.kind === 'evm')?.[0];
    if (!chainKey) {
      gwToast(`Unsupported or non-EVM chain ${chainHex}. Switch network in your wallet.`, 'warn');
      return;
    }

    let txParams;
    const nativeSym = GW_NATIVE_FOR[chainKey] || 'ETH';
    if (asset === nativeSym) {
      const wei = (typeof gwAmtToBaseUnits === 'function'
        ? gwAmtToBaseUnits(amtStr, 18)
        : gwParseAmountToUnits(amtStr, 18, { truncate: true }));
      txParams = { from, to, value: '0x' + wei.toString(16) };
    } else {
      const erc20 = (GROM_ERC20[chainKey] || {})[asset];
      if (!erc20) {
        gwToast(`${asset} is not available for Send on ${chainKey}. Pick an EVM token on this network.`, 'warn');
        return;
      }
      const dec = (GW_SEND_DECIMALS[chainKey] || {})[asset] || 18;
      const units = (typeof gwAmtToBaseUnits === 'function'
        ? gwAmtToBaseUnits(amtStr, dec)
        : gwParseAmountToUnits(amtStr, dec, { truncate: true }));
      const sel4 = 'a9059cbb';
      const addr32 = to.toLowerCase().replace(/^0x/, '').padStart(64, '0');
      const amt32 = units.toString(16).padStart(64, '0');
      txParams = { from, to: erc20, data: '0x' + sel4 + addr32 + amt32, value: '0x0' };
    }
    gwToast('Confirm the transaction in your wallet…', 'info');
    const hash = await provider.request({ method: 'eth_sendTransaction', params: [txParams] });
    gwToast(`Submitted — waiting for confirmation… ${String(hash).slice(0, 12)}…`, 'info');
    try { await gwWaitReceipt(provider, hash, 120000); gwToast('✓ Sent. Confirmed on-chain.', 'success'); }
    catch (_) { gwToast(`Sent (still propagating): ${String(hash).slice(0, 12)}…`, 'info'); }
    if (typeof window.closeWalletModal === 'function') window.closeWalletModal();
    setTimeout(() => {
      try { window.gromFetchOnchainBalances?.(from, parseInt(chainHex, 16)); } catch (_) {}
      try { document.dispatchEvent(new CustomEvent('grom:wallet-connected', { detail: { address: from } })); } catch (_) {}
    }, 3000);
  } catch (e) {
    console.warn('[grom-send] failed:', e);
    const msg = String(e?.message || e || '').toLowerCase();
    if (msg.includes('reject') || msg.includes('denied') || e?.code === 4001) {
      gwToast('You cancelled the transaction', 'warn');
    } else if (msg.includes('insufficient funds')) {
      gwToast('Insufficient balance (or not enough for gas)', 'error');
    } else {
      gwToast(e?.message || 'Send failed', 'error');
    }
  }
}

/* Sign-in prompt: open connect modal when JWT/session needed. */
function gwPromptSignIn(message) {
  try {
    if (typeof window.closeWalletModal === 'function') window.closeWalletModal();
  } catch (_) {}
  // Wallet already connected → SIWE immediately (no "Sign in first" wall).
  (async () => {
    const ok = await gwEnsureSignedIn({
      rejectToast: message || 'Sign in required to continue.',
    });
    if (!ok && !gwJwtValid()) {
      try { gwToast(message || 'Sign in required to continue.', 'warn'); } catch (_) {}
    }
  })();
}

function gwExpandAssetSelect(id) {
  const sel = document.getElementById(id);
  if (!sel) return;
  const present = new Set(Array.from(sel.options).map(o => o.value));
  for (const a of GW_SUPPORTED_ASSETS) {
    if (present.has(a)) continue;
    const o = document.createElement('option');
    o.value = a; o.textContent = a;
    sel.appendChild(o);
  }
}
function gwActiveChainKey() {
  try {
    const cid = Number(typeof gwGetActiveUiChainId === 'function' ? gwGetActiveUiChainId() : 0)
      || Number(window.gromWallet?.chainId || 0)
      || Number(typeof currentChainId !== 'undefined' ? currentChainId : 0);
    const map = {
      1: 'ETH', 42161: 'ARBITRUM', 10: 'OPTIMISM', 137: 'POLYGON',
      8453: 'BASE', 56: 'BSC', 43114: 'AVAXC',
    };
    if (map[cid]) return map[cid];
    if (typeof GROM_NETWORKS === 'object') {
      for (const [k, v] of Object.entries(GROM_NETWORKS)) {
        if (Number(v?.chainId) === cid || Number(v?.id) === cid) return k;
      }
    }
  } catch (_) {}
  return String(window.gromWallet?.chainKey || 'ETH').toUpperCase();
}
try { window.gwActiveChainKey = gwActiveChainKey; } catch (_) {}

function gwSendAssetsForActiveChain() {
  const chainKey = (typeof gwActiveChainKey === 'function')
    ? gwActiveChainKey()
    : (window.gromWallet?.chainKey || 'ETH');
  const key = String(chainKey || 'ETH').toUpperCase();
  const native = GW_NATIVE_FOR[key] || 'ETH';
  const erc = Object.keys(GROM_ERC20[key] || {});
  return [native, ...erc.filter((s) => s !== native)];
}
function gwExpandSendSwapDropdowns() {
  /* Send: EVM-only assets for active chain — never rehydrate BTC into wmSendAsset */
  const sendSel = document.getElementById('wmSendAsset');
  if (sendSel) {
    const assets = gwSendAssetsForActiveChain();
    const keep = new Set(assets);
    Array.from(sendSel.options).forEach((o) => {
      if (!keep.has(String(o.value || o.textContent).toUpperCase())) o.remove();
    });
    const present = new Set(Array.from(sendSel.options).map((o) => String(o.value || o.textContent).toUpperCase()));
    for (const a of assets) {
      if (present.has(a)) continue;
      const opt = document.createElement('option');
      opt.value = a; opt.textContent = a;
      sendSel.appendChild(opt);
    }
  }
  gwExpandAssetSelect('wmSwapFrom');
  gwExpandAssetSelect('wmSwapTo');
}
try { window.gwSendAssetsForActiveChain = gwSendAssetsForActiveChain; } catch (_) {}


