function gwTgLang() { let l='en'; try { const s=localStorage.getItem('grom_lang'); if (s&&GW_TG_TR[s]) l=s; } catch (_) {} return GW_TG_TR[l]||GW_TG_TR.en; }
const GW_TG_URL = 'https://t.me/grom_finence_hub';

