function gwOcLang() {
  let l = 'en';
  try {
    const s = localStorage.getItem('grom_lang');
    if (s && GW_OC_TR[s]) l = s;
  } catch (_) {}
  return GW_OC_TR[l] || GW_OC_TR.en;
}
function gwOcT(key) {
  const pack = gwOcLang();
  return pack[key] || GW_OC_TR.en[key] || key;
}

/** Balances under this are dust — foldable so BSC 0.003 BNB stops eating the card. */
const GW_OC_DUST_USD = 1;
const GW_OC_DUST_KEY = 'grom_oc_hide_small';
function gwOcHideSmall(next) {
  if (next !== undefined) {
    try { localStorage.setItem(GW_OC_DUST_KEY, next ? '1' : '0'); } catch (_) {}
    return !!next;
  }
  try {
    const raw = localStorage.getItem(GW_OC_DUST_KEY);
    /* Default on: a fresh wallet reads cleaner without sub-$1 leftovers. */
    return raw == null ? true : raw === '1';
  } catch (_) {
    return true;
  }
}

/** Sub-$1 is dust. A real TRON holding with no USD price (SUN) is not dust. */
function gwOcIsDust(it) {
  const usd = Number(it && it.usd) || 0;
  const amt = Number(it && it.amt) || 0;
  const sym = String((it && it.sym) || '').toUpperCase();
  let tronSym = sym === 'TRX';
  try {
    if (!tronSym && typeof GW_TRON_TOKENS !== 'undefined' && GW_TRON_TOKENS) {
      tronSym = Object.prototype.hasOwnProperty.call(GW_TRON_TOKENS, sym);
    }
  } catch (_) {}
  if (tronSym && !(usd > 0) && amt > 0.0001) return false;
  return usd + 1e-9 < GW_OC_DUST_USD;
}

async function gwRenderOnchainCard() {
  const page = document.getElementById('page-wallet');
  if (!page) return;
  gwInjectOnchainCardCss();

  let card = document.getElementById('gwOnchainCard');
  if (!card) {
    card = document.createElement('div');
    card.className = 'gw-oc-card';
    card.id = 'gwOnchainCard';
    // Insert AFTER wallet-hero so it sits between hero and ops-grid.
    const hero = page.querySelector('.wallet-hero');
    if (hero && hero.parentNode) hero.after(card);
    else page.prepend(card);
  }

  const addr = gwOcConnectedAddress();
  const tronAddr = (typeof gwTronSavedAddr === 'function')
    ? gwTronSavedAddr()
    : (window.__gwTronAddr || (() => { try { return localStorage.getItem('grom_tron_addr') || ''; } catch (_) { return ''; } })());
  const hasEvm = !!(addr && /^0x[a-fA-F0-9]{40}$/i.test(addr));
  const hasTron = !!(tronAddr && /^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(tronAddr));
  if (!hasEvm && !hasTron) {
    card.innerHTML = `
      <div class="gw-oc-head">
        <div>
          <p class="gw-oc-title">${gwOcT('title')}</p>
          <p class="gw-oc-total">—</p>
        </div>
      </div>
      <div class="gw-oc-empty">${gwOcT('empty')}</div>
    `;
    return;
  }

  const labelAddr = hasEvm ? addr : tronAddr;
  const short = labelAddr.slice(0, 6) + '…' + labelAddr.slice(-4);
  card.innerHTML = `
    <div class="gw-oc-head">
      <div>
        <p class="gw-oc-title">${gwOcT('title')}</p>
        <p class="gw-oc-total" id="gwOcTotal">—</p>
        <p class="gw-oc-addr">${short}${hasEvm && hasTron ? ' · +TRON' : (hasTron ? ' · TRON' : '')}</p>
      </div>
      <button type="button" class="gw-oc-refresh" id="gwOcRefresh">${gwOcT('refresh')}</button>
    </div>
    <div class="gw-oc-loading">${gwOcT('loading')}</div>
  `;
  document.getElementById('gwOcRefresh')?.addEventListener('click', gwRenderOnchainCard);

  try {
    const prices = await gwOcFetchPrices().catch(() => ({ USDT: 1, USDC: 1 }));
    const chains = hasEvm ? await gwOcFetchAllChains(addr).catch(() => []) : [];
    let totalUsd = 0;
    /* Collect structured groups first: the card sorts by USD and can fold dust,
     * which is impossible once rows are HTML strings. */
    const groups = [];
    const fmtAmt = (sym, amt) => {
      const n = Number(amt) || 0;
      if (sym === 'TRX' || sym === 'ETH' || sym === 'BNB' || sym === 'AVAX' || sym === 'MATIC') {
        return n.toFixed(n >= 1 ? 4 : 6);
      }
      if (n >= 1000) return n.toLocaleString('en-US', { maximumFractionDigits: 2 });
      if (n >= 1) return n.toLocaleString('en-US', { maximumFractionDigits: 4 });
      return n.toLocaleString('en-US', { maximumFractionDigits: 6 });
    };
    const fmtUsd = (usd) => {
      const n = Number(usd) || 0;
      if (n < 0.005) return '< $0.01';
      return '$' + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    };

    for (const c of chains) {
      if (!c.data) continue;
      const items = [];
      let chainUsd = 0;
      // Native token
      if (c.data.nativeEth != null && c.data.nativeEth > 0.0000001) {
        const sym = c.meta.native;
        const amt = Number(c.data.nativeEth);
        const usd = amt * (prices[sym] || 0);
        chainUsd += usd;
        items.push({ sym, amt, usd });
      }
      // ERC-20s
      for (const [sym, amtRaw] of Object.entries(c.data.tokens || {})) {
        const amt = Number(amtRaw);
        if (!(amt > 0.0001)) continue;
        const usd = amt * (prices[sym] || 0);
        chainUsd += usd;
        items.push({ sym, amt, usd });
      }
      if (items.length === 0) continue;
      totalUsd += chainUsd;
      groups.push({ label: c.meta.label, usd: chainUsd, items });
    }

    if (hasTron && typeof gwTronFetchAllBalances === 'function') {
      try {
        const tRows = await gwTronFetchAllBalances(tronAddr);
        const items = [];
        let chainUsd = 0;
        for (const tr of tRows) {
          const amt = Number(tr.amt) || 0;
          const px = (tr.sym === 'USDT' || tr.sym === 'USDC') ? 1 : (prices[tr.sym] || 0);
          const usd = amt * px;
          chainUsd += usd;
          items.push({ sym: tr.sym, amt, usd });
        }
        if (items.length) {
          totalUsd += chainUsd;
          groups.push({ label: 'TRON', usd: chainUsd, items });
        }
      } catch (_) {}
    }

    groups.sort((a, b) => b.usd - a.usd);
    groups.forEach((g) => g.items.sort((a, b) => b.usd - a.usd));

    const hideSmall = gwOcHideSmall();
    const groupKept = (g) => (g.usd + 1e-9 >= GW_OC_DUST_USD) || g.items.some((it) => !gwOcIsDust(it));
    const bigGroups = groups.filter(groupKept);
    const dustGroups = groups.filter((g) => !groupKept(g));
    const visible = hideSmall ? bigGroups : groups;
    let dustCount = dustGroups.length;
    const rows = visible.map((g) => {
      const shownItems = hideSmall ? g.items.filter((it) => !gwOcIsDust(it)) : g.items;
      const hiddenN = g.items.length - shownItems.length;
      dustCount += hiddenN;
      const tokRows = (shownItems.length ? shownItems : g.items).map((it) => {
        const dust = gwOcIsDust(it) ? ' gw-oc-dust' : '';
        return `<div class="gw-oc-tok-row${dust}">
          <span class="gw-oc-tok-sym">${it.sym}</span>
          <span class="gw-oc-tok-amt">${fmtAmt(it.sym, it.amt)}</span>
          <span class="gw-oc-tok-usd">${fmtUsd(it.usd)}</span>
        </div>`;
      }).join('');
      const more = hiddenN > 0 && shownItems.length
        ? `<div class="gw-oc-tok-more">+${hiddenN} ${gwOcT('small')}</div>`
        : '';
      return `
        <div class="gw-oc-chain">
          <div class="gw-oc-chain-head">
            <span class="gw-oc-chain-name">${g.label}</span>
            <span class="gw-oc-chain-usd">≈ $${g.usd.toFixed(2)}</span>
          </div>
          <div class="gw-oc-toks">${tokRows}${more}</div>
        </div>
      `;
    });

    const list = rows.length
      ? `<div class="gw-oc-list">${rows.join('')}</div>`
      : `<div class="gw-oc-empty">${hideSmall && groups.length ? gwOcT('allSmall') : gwOcT('noBal')}</div>`;

    const netHint = hasEvm && hasTron ? 'EVM + TRON' : (hasTron ? 'TRON' : gwOcT('netsEvm'));
    const toggle = (groups.length && (dustCount > 0 || hideSmall))
      ? `<button type="button" class="gw-oc-dust-btn" id="gwOcDustToggle">${
        hideSmall ? gwOcT('showSmall') : gwOcT('hideSmall')
      }${dustCount > 0 ? ` (${dustCount})` : ''}</button>`
      : '';
    card.innerHTML = `
      <div class="gw-oc-head">
        <div>
          <p class="gw-oc-title">${gwOcT('title')}</p>
          <p class="gw-oc-total">$${totalUsd.toFixed(2)}</p>
          <p class="gw-oc-addr">${short} · ${netHint}</p>
        </div>
        <div class="gw-oc-actions">
          ${toggle}
          <button type="button" class="gw-oc-refresh" id="gwOcRefresh">${gwOcT('refresh')}</button>
        </div>
      </div>
      ${list}
    `;
    document.getElementById('gwOcRefresh')?.addEventListener('click', gwRenderOnchainCard);
    document.getElementById('gwOcDustToggle')?.addEventListener('click', () => {
      gwOcHideSmall(!hideSmall);
      gwRenderOnchainCard();
    });
    gwRefreshCombinedPortfolioTotals().catch(() => {});
  } catch (e) {
    card.querySelector('.gw-oc-loading')?.classList.remove('gw-oc-loading');
    const err = document.createElement('div');
    err.className = 'gw-oc-empty';
    err.textContent = gwOcT('err');
    card.appendChild(err);
  }
}

