function gwDsLang() {
  let lang = 'en';
  try {
    if (typeof window.getGromLang === 'function') {
      const g = window.getGromLang();
      if (g && GW_DS_TR[g]) return GW_DS_TR[g];
    }
    const stored = localStorage.getItem('grom_lang');
    if (stored && GW_DS_TR[stored]) lang = stored;
    else {
      const nav = (navigator.language || '').toLowerCase();
      for (const code of Object.keys(GW_DS_TR)) if (nav.indexOf(code) === 0) { lang = code; break; }
    }
  } catch (e) {}
  return GW_DS_TR[lang] || GW_DS_TR.en;
}

/* ==========================================================================
 * Simple mode for the Instant Swap panel — 2026-07-10
 *
 * Balance-first swap UX. When active:
 *   - Real wallet balances shown at top (multi-chain aggregate)
 *   - Click a balance -> auto-select chain + set as YOU PAY token
 *   - Suggested swap targets appear (same-chain quick + cross-chain popular)
 *   - Classic YOU PAY / YOU GET / chain chips row hidden via CSS
 *   - CTA + recent swaps at the bottom continue to work
 * Advanced mode restores the current full manual UX.
 * ========================================================================== */
function gwSwapModeGet() {
  /* The swap card now has one clear flow; keep this accessor for old callers. */
  return 'advanced';
}
function gwSwapModeSet(m) {
  try { localStorage.removeItem('gw_swap_mode'); } catch (_) {}
  document.querySelectorAll('.gw-ds-wrap').forEach((w) => w.classList.remove('gw-ds-mode-simple'));
  document.querySelectorAll('.gw-ds-mode-tabs, #gwDsSimple').forEach((el) => el.remove());
}

/**
 * Open Instant Swap (Advanced) with YOU RECEIVE pre-set to a venue collateral
 * token — e.g. Polygon USDC (Predict) or Arbitrum USDC (Hyperliquid perps).
 * FROM is auto-picked from any wallet holding (any chain) via LiFi.
 *
 * opts: { toSym, toChainId, toAddress, toDecimals, amountUsd?, hint?, forceBridge?, source? }
 */
async function gwOpenTargetSwap(opts) {
  opts = opts || {};
  const toSym = String(opts.toSym || 'USDC').toUpperCase();
  const toChainId = Number(opts.toChainId) || 0;
  const toAddress = opts.toAddress || '';
  const toDecimals = opts.toDecimals != null ? Number(opts.toDecimals) : 6;
  const wantUsd = Number(opts.amountUsd) > 0 ? Number(opts.amountUsd) : 25;
  const forceBridge = opts.forceBridge !== false && toChainId > 0;
  const fundSource = String(opts.source || (toChainId === 42161 ? 'futures' : (toChainId === 137 ? 'predict' : 'swap')));
  const gen = (window.__gwDsPredictFundGen = (window.__gwDsPredictFundGen || 0) + 1);

  try { gwSwapModeSet('advanced'); } catch (_) {}
  try { if (typeof gwDsSetMode === 'function') gwDsSetMode('onchain'); } catch (_) {}
  try {
    if (forceBridge) {
      window.__gwDsForceBridgeTo = {
        chainId: toChainId, sym: toSym, at: Date.now(), amountUsd: wantUsd,
        source: fundSource,
      };
    } else {
      window.__gwDsForceBridgeTo = null;
    }
    window.__gwDsUserPickedTo = {
      sym: toSym, chainId: toChainId || null,
      address: toAddress || null, decimals: toDecimals,
      name: toSym, at: Date.now(),
    };
    window.__gwDsUserPickedFrom = { sym: '', chainId: null, at: Date.now() };
  } catch (_) {}

  try {
    if (typeof window.show === 'function') window.show('dashboard');
    else if (location.hash !== '#dashboard') location.hash = '#dashboard';
  } catch (_) {
    try { location.hash = '#dashboard'; } catch (__) {}
  }

  const apply = async () => {
    if (gen !== window.__gwDsPredictFundGen) return;
    try {
      if (typeof gwInjectDashSwapPanel === 'function') gwInjectDashSwapPanel();
      try { gwSwapModeSet('advanced'); } catch (_) {}
      if (typeof gwDsEnsureSimpleUi === 'function') gwDsEnsureSimpleUi();
      try { gwSwapModeSet('advanced'); } catch (_) {}

      if (typeof gwDsEnsureTokenOption === 'function') {
        gwDsEnsureTokenOption(toSym, {
          sym: toSym, chainId: toChainId || undefined,
          address: toAddress || undefined, decimals: toDecimals,
        });
      }

      /* Pay with whatever the wallet holds — skip dust; need ~35%+ of target USD.
       * Wait for holdings first — otherwise pick falls back before Base USDC appears
       * and we quote leftover mainnet ETH instead of the venue-sized USDC bag. */
      let fromSym = 'USDC';
      let fromChain = null;
      try {
        if (typeof gwTkLoadHoldings === 'function') {
          await Promise.race([
            gwTkLoadHoldings(true),
            new Promise((r) => setTimeout(r, 4000)),
          ]);
        }
      } catch (_) {}
      try {
        const hit = (typeof gwDsPickBestPayHolding === 'function')
          ? await gwDsPickBestPayHolding({
            minUsd: Math.max(1.5, wantUsd * 0.35),
            preferDestSym: toSym,
            /* Prefer liquid pay hubs, but never force ETH mainnet over a
             * ready USDC balance on Base/BSC (that sent HL fund as dust ETH). */
            preferChainId: 0,
            excludeChainIds: forceBridge && toChainId ? [toChainId] : [],
            amountUsd: wantUsd,
          })
          : null;
        if (hit && hit.sym) {
          fromSym = hit.sym;
          fromChain = hit.chainId || null;
        }
      } catch (_) {}

      /* Same-asset on dest chain is fine for forceBridge (USDC BSC → USDC Polygon).
       * Without forceBridge, avoid FROM===TO on same asset unless bridging. */
      if (fromSym === toSym && !forceBridge) {
        try {
          const alt = await gwDsPickBestPayHolding({
            minUsd: 0.5,
            excludeSyms: [toSym],
            amountUsd: wantUsd,
          });
          if (alt?.sym) { fromSym = alt.sym; fromChain = alt.chainId || null; }
        } catch (_) {}
      }

      window.__gwDsUserPickedFrom = { sym: fromSym, chainId: fromChain, at: Date.now() };
      try {
        const srcChain = fromChain || await gwDsBestChainForToken(fromSym);
        if (srcChain) {
          gwDsSetActiveChain(srcChain);
          window.__gwDsUserPickedFrom.chainId = srcChain;
        }
      } catch (_) {}
      const fromEl = document.getElementById('gwDsFrom');
      const toEl = document.getElementById('gwDsTo');
      if (fromEl) fromEl.value = fromSym;
      if (toEl) toEl.value = toSym;
      try { if (typeof gwTkSyncButton === 'function') { gwTkSyncButton('from'); gwTkSyncButton('to'); } } catch (_) {}

      let tokenAmt = wantUsd;
      try {
        if (typeof gwDsAvailableAmount === 'function') {
          const bal = await gwDsAvailableAmount(fromSym, { chainId: fromChain || undefined });
          if (gen !== window.__gwDsPredictFundGen) return;
          /* Ignore dust on the wrong chain — bal≈1e-6 used to overwrite $7 HL fund. */
          const balOk = bal > 0 && !(wantUsd > 0 && bal < Math.min(wantUsd * 0.05, 0.5));
          if (balOk) {
            if (fromSym === 'USDT' || fromSym === 'USDC' || fromSym === 'DAI' || fromSym === 'BUSD') {
              if (tokenAmt > bal) tokenAmt = bal;
            } else {
              const px = (typeof gwDsPriceUsd === 'function') ? await gwDsPriceUsd(fromSym) : 0;
              tokenAmt = (px > 0) ? Math.min(bal, wantUsd / px) : Math.min(bal, bal * 0.25);
            }
          } else if (!(bal > 0)) {
            /* Don't drop $10 into the ETH amount field (10 ETH). Stables are 1:1 USD. */
            if (/^(USDT|USDC|DAI|BUSD)$/i.test(fromSym)) {
              tokenAmt = wantUsd > 0 ? wantUsd : 0;
            } else {
              const px = (typeof gwDsPriceUsd === 'function') ? await gwDsPriceUsd(fromSym) : 0;
              tokenAmt = (px > 0 && wantUsd > 0) ? wantUsd / px : 0;
            }
          }
        }
      } catch (_) {}

      const sim = document.getElementById('gwDsSimAmt');
      const ds = document.getElementById('gwDsAmt');
      const canon = tokenAmt > 0
        ? (typeof gwDsFormatAmtHuman === 'function'
          ? gwDsFormatAmtHuman(tokenAmt, 8)
          : String(Number(tokenAmt.toFixed(8)).toFixed(8).replace(/0+$/, '').replace(/\.$/, '')))
        : '';
      if (sim) {
        sim.readOnly = false; sim.disabled = false;
        sim.value = canon;
        try {
          if (tokenAmt > 0) {
            sim.dataset.max = String(tokenAmt);
            sim.dataset.maxSym = fromSym;
            sim.dataset.maxCid = String(fromChain || '');
          }
        } catch (_) {}
      }
      if (ds) {
        ds.readOnly = false; ds.disabled = false;
        ds.value = canon;
      }
      try { if (typeof gwDsRefreshBalances === 'function') gwDsRefreshBalances(); } catch (_) {}
      try { if (typeof gwDsRefreshRate === 'function') gwDsRefreshRate(); } catch (_) {}
      const wrap = document.querySelector('.gw-ds-wrap');
      if (wrap) wrap.scrollIntoView({ behavior: 'smooth', block: 'start' });

      const hint = opts.hint
        || (`Advanced swap · YOU RECEIVE ${toSym}`
          + (toChainId ? (' on ' + ((typeof gwChainLabel === 'function') ? gwChainLabel(toChainId) : toChainId)) : ''));
      try {
        if (typeof window.notify === 'function') window.notify(hint, 'info');
        else if (typeof gwToast === 'function') gwToast(hint, 'info');
      } catch (_) {}
    } catch (e) {
      console.warn('[GROM] gwOpenTargetSwap', e);
    }
  };

  setTimeout(() => { apply().catch(() => {}); }, 350);
  return { gen, toSym, toChainId };
}
try { window.gwOpenTargetSwap = gwOpenTargetSwap; } catch (_) {}
