/** Bitcoin address validation with Base58Check + Bech32/Bech32m (F11). */
function gwBtcSha256Sync(bytes) {
  // Minimal SHA-256 for address checksums (sync; no SubtleCrypto).
  const K = new Uint32Array([
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2,
  ]);
  const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  const bitLen = u8.length * 8;
  const withPad = new Uint8Array(((u8.length + 9 + 63) & ~63));
  withPad.set(u8);
  withPad[u8.length] = 0x80;
  const dv = new DataView(withPad.buffer);
  dv.setUint32(withPad.length - 4, bitLen >>> 0, false);
  let h0=0x6a09e667,h1=0xbb67ae85,h2=0x3c6ef372,h3=0xa54ff53a,h4=0x510e527f,h5=0x9b05688c,h6=0x1f83d9ab,h7=0x5be0cd19;
  const w = new Uint32Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let i = 0; i < withPad.length; i += 64) {
    for (let j = 0; j < 16; j++) w[j] = dv.getUint32(i + j * 4, false);
    for (let j = 16; j < 64; j++) {
      const s0 = rotr(w[j-15],7) ^ rotr(w[j-15],18) ^ (w[j-15]>>>3);
      const s1 = rotr(w[j-2],17) ^ rotr(w[j-2],19) ^ (w[j-2]>>>10);
      w[j] = (w[j-16] + s0 + w[j-7] + s1) >>> 0;
    }
    let a=h0,b=h1,c=h2,d=h3,e=h4,f=h5,g=h6,h=h7;
    for (let j = 0; j < 64; j++) {
      const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[j] + w[j]) >>> 0;
      const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h=g; g=f; f=e; e=(d+t1)>>>0; d=c; c=b; b=a; a=(t1+t2)>>>0;
    }
    h0=(h0+a)>>>0; h1=(h1+b)>>>0; h2=(h2+c)>>>0; h3=(h3+d)>>>0;
    h4=(h4+e)>>>0; h5=(h5+f)>>>0; h6=(h6+g)>>>0; h7=(h7+h)>>>0;
  }
  const out = new Uint8Array(32);
  const ov = new DataView(out.buffer);
  ov.setUint32(0,h0,false); ov.setUint32(4,h1,false); ov.setUint32(8,h2,false); ov.setUint32(12,h3,false);
  ov.setUint32(16,h4,false); ov.setUint32(20,h5,false); ov.setUint32(24,h6,false); ov.setUint32(28,h7,false);
  return out;
}

function gwBtcDecodeBase58(str) {
  const B58 = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
  const s = String(str || '');
  let zeros = 0;
  while (zeros < s.length && s[zeros] === '1') zeros++;
  const size = Math.ceil(((s.length - zeros) * 733) / 1000) + 1;
  const b256 = new Uint8Array(size);
  for (let i = zeros; i < s.length; i++) {
    const c = B58.indexOf(s[i]);
    if (c < 0) return null;
    let carry = c;
    for (let j = size - 1; j >= 0; j--) {
      carry += 58 * b256[j];
      b256[j] = carry & 0xff;
      carry >>= 8;
    }
    if (carry) return null;
  }
  let start = 0;
  while (start < size && b256[start] === 0) start++;
  const out = new Uint8Array(zeros + (size - start));
  out.fill(0, 0, zeros);
  out.set(b256.subarray(start), zeros);
  return out;
}

function gwBtcDecodeBech32(addr) {
  const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';
  const s = String(addr || '').trim();
  const lower = s.toLowerCase();
  if (s !== lower && s !== s.toUpperCase()) return null;
  const pos = lower.lastIndexOf('1');
  if (pos < 1 || pos + 7 > lower.length) return null;
  const hrp = lower.slice(0, pos);
  if (hrp !== 'bc' && hrp !== 'tb') return null;
  const data = [];
  for (let i = pos + 1; i < lower.length; i++) {
    const v = CHARSET.indexOf(lower[i]);
    if (v < 0) return null;
    data.push(v);
  }
  const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];
  const polymod = (values) => {
    let chk = 1;
    for (const v of values) {
      const b = chk >> 25;
      chk = ((chk & 0x1ffffff) << 5) ^ v;
      for (let i = 0; i < 5; i++) if ((b >> i) & 1) chk ^= GEN[i];
    }
    return chk;
  };
  const hrpExpand = [];
  for (let i = 0; i < hrp.length; i++) hrpExpand.push(hrp.charCodeAt(i) >> 5);
  hrpExpand.push(0);
  for (let i = 0; i < hrp.length; i++) hrpExpand.push(hrp.charCodeAt(i) & 31);
  const bech32Ok = polymod(hrpExpand.concat(data)) === 1;
  const bech32mOk = polymod(hrpExpand.concat(data)) === 0x2bc830a3;
  if (!bech32Ok && !bech32mOk) return null;
  const values = data.slice(0, -6);
  if (!values.length) return null;
  const witVer = values[0];
  if (witVer < 0 || witVer > 16) return null;
  if (witVer === 0 && !bech32Ok) return null;
  if (witVer !== 0 && !bech32mOk) return null;
  return { hrp, witVer };
}

function gwBtcAddrValid(a) {
  if (!a || typeof a !== 'string') return false;
  const s = a.trim();
  if (s.length < 14 || s.length > 90) return false;
  if (/^(1|3)/.test(s)) {
    const decoded = gwBtcDecodeBase58(s);
    if (!decoded || decoded.length !== 25) return false;
    const payload = decoded.subarray(0, 21);
    const checksum = decoded.subarray(21);
    const hash = gwBtcSha256Sync(gwBtcSha256Sync(payload));
    for (let i = 0; i < 4; i++) if (hash[i] !== checksum[i]) return false;
    return payload[0] === 0x00 || payload[0] === 0x05;
  }
  if (/^bc1/i.test(s)) {
    const d = gwBtcDecodeBech32(s);
    return !!(d && d.hrp === 'bc');
  }
  return false;
}

/** Never treat slippage / tiny hex as THOR memo (F11). */
function gwExtractThorMemo(quote) {
  if (!quote || typeof quote !== 'object') return null;
  const candidates = [
    quote.transactionRequest?.data,
    quote.transactionRequest?.memo,
    quote.memo,
    quote.toolDetails?.memo,
  ];
  for (const step of quote.includedSteps || []) {
    if (step?.toolDetails?.memo) candidates.push(step.toolDetails.memo);
    if (step?.estimate?.memo) candidates.push(step.estimate.memo);
  }
  for (const c of candidates) {
    if (c == null) continue;
    const str = String(c).trim();
    if (!str || str === '0x' || str === '0X') continue;
    if (/^0x[0-9a-fA-F]+$/.test(str) && str.length <= 10) continue;
    if (/^\d+(\.\d+)?$/.test(str)) continue;
    if (str.length >= 8) return str;
  }
  return null;
}

/** Normalize LI.FI bridge status — DONE/REFUNDED ≠ success (F03/F21). */
function gwNormalizeLifiBridgeStatus(payload) {
  const status = String(payload?.status || '').toUpperCase();
  const sub = String(payload?.substatus || '').toUpperCase();
  const msg = String(payload?.substatusMessage || payload?.message || '').slice(0, 240);
  const assetHint = payload?.receiving?.token?.symbol || null;
  if (!status) return { outcome: 'unknown', success: false, message: msg || 'empty', assetHint };
  if (status === 'PENDING' || status === 'ACTION_REQUIRED') {
    return { outcome: 'bridging', success: false, message: msg || sub || status, assetHint };
  }
  if (status === 'FAILED') {
    if (/REFUND/i.test(sub) || /REFUND/i.test(msg)) {
      return { outcome: 'refund_pending', success: false, message: msg || sub, assetHint };
    }
    return { outcome: 'failed', success: false, message: msg || sub || 'FAILED', assetHint };
  }
  if (status === 'DONE') {
    if (sub === 'REFUNDED' || /REFUND/i.test(sub)) {
      return { outcome: 'refunded', success: false, message: msg || 'Refunded — not destination delivery', assetHint };
    }
    if (sub === 'PARTIAL' || /PARTIAL/i.test(sub)) {
      return { outcome: 'partial', success: false, message: msg || 'Partial fill', assetHint };
    }
    if (sub === 'COMPLETED' || sub === 'DONE') {
      return { outcome: 'completed', success: true, message: msg || 'Destination confirmed', assetHint };
    }
    if (!sub && !payload?.receiving) {
      return { outcome: 'unknown', success: false, message: 'DONE without substatus/receiving', assetHint: null };
    }
    if (!sub && payload?.receiving) {
      return { outcome: 'completed', success: true, message: msg || 'Destination confirmed', assetHint };
    }
    return { outcome: 'unknown', success: false, message: msg || `DONE/${sub}`, assetHint };
  }
  return { outcome: 'unknown', success: false, message: msg || status, assetHint };
}

async function gwLifiBridgeMonitor({ txHash, bridge, fromChainId, toChainId, opId }) {
  if (!txHash) return;
  const started = Date.now();
  const bridgeName = bridge || 'across';
  const myOpId = opId || null;
  const myHash = String(txHash).toLowerCase();
  // Cancel previous monitor generation for this page
  const gen = (window.__gwBridgeMonGen = (window.__gwBridgeMonGen || 0) + 1);
  const stillMine = () => {
    if (window.__gwBridgeMonGen !== gen) return false;
    const op = typeof gwSwapOpGet === 'function' ? gwSwapOpGet() : window.__gwSwapOp;
    try {
      if (window.GromSwapCore?.bridgeMonitorOwnsOp) {
        return window.GromSwapCore.bridgeMonitorOwnsOp(op, { opId: myOpId, txHash: myHash });
      }
    } catch (_) {}
    if (!op) return false;
    if (myOpId && op.id && String(op.id) !== String(myOpId)) return false;
    if (op.hash && String(op.hash).toLowerCase() !== myHash) return false;
    return true;
  };
  const tick = async () => {
    if (!stillMine()) return;
    if (Date.now() - started > 2 * 60 * 60_000) {
      if (stillMine()) {
        try { gwSwapOpUpdate({ stage: 'unknown', message: 'Bridge monitor timed out' }); } catch (_) {}
      }
      return;
    }
    try {
      const qs = new URLSearchParams({ txHash: String(txHash) });
      if (bridgeName) qs.set('bridge', String(bridgeName));
      if (fromChainId) qs.set('fromChain', String(fromChainId));
      if (toChainId) qs.set('toChain', String(toChainId));
      const r = await fetch(`${GW_LIFI_ENDPOINT}/status?${qs}`);
      const j = await r.json();
      if (!stillMine()) return;
      const norm = gwNormalizeLifiBridgeStatus(j);
      try {
        gwSwapOpUpdate({
          stage: norm.outcome,
          lifiStatus: j?.status,
          lifiSubstatus: j?.substatus,
          destTxHash: j?.receiving?.txHash || null,
          message: norm.message,
        });
      } catch (_) {}
      if (!stillMine()) return;
      if (norm.outcome === 'completed' && norm.success) {
        try { gwToast(`Bridge complete${norm.assetHint ? ' · ' + norm.assetHint : ''}`, 'success'); } catch (_) {}
        try { gwSwapOpClear('completed'); } catch (_) {}
        return;
      }
      if (norm.outcome === 'refunded' || norm.outcome === 'failed' || norm.outcome === 'partial') {
        try { gwToast(norm.message || norm.outcome, norm.outcome === 'partial' ? 'warn' : 'error'); } catch (_) {}
        try { gwSwapOpClear(norm.outcome); } catch (_) {}
        return;
      }
    } catch (_) {}
    if (stillMine()) setTimeout(tick, 30_000);
  };
  tick();
}

function gwResumeSwapOpFromStorage() {
  try {
    const raw = localStorage.getItem('gw_swap_op');
    if (!raw) return;
    const op = JSON.parse(raw);
    const allow = window.GromSwapCore?.shouldRestoreSwapOp
      ? window.GromSwapCore.shouldRestoreSwapOp(op)
      : (op && !/completed|failed|cancelled|refunded/i.test(String(op.stage || '')));
    if (!allow) return;
    if (!op.hash && !op.signature && !op.boc && !op.requestDispatched && op.stage !== 'unknown') {
      try { localStorage.removeItem('gw_swap_op'); } catch (_) {}
      return;
    }
    window.__gwSwapOp = op;
    try { gwDsSubmit._busy = true; } catch (_) {}
    try {
      const cta = document.getElementById('gwDsCta');
      if (cta) cta.classList.add('busy');
    } catch (_) {}
    const kind = window.GromSwapCore?.pickResumeMonitorKind
      ? window.GromSwapCore.pickResumeMonitorKind(op)
      : 'lock_only';
    // Never feed a Solana signature into LI.FI
    if (kind === 'lifi_bridge' && (op.hash || op.signature)) {
      gwLifiBridgeMonitor({
        txHash: op.hash || op.signature,
        bridge: op.bridge,
        fromChainId: op.fromChainId || op.chainId,
        toChainId: op.toChainId,
        opId: op.id,
      });
    } else if (kind === 'solana' && (op.hash || op.signature)) {
      try { gwSolConfirmMonitor({ signature: op.hash || op.signature, opId: op.id }); } catch (_) {}
    } else if (kind === 'tron' && op.hash) {
      try { gwTronConfirmMonitor({ txId: op.hash, opId: op.id }); } catch (_) {}
    } else if (kind === 'evm_receipt' && op.hash) {
      try {
        gwEvmConfirmMonitor({
          hash: op.hash,
          chainId: op.chainId || op.fromChainId,
          opId: op.id,
        });
      } catch (_) {}
    } else {
      try {
        gwToast('Previous swap still unresolved — check wallet Activity before swapping again', 'warn');
      } catch (_) {}
    }
  } catch (_) {}
}
try { setTimeout(gwResumeSwapOpFromStorage, 1500); } catch (_) {}

function gwMonitorTerminal(opId, stage, toastMsg, toastKind) {
  try {
    const op = typeof gwSwapOpGet === 'function' ? gwSwapOpGet() : window.__gwSwapOp;
    if (opId && op?.id && String(op.id) !== String(opId)) return false;
  } catch (_) {}
  try { gwSwapOpClear(stage); } catch (_) {}
  try { if (toastMsg) gwToast(toastMsg, toastKind || (stage === 'completed' ? 'success' : 'error')); } catch (_) {}
  try { gwDsSubmit._busy = false; } catch (_) {}
  try {
    const c = document.getElementById('gwDsCta');
    if (c) c.classList.remove('busy');
  } catch (_) {}
  try { gwDsResetSubmitState(); } catch (_) {}
  return true;
}

/** Best-effort Solana signature confirmation (no re-send). Uses result.value (D03). */
async function gwSolConfirmMonitor({ signature, opId }) {
  if (!signature) return;
  const myOpId = opId || null;
  const sig = String(signature);
  const started = Date.now();
  const stillMine = () => {
    const op = typeof gwSwapOpGet === 'function' ? gwSwapOpGet() : window.__gwSwapOp;
    if (!op) return false;
    if (myOpId && op.id && String(op.id) !== String(myOpId)) return false;
    return true;
  };
  const tick = async () => {
    if (!stillMine()) return;
    if (Date.now() - started > 30 * 60_000) {
      try { gwSwapOpUpdate({ stage: 'unknown', message: 'Solana confirm timed out' }); } catch (_) {}
      // Keep lock — ambiguous; do not unlock for second send
      return;
    }
    try {
      const r = await fetch('https://api.mainnet-beta.solana.com', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          jsonrpc: '2.0', id: 1,
          method: 'getSignatureStatuses',
          params: [[sig], { searchTransactionHistory: true }],
        }),
      });
      const j = await r.json();
      if (!stillMine()) return;
      const parsed = window.GromSwapCore?.parseSolanaSignatureStatuses
        ? window.GromSwapCore.parseSolanaSignatureStatuses(j)
        : (() => {
          const st = j?.result?.value?.[0] ?? j?.result?.[0];
          if (j?.error) return { outcome: 'rpc_error' };
          if (st == null) return { outcome: 'pending' };
          if (st.err) return { outcome: 'failed' };
          if (st.confirmationStatus === 'confirmed' || st.confirmationStatus === 'finalized') {
            return { outcome: 'completed' };
          }
          return { outcome: 'pending' };
        })();
      if (parsed.outcome === 'failed') {
        gwMonitorTerminal(myOpId, 'failed', 'Solana swap failed on-chain', 'error');
        return;
      }
      if (parsed.outcome === 'completed') {
        gwMonitorTerminal(myOpId, 'completed', 'Solana swap confirmed', 'success');
        return;
      }
      // rpc_error / empty / pending — keep polling
    } catch (_) {}
    if (stillMine()) setTimeout(tick, 15_000);
  };
  tick();
}
try { window.gwSolConfirmMonitor = gwSolConfirmMonitor; } catch (_) {}

/** Best-effort Tron receipt poll (no re-send). Positive SUCCESS only (D04). */
async function gwTronConfirmMonitor({ txId, opId }) {
  if (!txId) return;
  const myOpId = opId || null;
  const started = Date.now();
  const stillMine = () => {
    const op = typeof gwSwapOpGet === 'function' ? gwSwapOpGet() : window.__gwSwapOp;
    if (!op) return false;
    if (myOpId && op.id && String(op.id) !== String(myOpId)) return false;
    return true;
  };
  const tick = async () => {
    if (!stillMine()) return;
    if (Date.now() - started > 30 * 60_000) {
      try { gwSwapOpUpdate({ stage: 'unknown', message: 'Tron confirm timed out' }); } catch (_) {}
      return;
    }
    try {
      const r = await fetch(`https://api.trongrid.io/wallet/gettransactioninfobyid`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ value: txId }),
      });
      const j = await r.json();
      if (!stillMine()) return;
      const parsed = window.GromSwapCore?.classifyTronTxInfo
        ? window.GromSwapCore.classifyTronTxInfo(j, txId)
        : { outcome: 'pending' };
      if (parsed.outcome === 'failed') {
        gwMonitorTerminal(myOpId, 'failed', `Tron swap failed (${parsed.result || 'error'})`, 'error');
        return;
      }
      if (parsed.outcome === 'completed') {
        gwMonitorTerminal(myOpId, 'completed', 'Tron swap confirmed', 'success');
        return;
      }
      // empty / pending / mismatch / unknown → keep polling (unknown after long may stay)
      if (parsed.outcome === 'unknown' && Date.now() - started > 5 * 60_000) {
        try { gwSwapOpUpdate({ stage: 'unknown', message: 'Tron receipt ambiguous' }); } catch (_) {}
        return;
      }
    } catch (_) {}
    if (stillMine()) setTimeout(tick, 15_000);
  };
  tick();
}
try { window.gwTronConfirmMonitor = gwTronConfirmMonitor; } catch (_) {}

/** Same-chain EVM receipt poll after submitted (D05). */
async function gwEvmConfirmMonitor({ hash, chainId, opId }) {
  if (!hash) return;
  const myOpId = opId || null;
  const cid = Number(chainId) || null;
  const started = Date.now();
  const stillMine = () => {
    const op = typeof gwSwapOpGet === 'function' ? gwSwapOpGet() : window.__gwSwapOp;
    if (!op) return false;
    if (myOpId && op.id && String(op.id) !== String(myOpId)) return false;
    return true;
  };
  const tick = async () => {
    if (!stillMine()) return;
    if (Date.now() - started > 30 * 60_000) {
      try { gwSwapOpUpdate({ stage: 'unknown', message: 'EVM receipt timed out' }); } catch (_) {}
      return;
    }
    try {
      let receipt = null;
      if (typeof gwRpcTry === 'function' && cid) {
        receipt = await gwRpcTry(cid, 'eth_getTransactionReceipt', [hash]);
      } else if (typeof fetch === 'function' && cid) {
        // Minimal publicnode fallback when gwRpcTry unavailable (tests)
        const url = ({
          1: 'https://ethereum.publicnode.com',
          56: 'https://bsc.publicnode.com',
          42161: 'https://arbitrum.publicnode.com',
          8453: 'https://base.publicnode.com',
        })[cid];
        if (url) {
          const r = await fetch(url, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({
              jsonrpc: '2.0', id: 1,
              method: 'eth_getTransactionReceipt',
              params: [hash],
            }),
          });
          const j = await r.json();
          if (j?.error) throw new Error(j.error.message || 'rpc');
          receipt = j?.result ?? null;
        }
      }
      if (!stillMine()) return;
      const parsed = window.GromSwapCore?.classifyEvmReceipt
        ? window.GromSwapCore.classifyEvmReceipt(receipt)
        : (receipt == null
          ? { outcome: 'pending' }
          : (receipt.status === '0x1' || receipt.status === 1
            ? { outcome: 'completed' }
            : (receipt.status === '0x0' || receipt.status === 0
              ? { outcome: 'failed' }
              : { outcome: 'unknown' })));
      if (parsed.outcome === 'failed') {
        gwMonitorTerminal(myOpId, 'failed', 'EVM swap reverted on-chain', 'error');
        return;
      }
      if (parsed.outcome === 'completed') {
        gwMonitorTerminal(myOpId, 'completed', 'EVM swap confirmed', 'success');
        return;
      }
    } catch (_) {
      // Temporary RPC failure — keep polling
    }
    if (stillMine()) setTimeout(tick, 8_000);
  };
  tick();
}
try { window.gwEvmConfirmMonitor = gwEvmConfirmMonitor; } catch (_) {}

/** Ask the user for their BTC destination address (once) — glass modal. */
async function gwBtcPromptAddress() {
  return new Promise((resolve) => {
    let ov = document.getElementById('gw-btc-overlay');
    if (!ov) {
      ov = document.createElement('div');
      ov.id = 'gw-btc-overlay';
      Object.assign(ov.style, {
        position: 'fixed', inset: '0', zIndex: '950', display: 'none',
        alignItems: 'center', justifyContent: 'center',
        background: 'rgba(46,55,71,0.55)', backdropFilter: 'blur(6px)',
      });
      ov.innerHTML = `
        <div style="width:min(440px,92vw);padding:22px;border-radius:20px;color:#e7eef8;
                    background:linear-gradient(160deg,rgba(37,45,58,.98),rgba(32,39,55,.98));
                    border:1px solid rgba(247,147,26,.28);box-shadow:0 20px 60px -12px rgba(0,0,0,.65)">
          <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
            <span style="width:28px;height:28px;border-radius:50%;background:#F7931A;color:#fff;
                          font-weight:800;display:inline-flex;align-items:center;justify-content:center">₿</span>
            <h3 style="margin:0;font-size:15px;font-weight:800">Ваш Bitcoin-адрес получения</h3>
          </div>
          <p style="margin:0 0 12px;font-size:12.5px;color:#98a8c0;line-height:1.55">
            LiFi отправит BTC на этот адрес через THORchain после того как ты подпишешь EVM-транзакцию.
            Проверь дважды — вернуть нельзя.
          </p>
          <input id="gwBtcInp" type="text" placeholder="bc1q… или 1… / 3…"
            style="width:100%;padding:10px 12px;background:rgba(255,255,255,.05);
                   border:1px solid rgba(255,255,255,.08);border-radius:10px;color:#e7eef8;
                   font-size:14px;font-family:inherit;outline:none;margin-bottom:8px" />
          <div id="gwBtcErr" style="font-size:11.5px;color:#f87171;min-height:16px;margin-bottom:10px"></div>
          <div style="display:flex;gap:8px">
            <button id="gwBtcCancel" style="flex:1;padding:10px 14px;border-radius:10px;border:0;
                    background:rgba(255,255,255,.05);color:#cfdfee;font-weight:800;cursor:pointer">Отмена</button>
            <button id="gwBtcSave" style="flex:2;padding:10px 14px;border-radius:10px;border:0;
                    background:linear-gradient(135deg,#F7931A,#e07817);color:#0a0400;font-weight:800;
                    cursor:pointer">Сохранить</button>
          </div>
        </div>`;
      document.body.appendChild(ov);
    }
    const inp = ov.querySelector('#gwBtcInp');
    const err = ov.querySelector('#gwBtcErr');
    inp.value = gwBtcAddrGet();
    err.textContent = '';
    ov.style.display = 'flex';
    setTimeout(() => inp.focus(), 40);
    ov.querySelector('#gwBtcCancel').onclick = () => { ov.style.display = 'none'; resolve(null); };
    ov.querySelector('#gwBtcSave').onclick = () => {
      const v = (inp.value || '').trim();
      if (!gwBtcAddrValid(v)) { err.textContent = 'Похоже это не валидный BTC-адрес'; return; }
      gwBtcAddrSet(v);
      ov.style.display = 'none';
      resolve(v);
    };
    inp.addEventListener('keydown', (e) => { if (e.key === 'Enter') ov.querySelector('#gwBtcSave').click(); });
    ov.onclick = (e) => { if (e.target === ov) { ov.style.display = 'none'; resolve(null); } };
  });
}

/** LiFi quote for EVM → BTC via THORchain. `toBtcAddr` is user's BTC. */
async function gwLifiQuoteToBtc({ fromChainId, fromSym, amtNum, evmAccount, toBtcAddr }) {
  const cfg = GW_OC_SWAP[fromChainId];
  if (!cfg) return null;
  if (!gwBtcAddrValid(toBtcAddr)) throw new Error('Invalid BTC destination address');
  const isNative = fromSym === cfg.native;
  // Native input must use LI.FI zero marker — not wrapped without wrap/approve (F11)
  const inAddr = isNative ? '0x0000000000000000000000000000000000000000' : cfg.tokens[fromSym];
  if (!inAddr) return null;
  const inDec = cfg.decimals[fromSym] ?? 18;
  const fromAmount = (typeof gwAmtToBaseUnits === 'function'
    ? gwAmtToBaseUnits(amtNum, inDec)
    : gwParseAmountToUnits(amtNum, inDec, { truncate: true })).toString();
  const qs = new URLSearchParams({
    fromChain:    String(fromChainId),
    toChain:      String(GW_LIFI_BTC_CHAIN_ID),
    fromToken:    inAddr,
    toToken:      'bitcoin',
    fromAmount,
    fromAddress:  evmAccount,
    toAddress:    toBtcAddr,
    slippage:     String(typeof gwSwapSlippageFraction === 'function' ? gwSwapSlippageFraction() : 0.02),
    integrator:   GW_LIFI_INTEGRATOR,
    order:        'RECOMMENDED',
    allowBridges: 'thorchain',
    ...(GW_LIFI_FEE_ADDR !== '0x0000000000000000000000000000000000000000'
      ? { fee: String(GW_LIFI_FEE_PCT), feeAddress: GW_LIFI_FEE_ADDR }
      : {}),
  });
  const r = await fetch(`${GW_LIFI_ENDPOINT}/quote?${qs}`, { headers: { accept: 'application/json' } });
  if (!r.ok) {
    const t = await r.text().catch(() => '');
    if (typeof gwLifiIsFeeConfigErr === 'function' && gwLifiIsFeeConfigErr(r.status, t)) {
      if (typeof gwLifiMarkFeeUnavailable === 'function') gwLifiMarkFeeUnavailable('lifi-btc');
      return null;
    }
    console.warn('[GROM] lifi BTC quote', r.status, t);
    return null;
  }
  return await r.json();
}

/** Full EVM → BTC swap: quote → approve → sign → confirm. */
async function gwBtcSwapExec({ fromChainId, fromSym, amtNum }) {
  let btcAddr = gwBtcAddrGet();
  if (!btcAddr) btcAddr = await gwBtcPromptAddress();
  if (!btcAddr) throw new Error('BTC address required');
  if (!gwBtcAddrValid(btcAddr)) throw new Error('Invalid BTC destination address');
  const provider = (window.gromWallet?.wcProvider && window.gromWallet.wcProvider.accounts?.[0])
    ? window.gromWallet.wcProvider : window.ethereum;
  if (!provider) throw new Error('No wallet provider');
  const [account] = await provider.request({ method: 'eth_accounts' });
  if (!account) throw new Error('Wallet not connected');
  gwToast('Requesting THORchain route via LiFi…', 'info');
  await gwEnsureChain(provider, fromChainId);
  currentChainId = fromChainId;
  const quote = await gwLifiQuoteToBtc({ fromChainId, fromSym, amtNum, evmAccount: account, toBtcAddr: btcAddr });
  if (!quote?.transactionRequest) throw new Error('No THORchain route for this size/pair');
  const cfg = GW_OC_SWAP[fromChainId];
  const isNative = fromSym === cfg.native;
  const inAddr = isNative ? null : cfg.tokens[fromSym];
  const inDec = cfg.decimals[fromSym] ?? 18;
  const amountIn = typeof gwAmtToBaseUnits === 'function'
    ? gwAmtToBaseUnits(amtNum, inDec)
    : gwParseAmountToUnits(amtNum, inDec, { truncate: true });
  if (!isNative && inAddr) {
    const spender = quote.estimate?.approvalAddress || quote.transactionRequest.to;
    const allow = await gwErc20Allowance(provider, inAddr, account, spender, fromChainId);
    if (allow < amountIn) {
      gwToast('Approve token to THORchain router…', 'info');
      await gwErc20ApproveMax(provider, inAddr, spender, account, fromChainId);
    }
  }
  const outSat = Number(quote.estimate?.toAmount || 0) / 1e8;
  gwToast(`Confirm in wallet · you'll receive ~${outSat.toFixed(8)} BTC · ETA approximate`, 'info');
  const tx = quote.transactionRequest;
  const hash = await gwProviderSendTx(provider, {
    from: account, to: tx.to, data: tx.data, value: tx.value || '0x0',
    ...(tx.gasLimit ? { gas: tx.gasLimit } : {}),
  });
  try {
    gwSwapOpUpdate({
      stage: 'bridging',
      hash,
      fromChainId,
      toChainId: GW_LIFI_BTC_CHAIN_ID,
      bridge: 'thorchain',
    });
    gwLifiBridgeMonitor({ txHash: hash, bridge: 'thorchain', fromChainId, toChainId: GW_LIFI_BTC_CHAIN_ID });
  } catch (_) {}
  gwToast('Submitted · THORchain confirming — destination not complete yet', 'info');
  return hash;
}

/* ==========================================================================
 * PHASE 9 — Solana support (2026-07-08)
 *
 * User: "мне нужно чтобы человек мог в одном месте поменять". Solana
 * needs its own wallet stack — Phantom / Solflare / Backpack. We route
 * quotes through Jupiter Aggregator (jup.ag/swap), the de-facto meta-
 * aggregator on Solana. Jupiter's API is keyless and public.
 *
 * Flow when a user picks the SOL chain chip:
 *   1. `gwSolConnect()` opens Phantom's provider popup and gets pubkey.
 *   2. `gwSolQuote(inMint, outMint, amt)` hits Jupiter's quote API.
 *   3. `gwSolSwap(quote)` hits Jupiter's `/swap` endpoint to get an
 *      unsigned transaction (base64), then asks Phantom to sign + send.
 *
 * Well-known SPL token mints — SPL uses 32-byte base58 addresses.
 * ========================================================================== */
