/** Patch swap panel labels on lang change without tearing down the whole widget. */
function gwDsApplyI18nLabels() {
  const card = document.getElementById('gwDsCard');
  if (!card) return false;
  const t = gwDsLang();
  const mode = (typeof gwDsGetMode === 'function') ? gwDsGetMode() : 'onchain';
  const title = card.querySelector('.gw-ds-title');
  if (title) title.textContent = t.h;
  const sub = card.querySelector('.gw-ds-sub');
  if (sub) sub.textContent = gwUxText("Сравниваем доступные маршруты", "Comparing available routes");
  const rows = card.querySelectorAll('.gw-ds-row');
  if (rows[0]) {
    const el = rows[0].querySelector('.gw-ds-row-top > span:first-child');
    if (el) el.textContent = t.from;
  }
  if (rows[1]) {
    const el = rows[1].querySelector('.gw-ds-row-top > span:first-child');
    if (el) el.textContent = t.to;
  }
  card.querySelectorAll('.gw-ds-chip').forEach((btn) => {
    const pct = btn.dataset.pct;
    if (pct === '25') btn.textContent = t.pct25;
    else if (pct === '50') btn.textContent = t.pct50;
    else if (pct === '75') btn.textContent = t.pct75;
    else if (pct === '100') btn.textContent = t.pctMax;
  });
  card.querySelectorAll('.gw-ds-mode').forEach((btn) => {
    if (btn.dataset.mode === 'paper') btn.textContent = t.modeT;
    else if (btn.dataset.mode === 'onchain') btn.textContent = t.modeO;
  });
  const flip = document.getElementById('gwDsFlip');
  if (flip) flip.setAttribute('aria-label', t.flip);
  const cta = document.getElementById('gwDsCta');
  if (cta && !cta.classList.contains('busy')) {
    const label = mode === 'onchain' ? (t.ctaOc || t.cta) : t.cta;
    cta.textContent = label + ' →';
  }
  const recentTitle = card.querySelector('.gw-ds-recent-title');
  if (recentTitle) recentTitle.textContent = t.recent;

  // Idle route hint + live quote must follow language without a full page reload
  // (mobile/stable UI skips panel rebuild on grom:lang-change).
  let amt = 0;
  try {
    amt = (typeof gwDsReadSwapAmt === 'function')
      ? gwDsReadSwapAmt()
      : Number(document.getElementById('gwDsAmt')?.value) || 0;
  } catch (_) { amt = 0; }
  const rateLine = document.getElementById('gwDsRateLine');
  if (rateLine && !(amt > 0)) rateLine.textContent = t.est;
  try { if (typeof gwDsRefreshBalances === 'function') gwDsRefreshBalances().catch(() => {}); } catch (_) {}
  try { if (typeof gwDsRefreshRate === 'function') gwDsRefreshRate(); } catch (_) {}
  try { if (typeof gwDsSyncCtaState === 'function') gwDsSyncCtaState(); } catch (_) {}
  return true;
}

/* Small in-memory price cache for USD values (neutral /api/market/quotes). */
const gwDsPriceCache = new Map();  // sym -> { price, at }
let gwDsQuotesBundle = null;
let gwDsQuotesAt = 0;
async function gwDsPriceUsd(sym) {
  if (sym === 'USDT' || sym === 'USDC' || sym === 'BUSD' || sym === 'DAI') return 1;
  const cached = gwDsPriceCache.get(sym);
  if (cached && Date.now() - cached.at < 20000) return cached.price;
  try {
    if (!gwDsQuotesBundle || Date.now() - gwDsQuotesAt > 20000) {
      const j = (typeof gwFetchMarketQuotes === 'function')
        ? await gwFetchMarketQuotes()
        : await (await fetch('/api/market/quotes', { headers: { accept: 'application/json' } })).json();
      if (!j) return 0;
      gwDsQuotesBundle = j;
      gwDsQuotesAt = Date.now();
    }
    const p = Number(gwDsQuotesBundle?.crypto?.[sym] || 0) || 0;
    gwDsPriceCache.set(sym, { price: p, at: Date.now() });
    return p;
  } catch (_) { return 0; }
}

/** Balance of `sym` on one EVM chain (for routing / gas network pick). */
async function gwDsTokenBalanceOnChain(sym, chainId, opts) {
  const s = String(sym || '').toUpperCase();
  const c = Number(chainId);
  if (!s || !c) return 0;
  let addr = (opts && opts.account) || '';
  if (!addr || !/^0x[a-fA-F0-9]{40}$/i.test(addr)) {
    try { addr = gwOcConnectedAddress() || ''; } catch (_) { addr = ''; }
  }
  /* Soft chip / Tron-first WC: ocConnected often null while label/display is live. */
  if (!addr || !/^0x[a-fA-F0-9]{40}$/i.test(addr)) {
    try { addr = (typeof gwDisplayAddress === 'function' && gwDisplayAddress()) || ''; } catch (_) {}
  }
  if (!addr || !/^0x[a-fA-F0-9]{40}$/i.test(addr)) {
    try { addr = localStorage.getItem('grom_wallet_label') || ''; } catch (_) {}
  }
  if (!addr || !/^0x[a-fA-F0-9]{40}$/i.test(addr)) {
    try {
      const p = (typeof gwActiveSigningProvider === 'function' && gwActiveSigningProvider())
        || window.gromWallet?.wcProvider;
      addr = p?.accounts?.[0] || '';
    } catch (_) {}
  }
  if (!addr || !/^0x[a-fA-F0-9]{40}$/i.test(addr)) return 0;
  const b = await window.gromFetchOnchainBalances?.(addr, c).catch(() => null);
  if (!b) return 0;
  if (s === 'ETH' && b.nativeEth) return Number(b.nativeEth) || 0;
  if (s === 'BNB' && c === 56 && b.nativeEth) return Number(b.nativeEth) || 0;
  if ((s === 'MATIC' || s === 'POL') && c === 137 && b.nativeEth) return Number(b.nativeEth) || 0;
  if (s === 'AVAX' && c === 43114 && b.nativeEth) return Number(b.nativeEth) || 0;
  if (b.tokens && b.tokens[s] != null) return Number(b.tokens[s]) || 0;
  return 0;
}

/** Chain where the user holds the most of `sym` (USDC on BSC → 56, not Ethereum). */
async function gwDsBestChainForToken(sym, opts) {
  const s = String(sym || '').toUpperCase();
  if (!s) return null;
  const addr = gwOcConnectedAddress();
  if (!addr || !/^0x[a-fA-F0-9]{40}$/i.test(addr)) return null;
  const prefer = opts?.prefer ? Number(opts.prefer) : null;
  const scan = opts?.chains || [56, 1, 42161, 137, 8453, 10, 43114, 59144, 250];
  let bestCid = null;
  let bestBal = 0;
  for (const c of scan) {
    const v = await gwDsTokenBalanceOnChain(s, c);
    if (v > bestBal) { bestBal = v; bestCid = c; }
  }
  if (prefer && bestCid && prefer !== bestCid) {
    const pb = await gwDsTokenBalanceOnChain(s, prefer);
    if (pb >= bestBal * 0.999) return prefer;
  }
  return bestBal > 0 ? bestCid : null;
}

/** User explicitly picked a network (chip click or FROM token row). */
function gwDsMarkUserChain(chainId) {
  const cid = Number(chainId);
  if (!cid) return;
  try { window.__gwDsUserPickedChain = { chainId: cid, at: Date.now() }; } catch (_) {}
}
try { window.gwDsMarkUserChain = gwDsMarkUserChain; } catch (_) {}

function gwDsUserExplicitChain() {
  try {
    const chipPick = window.__gwDsUserPickedChain;
    if (chipPick && Number(chipPick.chainId) > 0) {
      const at = Number(chipPick.at || 0);
      if (!at || Date.now() - at < 60 * 60 * 1000) return Number(chipPick.chainId);
    }
    const fromPick = window.__gwDsUserPickedFrom;
    if (fromPick && Number(fromPick.chainId) > 0) {
      const at = Number(fromPick.at || 0);
      if (!at || Date.now() - at < 30 * 60 * 1000) return Number(fromPick.chainId);
    }
    const ui = typeof gwGetActiveUiChainId === 'function' ? Number(gwGetActiveUiChainId()) : 0;
    return ui || 0;
  } catch (_) { return 0; }
}
try { window.gwDsUserExplicitChain = gwDsUserExplicitChain; } catch (_) {}

/**
 * Align chain chip with FROM token — BNB must flip to BSC, USDC stays on ARB if bal there.
 * Returns the chain id now active for quotes/exec.
 */
async function gwDsSyncChainForFromToken(fromSym, opts) {
  const sym = (typeof gwDsNormSym === 'function') ? gwDsNormSym(fromSym) : String(fromSym || '').toUpperCase();
  if (!sym) return null;
  /* Sticky / explicit FROM chain (HL fund ETH on mainnet) must not be
   * auto-flipped to BSC just because a dust balance exists there. */
  try {
    const pick = window.__gwDsUserPickedFrom;
    const pickCid = Number(pick?.chainId) || 0;
    const pickSym = (typeof gwDsNormSym === 'function')
      ? gwDsNormSym(pick?.sym)
      : String(pick?.sym || '').toUpperCase();
    const sticky = window.__gwDsForceBridgeTo
      && (window.__gwDsForceBridgeTo.source === 'futures'
        || window.__gwDsForceBridgeTo.source === 'hl'
        || window.__gwDsForceBridgeTo.source === 'predict'
        || Number(window.__gwDsForceBridgeTo.amountUsd) > 0);
    if (pickCid && pickSym === sym && (sticky || Number(pick.at) > Date.now() - 30 * 60 * 1000)) {
      if ((typeof gwGetActiveUiChainId === 'function' ? Number(gwGetActiveUiChainId()) : 0) !== pickCid) {
        gwDsSetActiveChain(pickCid);
      }
      return pickCid;
    }
  } catch (_) {}
  const home = gwDsHomeChainForToken(sym);
  const ui = (typeof gwGetActiveUiChainId === 'function') ? Number(gwGetActiveUiChainId()) : 0;
  const walletCid = Number(opts?.walletChainId) || 0;
  const addr = gwOcConnectedAddress();
  const hasAddr = addr && /^0x[a-fA-F0-9]{40}$/i.test(addr);

  /* Exclusive native on wrong network (BNB while ARB chip lit) → home chain. */
  if (home && ui && ui !== home && GW_TOKEN_EXCLUSIVE_CHAIN[sym]) {
    const onUi = hasAddr ? await gwDsTokenBalanceOnChain(sym, ui) : 0;
    if (onUi <= 0) {
      gwDsSetActiveChain(home);
      try { gwDsMarkUserChain(home); } catch (_) {}
      if (!opts?.silent) {
        try {
          const lbl = (typeof gwChainLabel === 'function') ? gwChainLabel(home) : String(home);
          gwToast(`${sym} → ${lbl}`, 'info');
        } catch (_) {}
      }
      return home;
    }
  }

  /* Balance on currently selected chain — keep (USDC on ARB, etc.). */
  if (ui && hasAddr) {
    const uiBal = await gwDsTokenBalanceOnChain(sym, ui);
    if (uiBal > 0) return ui;
  }

  /* Scan wallets for where this token actually lives. */
  if (hasAddr) {
    const best = await gwDsBestChainForToken(sym, { prefer: ui || home || walletCid || null });
    if (best && best !== ui) {
      gwDsSetActiveChain(best);
      return best;
    }
  }

  /* No balance yet — default hub for symbol (BNB→56, ARB→42161). */
  if (home && (!ui || !gwDsTokenValidOnChain(sym, ui))) {
    if (ui !== home) gwDsSetActiveChain(home);
    return home;
  }

  return ui || home || walletCid || null;
}
