/**
 * Auto-pick the chain where FROM token actually lives (Simple + Advanced).
 * Switches UI chip + currentChainId; shows gas hint once per sym/chain.
 */
async function gwDsAutoDetectChainFor(fromSym, opts) {
  if (gwDsGetMode() !== 'onchain') return null;
  if (typeof gwDsSyncChainForFromToken === 'function') {
    return gwDsSyncChainForFromToken(fromSym, opts);
  }
  const sym = gwDsNormSym(fromSym);
  if (!sym) return null;
  if (!gwOcConnectedAddress()) return null;
  const ui = (typeof gwGetActiveUiChainId === 'function') ? Number(gwGetActiveUiChainId()) : 0;
  const best = await gwDsBestChainForToken(sym, { prefer: ui || null });
  if (!best) return ui || null;

  const uiBal = ui ? await gwDsTokenBalanceOnChain(sym, ui) : 0;
  const bestBal = await gwDsTokenBalanceOnChain(sym, best);
  let target = ui || best;

  if (uiBal > 0 && ui) target = ui;
  else if (uiBal <= 0 && bestBal > 0) target = best;
  else if (best !== ui && bestBal > uiBal * 1.001) target = best;
  else if (!ui && bestBal > 0) target = best;

  if (!target || target === ui) return ui || target;

  gwDsSetActiveChain(target);
  try {
    const hintKey = sym + '|' + target;
    if (window.__gwDsChainHintShown !== hintKey && !opts?.silent) {
      window.__gwDsChainHintShown = hintKey;
      const lbl = (typeof gwChainLabel === 'function') ? gwChainLabel(target) : String(target);
      const gas = target === 56 ? 'BNB' : target === 137 ? 'POL' : target === 43114 ? 'AVAX' : 'ETH';
      gwToast(`${sym} on ${lbl} · gas in ${gas}`, 'info');
    }
  } catch (_) {}

  try {
    const row = document.querySelector(
      `.gw-ds-sim-row[data-sym="${sym}"][data-cid="${target}"]`,
    );
    if (row && !row.classList.contains('on')) {
      document.querySelectorAll('.gw-ds-sim-row.on').forEach((x) => x.classList.remove('on'));
      row.classList.add('on');
    }
  } catch (_) {}

  try {
    window.__gwDsUserPickedFrom = Object.assign({}, window.__gwDsUserPickedFrom || {}, {
      sym, chainId: target, at: Date.now(),
    });
  } catch (_) {}

  return target;
}
