function gwDsCanonicalAmtStr(raw) {
  try {
    if (window.GromSwapCore?.canonicalAmountString) return window.GromSwapCore.canonicalAmountString(raw);
  } catch (_) {}
  if (raw == null) return '';
  let s = String(raw).trim().replace(/\s+/g, '').replace(/^\u2212/, '-');
  if (!s || s.startsWith('-') || /[eE]/.test(s)) return '';
  if (s.includes(',') && s.includes('.')) {
    if (s.lastIndexOf(',') > s.lastIndexOf('.')) s = s.replace(/\./g, '').replace(',', '.');
    else s = s.replace(/,/g, '');
  } else if (s.includes(',')) s = s.replace(',', '.');
  if (!/^\d+(\.\d+)?$/.test(s)) return '';
  const [w, f] = s.split('.');
  const whole = w.replace(/^0+(?=\d)/, '') || '0';
  return f != null ? `${whole}.${f}` : whole;
}

function gwDsParseAmt(raw) {
  // Display/estimate only — monetary paths must use gwDsCanonicalAmtStr / BigInt (R10)
  const s = gwDsCanonicalAmtStr(raw);
  if (!s) return 0;
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

function gwDsReadSwapAmtStr() {
  try {
    const ds = document.getElementById('gwDsAmt');
    const raw = ds?.value || '';
    const canon = gwDsCanonicalAmtStr(raw);
    if (ds && canon && ds.value !== canon) ds.value = canon;
    return canon;
  } catch (_) {
    return gwDsCanonicalAmtStr(document.getElementById('gwDsAmt')?.value);
  }
}

function gwDsReadSwapAmt() {
  const s = gwDsReadSwapAmtStr();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}
