/** Keep the executable-quote flag and CTA state in sync. */
function gwDsSetQuoteExecReady(ready, reason) {
  window.__gwDsQuoteExecReady = !!ready;
  window.__gwDsQuoteExecReason = reason || '';
  try { gwDsSyncCtaState(); } catch (_) {}
}
try { window.gwDsSetQuoteExecReady = gwDsSetQuoteExecReady; } catch (_) {}

/** After WC reconnect, wait until fee-verified quote is painted (or timeout). */
async function gwDsAwaitQuoteReady(ms) {
  const budget = Math.max(2000, Number(ms) || 12000);
  const t0 = Date.now();
  while (Date.now() - t0 < budget) {
    if (window.__gwDsQuoteExecReady) return true;
    await new Promise((r) => setTimeout(r, 280));
  }
  return !!window.__gwDsQuoteExecReady;
}
try { window.gwDsAwaitQuoteReady = gwDsAwaitQuoteReady; } catch (_) {}

/** Soft reconnect → fresh quote → only then allow signing. */
async function gwDsReconnectThenRequote(ctx) {
  const from = ctx?.from || '';
  const to = ctx?.to || '';
  const amt = ctx?.amt;
  try {
    gwToast('Refreshing route after reconnect…', 'info');
  } catch (_) {}
  try {
    window.__gwDsQuoteExecReady = false;
    window.__gwDsQuoteExecReason = 'Refreshing route after reconnect…';
    window.__gwLastAggQuotes = null;
  } catch (_) {}
  try {
    if (typeof gwDsRefreshRate === 'function') await gwDsRefreshRate();
  } catch (_) {}
  const ok = await gwDsAwaitQuoteReady(14000);
  if (!ok) {
    const why = window.__gwDsQuoteExecReason
      || ('No executable route for ' + from + ' → ' + to + ' after reconnect');
    try {
      gromReportIssue({
        product: 'swap',
        action: 'quote_not_ready',
        message: why,
        detail: {
          kind: 'quote_not_ready',
          from, to, amt,
          afterReconnect: true,
          admin_brief: 'После reconnect маршрута нет — Start не должен слать в кошелёк',
        },
      });
    } catch (_) {}
    throw new Error(why);
  }
  return true;
}
try { window.gwDsReconnectThenRequote = gwDsReconnectThenRequote; } catch (_) {}

