const GW_POLYGON_USDC = '0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359';

/** Destination chain when user wants TO token on another network (bridge). */
function gwDsResolveBridgeDest(fromSym, toSym, fromCid) {
  const from = gwDsNormSym(fromSym);
  const to = gwDsNormSym(toSym);
  const src = Number(fromCid) || 0;
  if (!src) return 0;
  try {
    const f = window.__gwDsForceBridgeTo;
    if (f && Number(f.chainId) > 0 && Number(f.chainId) !== src) {
      const want = gwDsNormSym(f.sym || to);
      if (want === to || (from === to && want === from)) return Number(f.chainId);
    }
    const pick = window.__gwDsUserPickedTo;
    if (pick && Number(pick.chainId) > 0 && Number(pick.chainId) !== src) {
      if (gwDsNormSym(pick.sym) === to) return Number(pick.chainId);
    }
    if (from === to) {
      const f2 = window.__gwDsForceBridgeTo;
      if (f2 && Number(f2.chainId) > 0 && gwDsNormSym(f2.sym || from) === from
        && Number(f2.chainId) !== src) return Number(f2.chainId);
      if (pick && gwDsNormSym(pick.sym) === from
        && Number(pick.chainId) > 0 && Number(pick.chainId) !== src) return Number(pick.chainId);
      const cat = Number(window.__gwDsToCatalogChain) || 0;
      if (cat > 0 && cat !== src) return cat;
    }
  } catch (_) {}
  return 0;
}
try { window.gwDsResolveBridgeDest = gwDsResolveBridgeDest; } catch (_) {}

function gwDsBridgeDestChainId(fromSym) {
  const fromCid = (typeof gwGetActiveUiChainId === 'function') ? Number(gwGetActiveUiChainId()) : 0;
  return gwDsResolveBridgeDest(fromSym, gwDsNormSym(fromSym), fromCid);
}

function gwDsSameAssetBridgeAllowed(fromSym, toSym) {
  const from = gwDsNormSym(fromSym);
  const to = gwDsNormSym(toSym);
  if (from !== to) return false;
  return gwDsBridgeDestChainId(from) > 0;
}

function gwDsPredictFundContext() {
  try {
    if (/(?:^|#)predict\b/i.test(String(location.hash || ''))) return true;
    const pg = document.getElementById('page-predict');
    if (pg && pg.classList.contains('active')) return true;
  } catch (_) {}
  return false;
}

/** Auto-set bridge target when same-asset on another network (USDC→USDC). */
function gwDsEnsureSameAssetBridge(fromSym, toSym) {
  const from = gwDsNormSym(fromSym);
  const to = gwDsNormSym(toSym);
  if (from !== to) return;
  if (gwDsBridgeDestChainId(from) > 0) return;
  const fromCid = (typeof gwGetActiveUiChainId === 'function') ? Number(gwGetActiveUiChainId()) : 0;
  if (!fromCid) return;
  const f = window.__gwDsForceBridgeTo;
  const pick = window.__gwDsUserPickedTo;
  const onPredict = gwDsPredictFundContext();
  let dest = 0;
  if (f && Number(f.chainId) > 0 && Number(f.chainId) !== fromCid) dest = Number(f.chainId);
  else if (pick && gwDsNormSym(pick.sym || '') === from
    && Number(pick.chainId) > 0 && Number(pick.chainId) !== fromCid) dest = Number(pick.chainId);
  else {
    const cat = Number(window.__gwDsToCatalogChain) || 0;
    if (cat > 0 && cat !== fromCid) dest = cat;
  }
  if (!dest && onPredict && (from === 'USDC' || from === 'USDT') && fromCid !== 137) dest = 137;
  if (!dest || dest === fromCid) return;
  try {
    if (!f || Number(f.chainId) !== dest) {
      window.__gwDsForceBridgeTo = {
        chainId: dest, sym: from, at: Date.now(),
        amountUsd: Number(f?.amountUsd) || 0,
        source: onPredict ? 'predict' : (f?.source || 'user'),
      };
    }
    if (!pick || gwDsNormSym(pick.sym) !== from || Number(pick.chainId) !== dest) {
      const curated = (typeof gwTkResolveCuratedToken === 'function')
        ? gwTkResolveCuratedToken(dest, from) : null;
      window.__gwDsUserPickedTo = {
        sym: from, chainId: dest,
        address: curated?.address
          || (dest === 137 && from === 'USDC' ? GW_POLYGON_USDC : (pick?.address || null)),
        decimals: curated?.decimals
          ?? (from === 'USDC' || from === 'USDT' ? 6 : (pick?.decimals ?? 18)),
        name: from, at: Date.now(),
      };
    }
  } catch (_) {}
}
try {
  window.gwDsBridgeDestChainId = gwDsBridgeDestChainId;
  window.gwDsSameAssetBridgeAllowed = gwDsSameAssetBridgeAllowed;
} catch (_) {}

function gwDsEnsureSimpleUi(opts) {
  opts = opts || {};
  try {
    if (!document.getElementById('gwDsCard')) return;
    if (typeof gwDsSimBuildToggle === 'function') gwDsSimBuildToggle();
    if (typeof gwDsSimBuildToggle === 'function') gwDsSimBuildToggle();
    try { gwDsSimUpdatePreview(); } catch (_) {}
  } catch (_) {}
}

async function gwDsRefreshRate() {
  try {
  // Race-safe: only the latest refresh may write UI.
  const seq = ++window.__gwDsQuoteSeq;
  const stillMine = () => seq === window.__gwDsQuoteSeq;
  const finishPreview = () => {
    try { if (typeof gwDsSimUpdatePreview === 'function') gwDsSimUpdatePreview(); } catch (_) {}
  };

  try { window.__gwLastAggQuotes = null; } catch (_) {}
  const t = gwDsLang();
  const routeEl = document.getElementById('gwDsRoute');
  const outEl   = document.getElementById('gwDsOut');
  const amtUsd = document.getElementById('gwDsAmtUsd');
  const outUsd = document.getElementById('gwDsOutUsd');
  if (!routeEl || !outEl) { finishPreview(); return; }
  let rateLine = document.getElementById('gwDsRateLine');
  if (!rateLine) {
    routeEl.className = 'gw-ds-route';
    routeEl.innerHTML = `<span class="k full" id="gwDsRateLine">${t.getting || 'Fetching rate…'}</span>`;
    rateLine = document.getElementById('gwDsRateLine');
  }
  if (!rateLine) { finishPreview(); return; }
  routeEl.className = 'gw-ds-route';

  // Source of truth: Simple row → recent user pick → token button label → select.
  // (Predict fund + late quotes used to leave select=USDT while button said BNB.)
  let from = gwDsNormSym(document.getElementById('gwDsFrom')?.value || 'USDT');
  let to   = gwDsNormSym(document.getElementById('gwDsTo')?.value   || 'BTC');
  try {
    const row = document.querySelector('.gw-ds-wrap.gw-ds-mode-simple .gw-ds-sim-row.on');
    if (row?.dataset?.sym) {
      const rowSym = gwDsNormSym(row.dataset.sym);
      if (rowSym && rowSym !== from) {
        console.warn('[GROM swap] FROM desync: select=', from, 'row=', rowSym, '— using row');
        from = rowSym;
        const fromEl = document.getElementById('gwDsFrom');
        if (fromEl) {
          try { gwDsEnsureTokenOption(from, { sym: from }); } catch (_) {}
          fromEl.value = from;
        }
        try { gwTkSyncButton('from'); } catch (_) {}
        if (row.dataset.cid) {
          const cid = Number(row.dataset.cid);
          if (cid) {
            currentChainId = cid;
            document.querySelectorAll('.gw-ds-chain.on').forEach((x) => x.classList.remove('on'));
            document.querySelector(`.gw-ds-chain[data-cid="${cid}"]`)?.classList.add('on');
          }
        }
      }
    } else if (window.__gwDsUserPickedFrom?.sym) {
      const u = gwDsNormSym(window.__gwDsUserPickedFrom.sym);
      const pickedAt = Number(window.__gwDsUserPickedFrom.at || 0);
      if (u && u !== from && (!pickedAt || Date.now() - pickedAt < 30 * 60 * 1000)) {
        from = u;
        const fromEl = document.getElementById('gwDsFrom');
        if (fromEl) {
          try { gwDsEnsureTokenOption(from, { sym: from }); } catch (_) {}
          fromEl.value = from;
        }
        try { gwTkSyncButton('from'); } catch (_) {}
      }
    } else {
      const btnLbl = gwDsNormSym(document.querySelector('#gwDsFromBtn .lbl')?.textContent || '');
      if (btnLbl && btnLbl !== from) {
        console.warn('[GROM swap] FROM desync: select=', from, 'btn=', btnLbl, '— using button');
        from = btnLbl;
        const fromEl = document.getElementById('gwDsFrom');
        if (fromEl) {
          try { gwDsEnsureTokenOption(from, { sym: from }); } catch (_) {}
          fromEl.value = from;
        }
      }
    }
    if (window.__gwDsUserPickedTo?.sym) {
      const tSym = gwDsNormSym(window.__gwDsUserPickedTo.sym);
      const tAt = Number(window.__gwDsUserPickedTo.at || 0);
      const tCid = Number(window.__gwDsUserPickedTo.chainId) || 0;
      const cat = Number(window.__gwDsToCatalogChain) || 0;
      const payCid = (typeof gwGetActiveUiChainId === 'function')
        ? Number(gwGetActiveUiChainId()) || 0
        : Number(window.__gwDsUserPickedFrom?.chainId) || 0;
      /* Ignore sticky Tron/Sol TO after user switched pay network to EVM. */
      const staleNonevmTo = tCid
        && payCid
        && tCid !== payCid
        && (tCid === GW_TRON_CHAIN_ID || tCid === GW_LIFI_SOL_CHAIN || tCid === 1151111081099710)
        && payCid !== GW_TRON_CHAIN_ID
        && payCid !== GW_LIFI_SOL_CHAIN
        && payCid !== 1151111081099710;
      const staleVsCatalog = tCid && cat && tCid !== cat
        && (tCid === GW_TRON_CHAIN_ID || tCid === GW_LIFI_SOL_CHAIN || tCid === 1151111081099710)
        && cat !== GW_TRON_CHAIN_ID
        && cat !== GW_LIFI_SOL_CHAIN
        && cat !== 1151111081099710;
      if (staleNonevmTo || staleVsCatalog) {
        try {
          const fixed = (typeof gwDsDefaultReceiveSym === 'function')
            ? gwDsDefaultReceiveSym(payCid || cat, from)
            : 'USDC';
          to = fixed;
          const toEl = document.getElementById('gwDsTo');
          if (toEl) {
            try { gwDsEnsureTokenOption(to, { sym: to }); } catch (_) {}
            toEl.value = to;
          }
          window.__gwDsUserPickedTo = {
            sym: to, chainId: payCid || cat || tCid, at: Date.now(),
          };
          try { gwTkSyncButton('to'); } catch (_) {}
        } catch (_) {}
      } else if (tSym && tSym !== to && (!tAt || Date.now() - tAt < 30 * 60 * 1000)) {
        to = tSym;
        const toEl = document.getElementById('gwDsTo');
        if (toEl) {
          try { gwDsEnsureTokenOption(to, { sym: to }); } catch (_) {}
          toEl.value = to;
        }
        try { gwTkSyncButton('to'); } catch (_) {}
      }
    }
  } catch (_) {}
  try {
    const f = window.__gwDsForceBridgeTo;
    if (f && String(f.sym || '').toUpperCase() !== to) {
      /* TO changed away from forced dest token — drop sticky bridge. */
      if (typeof gwDsClearForceBridge === 'function') gwDsClearForceBridge('to-mismatch');
      else if (typeof gwDsClearPredictFundIntent === 'function') {
        gwDsClearPredictFundIntent('to-mismatch', { forceClear: true });
      }
    }
  } catch (_) {}
  // Prefer simple-mode amount (fixes: UI shows 0.0062 but quote used stale gwDsAmt).
  let amtStr = (typeof gwDsReadSwapAmtStr === 'function')
    ? gwDsReadSwapAmtStr()
    : String(document.getElementById('gwDsAmt')?.value || '');
  let amt = Number(amtStr);
  if (!(amt > 0) && amtStr) {
    // keep amtStr for monetary paths even if Number collapsed
    amt = 0;
  }
  // Cap to available balance so Predict's $25 never quotes as 25 USDT when bal is 0.47.
  // Never trust a stale sim.dataset.max from a previous FROM token (ETH/BSC dust max
  // was clamping Base USDC 7.4 → 7.6e-7 scientific notation in the amount box).
  try {
    const sim = document.getElementById('gwDsSimAmt');
    let maxBal = gwDsParseAmt(sim?.dataset?.max);
    const maxSym = String(sim?.dataset?.maxSym || '').toUpperCase();
    const maxCid = Number(sim?.dataset?.maxCid) || 0;
    const fromCid = Number(window.__gwDsUserPickedFrom?.chainId) || 0;
    const fundUsd = Number(window.__gwDsForceBridgeTo?.amountUsd) || 0;
    if (maxBal > 0 && maxSym && maxSym !== from) maxBal = 0;
    if (maxBal > 0 && maxCid && fromCid && maxCid !== fromCid) maxBal = 0;
    /* Dust max on wrong chain — never clamp a real amount down to ~1e-6. */
    if (maxBal > 0 && maxBal < 0.01) maxBal = 0;
    if (maxBal > 0 && fundUsd > 0 && maxBal < fundUsd * 0.05) maxBal = 0;
    if (maxBal > 0 && amt > maxBal * 1.0000001) {
      console.warn('[GROM swap] amount', amt, '> max', maxBal, '— clamping');
      amt = maxBal;
      const human = (typeof gwDsFormatAmtHuman === 'function') ? gwDsFormatAmtHuman(maxBal, 8) : String(maxBal);
      if (sim) sim.value = human;
      const ds = document.getElementById('gwDsAmt');
      if (ds) ds.value = human;
    }
  } catch (_) {}
  /* If amount field somehow holds scientific notation, normalize it. */
  try {
    const ds = document.getElementById('gwDsAmt');
    if (ds && /e/i.test(String(ds.value || '')) && amt > 0) {
      const human = (typeof gwDsFormatAmtHuman === 'function') ? gwDsFormatAmtHuman(amt, 8) : String(amt);
      if (human) { ds.value = human; amtStr = human; }
    }
  } catch (_) {}
  const mode = gwDsGetMode();

  try {
    if (mode === 'onchain' && typeof gwDsSyncChainForFromToken === 'function') {
      await gwDsSyncChainForFromToken(from, { silent: true });
    } else if (mode === 'onchain' && typeof gwDsAutoDetectChainFor === 'function') {
      const autoKey = from;
      window.__gwDsAutoChainAt = window.__gwDsAutoChainAt || {};
      const autoAt = Number(window.__gwDsAutoChainAt[autoKey]) || 0;
      if (!autoAt || Date.now() - autoAt > 12000) {
        window.__gwDsAutoChainAt[autoKey] = Date.now();
        await gwDsAutoDetectChainFor(from, { silent: true });
      }
    }
    if (from === to) gwDsEnsureSameAssetBridge(from, to);
  } catch (_) {}

  gwDsRefreshBalancesDebounced();

  /* Hard cap using the Simple-row max when we already know it. Don't block
   * the quote on 5-chain RPC — that's what made Swap feel frozen. */
  try {
    const sim = document.getElementById('gwDsSimAmt');
    let maxBal = gwDsParseAmt(sim?.dataset?.max);
    const maxSym = String(sim?.dataset?.maxSym || '').toUpperCase();
    const maxCid = Number(sim?.dataset?.maxCid) || 0;
    const fromCid = Number(window.__gwDsUserPickedFrom?.chainId) || 0;
    const fundUsd = Number(window.__gwDsForceBridgeTo?.amountUsd) || 0;
    if (maxBal > 0 && maxSym && maxSym !== from) maxBal = 0;
    if (maxBal > 0 && maxCid && fromCid && maxCid !== fromCid) maxBal = 0;
    if (maxBal > 0 && maxBal < 0.01) maxBal = 0;
    if (maxBal > 0 && fundUsd > 0 && maxBal < fundUsd * 0.05) maxBal = 0;
    if (maxBal > 0 && amt > maxBal * 1.0000001) {
      amt = maxBal;
      const human = (typeof gwDsFormatAmtHuman === 'function') ? gwDsFormatAmtHuman(maxBal, 8) : String(maxBal);
      if (sim) sim.value = human;
      const ds = document.getElementById('gwDsAmt');
      if (ds) { ds.value = human; ds.readOnly = false; ds.disabled = false; }
    }
  } catch (_) {}
  // Background clamp if dataset.max was stale (won't delay first paint).
  try {
    if (amt > 0 && typeof gwDsAvailableAmount === 'function') {
      const fundUsd = Number(window.__gwDsForceBridgeTo?.amountUsd) || 0;
      const fromCid = Number(window.__gwDsUserPickedFrom?.chainId) || 0;
      gwDsAvailableAmount(from, fromCid ? { chainId: fromCid } : undefined).then((avail) => {
        if (!stillMine()) return;
        if (!(avail > 0) || avail < 0.01) return;
        if (fundUsd > 0 && avail < fundUsd * 0.05) return;
        if (!(amt > avail * 1.02)) return;
        const sim = document.getElementById('gwDsSimAmt');
        const ds = document.getElementById('gwDsAmt');
        const canon = (typeof gwDsFormatAmtHuman === 'function')
          ? gwDsFormatAmtHuman(avail, 8)
          : String(avail);
        if (!canon) return;
        if (sim) {
          sim.value = canon;
          sim.dataset.max = String(avail);
          sim.dataset.maxSym = from;
          sim.dataset.maxCid = String(fromCid || '');
        }
        if (ds) { ds.value = canon; ds.readOnly = false; ds.disabled = false; }
        try { gwDsRefreshRate(); } catch (_) {}
      }).catch(() => {});
    }
  } catch (_) {}

  const quoteFrom = from;
  const quoteTo = to;
  const quoteAmt = amt;
  try { gwDsPaintAmtUsd(amt, from); } catch (_) {}

  const uiStillMatches = () => {
    try {
      const fNow = gwDsNormSym(document.getElementById('gwDsFrom')?.value || '');
      const tNow = gwDsNormSym(document.getElementById('gwDsTo')?.value || '');
      const aNow = (typeof gwDsReadSwapAmt === 'function') ? gwDsReadSwapAmt() : gwDsParseAmt(document.getElementById('gwDsAmt')?.value);
      if (fNow && quoteFrom && fNow !== quoteFrom) return false;
      if (tNow && quoteTo && tNow !== quoteTo) return false;
      if (quoteAmt > 0 && aNow > 0 && Math.abs(aNow - quoteAmt) / quoteAmt > 0.02) return false;
      return true;
    } catch (_) { return true; }
  };

  if (amt <= 0) {
    outEl.value = '';
    delete outEl.dataset.pair;
    if (amtUsd) amtUsd.textContent = '';
    if (outUsd) outUsd.textContent = '';
    rateLine.textContent = t.est;
    finishPreview();
    return;
  }
  if (from === to) {
    try { gwDsEnsureSameAssetBridge(from, to); } catch (_) {}
    const allowSame = gwDsSameAssetBridgeAllowed(from, to);
    if (!allowSame) {
      routeEl.className = 'gw-ds-route warn';
      rateLine.textContent = '⚠ Choose different assets';
      outEl.value = '';
      delete outEl.dataset.pair;
      finishPreview();
      return;
    }
    try {
      const destCid = gwDsBridgeDestChainId(from);
      const destLbl = (typeof gwChainLabel === 'function') ? gwChainLabel(destCid) : String(destCid);
      const fromLbl = (typeof gwChainLabel === 'function') ? gwChainLabel(gwGetActiveUiChainId()) : '';
      rateLine.textContent = fromLbl
        ? `Bridge ${from} · ${fromLbl} → ${destLbl}`
        : `Bridge ${from} → ${destLbl}`;
    } catch (_) {}
  }

  gwDsPaintAmtUsd(amt, from);

  rateLine.textContent = t.getting;
  outEl.value = '';
  delete outEl.dataset.pair;
  finishPreview();
  try { gwDsSetQuoteExecReady(false, 'Fetching on-chain route…'); } catch (_) {}

  const midPromise = gwDsMidEstimate(from, to, amt).catch(() => null);

  const applyOut = (outAmt, meta) => {
    if (!stillMine() || !uiStillMatches()) return false;
    const outNum = Number(outAmt);
    const rate = amt > 0 ? outNum / amt : null;
    if (typeof gwDsPublishSimpleQuote === 'function') {
      gwDsPublishSimpleQuote({ from: quoteFrom, to: quoteTo, outAmt: outNum, rate });
    } else {
      outEl.value = Number(outNum.toFixed(8));
      outEl.dataset.pair = quoteFrom + '|' + quoteTo;
      finishPreview();
    }
    if (outUsd) {
      gwDsPriceUsd(quoteTo).then((p) => {
        if (!stillMine() || !uiStillMatches()) return;
        outUsd.textContent = p ? '≈ $' + (outNum * p).toLocaleString('en-US', { maximumFractionDigits: 2 }) : '';
      });
    }
    return true;
  };

  // === TRON (TRX / TRC-20) via SunSwap — Trust DApp browser or TronLink ===
  // Skip same-chain SunSwap when user forced a bridge to another network.
  let bridgeDestEarly = 0;
  try {
    const fromCid0 = (typeof gwGetActiveUiChainId === 'function' ? gwGetActiveUiChainId() : null)
      || Number(window.__gwDsUserPickedFrom?.chainId) || 0;
    bridgeDestEarly = (typeof gwDsResolveBridgeDest === 'function')
      ? gwDsResolveBridgeDest(from, to, fromCid0) : 0;
  } catch (_) {}

  if (!bridgeDestEarly && typeof gwIsTronPair === 'function' && gwIsTronPair(from, to, (typeof gwGetActiveUiChainId === 'function' ? gwGetActiveUiChainId() : null))) {
    try {
      const tronQ = await gwTronQuoteHuman(from, to, amt);
      const outAmt = Number(tronQ?.outAmt || 0);
      if (!stillMine()) return;
      if (outAmt > 0) {
        const rate = amt > 0 ? outAmt / amt : null;
        applyOut(outAmt, { rate });
        if (typeof gwDsPublishSimpleQuote === 'function') {
          gwDsPublishSimpleQuote({ from, to, outAmt, rate });
        }
        const executable = !!tronQ?.executable;
        const slipPct = ((typeof gwSwapSlippageFraction === 'function' ? gwSwapSlippageFraction() : 0.005) * 100).toFixed(1);
        routeEl.innerHTML = `
          <span class="k">${t.route}</span><span class="v">${executable ? 'SunSwap · TRON' : 'Indicative · not executable'}</span>
          <span class="k">${t.slip}</span><span class="v">${slipPct}%</span>
          <span class="k full" id="gwDsRateLine">1 ${from} ≈ ${(rate || 0).toFixed(6)} ${to}${executable ? '' : ' · preview only'}</span>
        `;
        // F22: ready only after real SunSwap amountsOut — never after a reference price
        try {
          gwDsSetQuoteExecReady(executable, executable ? '' : 'Tron route is indicative only — open in TronLink/Trust Tron for SunSwap quote');
        } catch (_) {}
        finishPreview();
        return;
      }
      try { gwDsSetQuoteExecReady(false, 'No SunSwap route for this Tron pair'); } catch (_) {}
    } catch (e) {
      console.warn('[GROM] tron UI quote failed', e?.message || e);
      try { gwDsSetQuoteExecReady(false, 'Tron quote failed'); } catch (_) {}
    }
  }

  // === SOLANA (Jupiter) — only when Solana chip is active (same-chain) ===
  if (!bridgeDestEarly && typeof gwIsSolanaUiActive === 'function' && gwIsSolanaUiActive() && typeof gwSolQuoteHuman === 'function') {
    try {
      const solQ = await gwSolQuoteHuman(from, to, typeof gwDsReadSwapAmtStr === 'function' ? gwDsReadSwapAmtStr() : amt);
      const outAmt = Number(solQ?.outAmt || 0);
      if (!stillMine()) return;
      if (outAmt > 0) {
        const rate = amt > 0 ? outAmt / amt : null;
        applyOut(outAmt, { rate });
        const slipPct = ((typeof gwSwapSlippageFraction === 'function' ? gwSwapSlippageFraction() : 0.005) * 100).toFixed(2);
        routeEl.innerHTML = `
          <span class="k">${t.route}</span><span class="v">Jupiter · Solana</span>
          <span class="k">${t.slip}</span><span class="v">${slipPct}%</span>
          <span class="k full" id="gwDsRateLine">1 ${from} ≈ ${(rate || 0).toFixed(6)} ${to}</span>
        `;
        try { gwDsSetQuoteExecReady(true, ''); } catch (_) {}
        finishPreview();
        return;
      }
      try { gwDsSetQuoteExecReady(false, 'No Jupiter route for this Solana pair'); } catch (_) {}
    } catch (e) {
      console.warn('[GROM] solana UI quote failed', e?.message || e);
      try { gwDsSetQuoteExecReady(false, 'Solana quote failed'); } catch (_) {}
    }
  }

  // === Sol / Tron ↔ EVM (and reverse) via LiFi bridges ===
  try {
    const fromCidBridge = (typeof gwGetActiveUiChainId === 'function' ? gwGetActiveUiChainId() : null)
      || Number(window.__gwDsUserPickedFrom?.chainId) || 0;
    const toCidBridge = bridgeDestEarly
      || (Number(window.__gwDsUserPickedTo?.chainId) > 0
        && Number(window.__gwDsUserPickedTo.chainId) !== Number(fromCidBridge)
        ? Number(window.__gwDsUserPickedTo.chainId) : 0);
    const SOL_ID = (typeof GW_LIFI_SOL_CHAIN !== 'undefined') ? GW_LIFI_SOL_CHAIN : 1151111081099710;
    const TRX_ID = (typeof GW_TRON_CHAIN_ID !== 'undefined') ? GW_TRON_CHAIN_ID : 728126428;
    const isNonevmCid = (id) => Number(id) === SOL_ID || Number(id) === TRX_ID;
    const involvesNonevm = isNonevmCid(fromCidBridge) || isNonevmCid(toCidBridge);
    if (involvesNonevm && toCidBridge && Number(toCidBridge) !== Number(fromCidBridge)
      && amt > 0 && typeof gwAggQuoteLifi === 'function') {
      rateLine.textContent = t.getting || 'Finding bridge route…';
      let acct = null;
      try {
        if (Number(fromCidBridge) === SOL_ID) {
          acct = (typeof gwSolPubkey === 'function' && gwSolPubkey())
            || window.__gwSolAddr || localStorage.getItem('grom_sol_addr');
        } else if (Number(fromCidBridge) === TRX_ID) {
          acct = (typeof gwTronSavedAddr === 'function' && gwTronSavedAddr())
            || window.__gwTronAddr || localStorage.getItem('grom_tron_addr');
        } else {
          acct = (typeof gwDsResolveQuoteAccount === 'function')
            ? gwDsResolveQuoteAccount()
            : (gwReadOnlyAddress() || GW_LIFI_QUOTE_DUMMY);
        }
      } catch (_) {}
      const lifiQ = await gwAggQuoteLifi({
        chainId: fromCidBridge,
        fromSym: from,
        toSym: to,
        amtNum: typeof gwDsReadSwapAmtStr === 'function' ? gwDsReadSwapAmtStr() : amt,
        account: acct,
        toChainId: toCidBridge,
        slippage: String(typeof gwSwapSlippageFraction === 'function' ? gwSwapSlippageFraction() : 0.005),
      });
      if (!stillMine()) return;
      if (lifiQ && typeof lifiQ.toAmount === 'bigint' && lifiQ.toAmount > 0n) {
        const outDec = Number(lifiQ.outDecimals) > 0 ? Number(lifiQ.outDecimals) : 18;
        const outAmt = Number(lifiQ.toAmount) / (10 ** outDec);
        const rate = amt > 0 ? outAmt / amt : null;
        applyOut(outAmt, { rate });
        const tool = lifiQ.tool || 'LiFi';
        const fromLbl = (typeof gwTkChainShort === 'function') ? gwTkChainShort(fromCidBridge) : String(fromCidBridge);
        const toLbl = (typeof gwTkChainShort === 'function') ? gwTkChainShort(toCidBridge) : String(toCidBridge);
        const slipPct = ((typeof gwSwapSlippageFraction === 'function' ? gwSwapSlippageFraction() : 0.005) * 100).toFixed(2);
        const canExec = !!lifiQ.transactionRequest || !!lifiQ.raw?.transactionRequest;
        routeEl.innerHTML = `
          <span class="k">${t.route}</span><span class="v">${tool} · ${fromLbl} → ${toLbl}</span>
          <span class="k">${t.slip}</span><span class="v">${slipPct}%</span>
          <span class="k full" id="gwDsRateLine">1 ${from} ≈ ${(rate || 0).toFixed(6)} ${to}${canExec ? '' : ' · quote only'}</span>
        `;
        try {
          window.__gwLastAggQuotes = {
            at: Date.now(), chainId: fromCidBridge, from, to, amt,
            quotes: [lifiQ],
          };
        } catch (_) {}
        try {
          gwDsSetQuoteExecReady(canExec, canExec ? '' : 'Bridge quote ready — connect source wallet to execute');
        } catch (_) {}
        finishPreview();
        return;
      }
      try { gwDsSetQuoteExecReady(false, 'No LiFi bridge route for this pair/network'); } catch (_) {}
    }
  } catch (e) {
    console.warn('[GROM] nonevm bridge quote', e?.message || e);
  }

  // === ON-CHAIN meta-aggregator ===
  if (mode === 'onchain') {
    try {
      const account = (typeof gwDsResolveQuoteAccount === 'function')
        ? gwDsResolveQuoteAccount()
        : (gwReadOnlyAddress() || GW_LIFI_QUOTE_DUMMY);
      const provider = (window.gromWallet?.wcProvider && window.gromWallet.wcProvider.accounts?.[0])
        ? window.gromWallet.wcProvider
        : window.ethereum;
      if (account) {
        let chainId = (typeof gwGetActiveUiChainId === 'function' ? gwGetActiveUiChainId() : null);
        let walletCid = 0;
        if (provider) {
          try {
            const hex = await Promise.race([
              provider.request({ method: 'eth_chainId' }),
              new Promise((_, rej) => setTimeout(() => rej(new Error('wc-timeout')), 500)),
            ]);
            walletCid = parseInt(hex, 16);
            if (!chainId) chainId = walletCid;
          } catch (_) {}
        }
        if (!chainId) {
          try { chainId = Number(window.__gwDsUserPickedFrom?.chainId) || 0; } catch (_) {}
        }
        if (!chainId) chainId = gwResolveSwapChainId(walletCid || 42161);
        /* Sync chip to wallet on first load when user hasn't picked a network yet. */
        if (walletCid && !window.__gwDsUserPickedChain && !window.__gwDsUserPickedFrom?.chainId) {
          try { gwDsSetActiveChain(walletCid); } catch (_) {}
          chainId = walletCid;
        }
        if (typeof gwDsResolveSwapChainFor === 'function') {
          try { chainId = await gwDsResolveSwapChainFor(from, walletCid || chainId); } catch (_) {}
        }
        currentChainId = chainId;
        if (!stillMine()) return;
        console.log('[GROM swap] refresh', { seq, chainId, from, to, amt });
        // Only wait for catalog when FROM isn't already known on this chain.
        let fromTok = typeof gwResolveEvmToken === 'function' ? gwResolveEvmToken(chainId, from, 'from') : null;
        if (!fromTok && typeof gwLifiEnsureChainTokens === 'function') {
          try {
            await Promise.race([
              gwLifiEnsureChainTokens(chainId),
              new Promise((r) => setTimeout(r, 1200)),
            ]);
          } catch (_) {}
          fromTok = typeof gwResolveEvmToken === 'function' ? gwResolveEvmToken(chainId, from, 'from') : null;
        }
        if (!fromTok) {
          console.warn('[GROM swap] FROM not on chain', chainId, from, '— trying bridge aggregators');
        }
        // TO may live on another network — best-route will bridge automatically.

        window.__gwLastAggQuotes = null;
        rateLine.textContent = t.getting || 'Finding best route across DEXes…';
        const quoteFn = (typeof gwMetaAggQuoteBest === 'function') ? gwMetaAggQuoteBest : gwMetaAggQuoteAll;
        let painted = false;
        const paintQuotes = (quotes) => {
          if (!stillMine() || !quotes || !quotes.length) return false;
          const midNow = window.__gwDsMidEst && window.__gwDsMidEst.key === (from + '|' + to + '|' + amt)
            ? window.__gwDsMidEst.mid : null;
          const decFor = (q) => {
            const cid = Number(q?._toChainId || chainId);
            if (Number(q?.outDecimals) > 0) return Number(q.outDecimals);
            return (typeof gwOcCanonicalDecimals === 'function')
              ? gwOcCanonicalDecimals(cid, to)
              : (GW_OC_SWAP[cid]?.decimals?.[to] ?? 18);
          };
          let saneQuotes = quotes.filter((q) => gwDsQuoteSane(Number(q.toAmount) / 10 ** decFor(q), midNow));
          if (!saneQuotes.length && quotes.length) {
            saneQuotes = quotes.filter((q) => gwDsQuoteSane(Number(q.toAmount) / 10 ** decFor(q), midNow, { loose: true }));
          }
          /* Venue fund (HL Arb / Predict Polygon): never paint a wrong-chain winner. */
          try {
            const forceTo = Number(window.__gwDsForceBridgeTo?.chainId) || 0;
            if (forceTo) {
              const pool = (saneQuotes.length ? saneQuotes : quotes).filter((q) => Number(q._toChainId) === forceTo);
              saneQuotes = pool;
              if (!pool.length) return false;
            }
          } catch (_) {}
          const useQuotes = saneQuotes.length ? saneQuotes : (quotes.length ? [quotes[0]] : []);
          if (!useQuotes.length) return false;
          window.__gwLastAggQuotes = {
            chainId, fromSym: from, toSym: to, amtNum: amt, quotes: useQuotes, at: Date.now(),
            account: String(account || '').toLowerCase(),
          };
          const execQuotes = useQuotes.filter(gwAggCanExec);
          const winner = execQuotes[0] || useQuotes[0];
          const outDec = decFor(winner);
          const winnerOut = Number(winner.toAmount) / 10 ** outDec;
          applyOut(winnerOut);
          painted = true;
          const rate = amt > 0 ? (winnerOut / amt).toFixed(8).replace(/0+$/, '').replace(/\.$/, '') : '';
          const gasUsd = winner.gasUsd != null && Number.isFinite(Number(winner.gasUsd)) ? Number(winner.gasUsd).toFixed(2) : null;
          const cmp = useQuotes.slice(0, 5).map((q, i) => {
            const out = Number(q.toAmount) / 10 ** decFor(q);
            const winMark = i === 0 ? '✓ ' : '';
            const bridgeMark = q._crossChain ? ' ⇄' : '';
            const outFmt = out.toLocaleString('en-US', { maximumFractionDigits: Math.min(decFor(q), 6) });
            return `<span class="agg${i === 0 ? ' win' : ''}">${winMark}${q.aggregator}${bridgeMark} ${outFmt}</span>`;
          }).join(' · ');
          const hopsHtml  = gwDsRouteHopsHtml(winner);
          const fromLbl = (typeof gwChainLabel === 'function') ? gwChainLabel(chainId) : String(chainId);
          const toCid = Number(winner._toChainId || chainId);
          const toLbl = (typeof gwChainLabel === 'function') ? gwChainLabel(toCid) : String(toCid);
          const routeTitle = winner._crossChain
            ? `${winner.aggregator} · ${fromLbl} → ${toLbl}`
            : `${winner.aggregator} · ${winner.tool || 'best'}`;
          const bridgeNote = winner._crossChain
            ? `<span class="k full" style="color:#9ecbff">${gwUxText('Межсетевой обмен · Получение:','Cross-chain swap · Receive:')} ${gwUxEsc(to)} · ${gwUxEsc(toLbl)}</span>`
            : '';
          const tried = Number(window.__gromMetaQuoteTried) || useQuotes.length;
          const got = useQuotes.length;
          const srcLine = `${got} / ${tried} ${gwUxText('источников ответили','sources responded')}`;
          if (!stillMine()) return true;
          routeEl.innerHTML = `
            <span class="k">${t.route}</span><span class="v">${routeTitle}</span>
            ${gwUxDetails(winner, outDec, gasUsd)}
            <span class="k">${t.slip}</span><span class="v">${((Number(winner._gromSlippage) > 0 ? Number(winner._gromSlippage) : gwSwapSlippageFraction()) * 100).toFixed(2)}%</span>

            <span class="k full" id="gwDsRateLine">1 ${from} ≈ ${rate} ${to}</span>
            <span class="k full agg-cmp">${cmp} · ${srcLine}</span>
            ${bridgeNote}
            <span class="k full" id="gwDsPimpSlot"></span>
            <span class="k full">${hopsHtml}</span>
            <span class="k full" id="gwDsAiTipSlot"></span>
          `;
          gwDsSetQuoteExecReady(!!execQuotes.length, execQuotes.length
            ? ''
            : (winner._crossChain
              ? (`Route preview only — no fee-ready bridge ${fromLbl}→${toLbl} for ${to}. Stay on pay network & wait, or pick ${to} again from Trending.`)
              : 'Route preview only — no wallet-ready path. Try another network.'));
          return true;
        };
        midPromise.then((mid) => {
          try { window.__gwDsMidEst = { key: from + '|' + to + '|' + amt, mid }; } catch (_) {}
        }).catch(() => {});
        const [quotes, mid] = await Promise.all([
          quoteFn({
            chainId, fromSym: from, toSym: to, amtNum: amt, account,
            onPartial: (partial) => { try { paintQuotes(partial); } catch (_) {} },
          }),
          midPromise,
        ]);
        if (!stillMine()) return;
        try { window.__gwDsMidEst = { key: from + '|' + to + '|' + amt, mid }; } catch (_) {}
        console.log('[GROM swap] quotes', quotes.length, '/', (window.__gromMetaQuoteTried || '?'),
          quotes.map(q => q.aggregator + (q._crossChain ? '🌉' : '')).slice(0, 8));

        if (paintQuotes(quotes) || painted) {
          const winner = (window.__gwLastAggQuotes?.quotes || []).filter(gwAggCanExec)[0]
            || (window.__gwLastAggQuotes?.quotes || [])[0];
          if (winner && !winner._crossChain) {
            gwAggQuoteLifi({ chainId, fromSym: from, toSym: to, amtNum: amt / 10, account })
              .then((smallQ) => {
                if (!stillMine() || !smallQ?.toAmount) return;
                const outDec = Number(winner.outDecimals) || 18;
                const smallRate = Number(smallQ.toAmount) * 10 / 10 ** outDec / amt;
                const bigRate   = Number(winner.toAmount) / 10 ** outDec / amt;
                const impactPct = Math.max(0, ((smallRate - bigRate) / smallRate) * 100);
                const slot = document.getElementById('gwDsPimpSlot');
                if (slot) slot.outerHTML = gwDsPriceImpactHtml(impactPct);
              })
              .catch(() => {});
          }
          if (winner) {
            gwAiSplitTip({ chainId, fromSym: from, toSym: to, amtNum: amt, account, winnerQuote: winner })
              .then((tip) => {
                if (!stillMine()) return;
                const slot = document.getElementById('gwDsAiTipSlot');
                if (slot && tip) { slot.outerHTML = gwAiTipBanner(tip, { fromSym: from, toSym: to, amtNum: amt }); setTimeout(gwWireAiTipButton, 0); }
              })
              .catch(() => {});
          }
          return;
        }
      }
    } catch (e) {
      console.warn('[GROM] meta-agg quote (UI) failed, falling back to cross-rate:', e?.message || e);
    }
  }

  if (!stillMine()) return;

  const mid = await midPromise;
  if (!stillMine()) return;

  // Instant Swap is aggregator-only.
  if (!stillMine()) return;
  if (mid && mid.est > 0) {
    /* Never clobber a live fee-verified aggregator route with CoinGecko mid.
     * Race: meta-agg paints executable → mid resolves late → "estimate only"
     * and CTA stuck on Waiting for route (soft reconnect cannot Start). */
    try {
      const cached = window.__gwLastAggQuotes;
      const samePair = cached
        && (typeof gwDsNormSym === 'function'
          ? gwDsNormSym(cached.fromSym) === from && gwDsNormSym(cached.toSym) === to
          : String(cached.fromSym || '').toUpperCase() === from
            && String(cached.toSym || '').toUpperCase() === to)
        && Math.abs(Number(cached.amtNum) - amt) < 1e-9;
      const hasExec = samePair
        && Array.isArray(cached.quotes)
        && cached.quotes.some((q) => (typeof gwAggCanExec === 'function')
          ? gwAggCanExec(q)
          : (typeof gwIsFeeVerified === 'function' && gwIsFeeVerified(q)));
      const fresh = samePair && (Date.now() - Number(cached.at || 0) < 30000);
      if (hasExec && fresh) {
        if (!window.__gwDsQuoteExecReady) {
          try { gwDsSetQuoteExecReady(true, ''); } catch (_) {}
        }
        finishPreview();
        return;
      }
    } catch (_) {}
    /* Preview-only mid from CoinGecko path — never executable without fee-verified aggregator */
    applyOut(mid.est);
    rateLine.textContent = `1 ${from} ≈ ${mid.rate.toFixed(6)} ${to}`;
    routeEl.className = 'gw-ds-route warn';
    const bridgeHint = '⚠ No fee-verified aggregator route — try another pair or network';
    let bridgeHint2 = bridgeHint;
    try {
      const forceTo = Number(window.__gwDsForceBridgeTo?.chainId)
        || Number(window.__gwDsUserPickedTo?.chainId) || 0;
      const uiCid = typeof gwGetActiveUiChainId === 'function' ? Number(gwGetActiveUiChainId()) : 0;
      if (forceTo && uiCid && forceTo !== uiCid) {
        const fromLbl = (typeof gwChainLabel === 'function') ? gwChainLabel(uiCid) : String(uiCid);
        const toLbl = (typeof gwChainLabel === 'function') ? gwChainLabel(forceTo) : String(forceTo);
        bridgeHint2 = `⚠ No fee-ready bridge ${fromLbl}→${toLbl} for ${to} yet — wait a few seconds or pick ${to} again from Trending`;
      }
    } catch (_) {}
    routeEl.innerHTML = `
      <span class="k">${t.route}</span><span class="v">estimate only · not executable</span>
      <span class="k full" id="gwDsRateLine">1 ${from} ≈ ${mid.rate.toFixed(6)} ${to}</span>
      <span class="k full" style="color:#fbbf24">${bridgeHint2}</span>
    `;
    try { gwDsSetQuoteExecReady(false, bridgeHint2.replace(/^⚠\s*/, '')); } catch (_) {}
    return;
  }

  try { gwDsSetQuoteExecReady(false, 'Rate unavailable — check amount and network'); } catch (_) {}
  routeEl.className = 'gw-ds-route err';
  let failMsg = t.rateFail || 'Rate unavailable';
  try {
    const uiCid = typeof gwGetActiveUiChainId === 'function' ? gwGetActiveUiChainId() : 0;
    const bridgeDest = (typeof gwDsResolveBridgeDest === 'function')
      ? gwDsResolveBridgeDest(from, to, uiCid || 0) : 0;
    if (bridgeDest > 0) {
      failMsg = t.rateFailBridge || failMsg;
    } else if (typeof gwTokenChainHint === 'function') {
      failMsg = gwTokenChainHint(to, uiCid || 0);
    }
  } catch (_) {}
  rateLine.textContent = failMsg;
  outEl.value = '';
  delete outEl.dataset.pair;
  finishPreview();
  } catch (e) {
    console.warn('[GROM] gwDsRefreshRate', e?.message || e);
    try { finishPreview(); } catch (_) {}
  }
}


async function gwDsRefreshBalances() {
  const seq = window.__gwDsBalanceSeq = (window.__gwDsBalanceSeq || 0) + 1;
  const context = () => JSON.stringify([document.getElementById('gwDsFrom')?.value,
    document.getElementById('gwDsTo')?.value, window.__gwDsUserPickedFrom, window.__gwDsUserPickedTo,
    gwOcConnectedAddress(), window.__gwDsForceBridgeTo]);
  const key = context();
  const current = () => seq === window.__gwDsBalanceSeq && context() === key;
  const from = document.getElementById('gwDsFrom')?.value;
  const to   = document.getElementById('gwDsTo')?.value;
  const bFrom = document.getElementById('gwDsBalFrom');
  const bTo   = document.getElementById('gwDsBalTo');
  if (bFrom) { bFrom.textContent = ''; delete bFrom.dataset.max; delete bFrom.dataset.maxSym; delete bFrom.dataset.maxCid; }
  if (bTo) bTo.textContent = '';
  if (bFrom && from) {
    const fromCid = Number(window.__gwDsUserPickedFrom?.chainId)
      || (typeof gwGetActiveUiChainId === 'function' ? gwGetActiveUiChainId() : 0)
      || 0;
    const v = await gwDsAvailableAmount(from, fromCid ? { chainId: fromCid } : undefined);
    if (!current()) return;
    bFrom.classList.toggle('clickable', v > 0);
    if (v > 0) {
      bFrom.dataset.max = String(v);
      bFrom.dataset.maxSym = String(from).toUpperCase();
      bFrom.dataset.maxCid = String(fromCid || '');
    } else {
      delete bFrom.dataset.max;
      delete bFrom.dataset.maxSym;
      delete bFrom.dataset.maxCid;
    }
    bFrom.textContent = v > 0 ? `${gwDsLang().bal}: ${Number(v).toFixed(6).replace(/0+$/, '').replace(/\.$/, '')} ${from}` : '';
  }
  if (bTo && to) {
    const destCid = Number(window.__gwDsUserPickedTo?.chainId) || gwTkGetToCatalogChain(gwTkGetFromContext().chainId);
    if (destCid > 0) {
      const destLbl = (typeof gwChainLabel === 'function') ? gwChainLabel(destCid) : String(destCid);
      let vDest = 0;
      try {
        if (destCid === GW_LIFI_SOL_CHAIN) vDest = await gwSolAvailableAmount(to);
        else if (destCid === GW_TRON_CHAIN_ID) {
          const rows = await gwTronFetchAllBalances(gwTronSavedAddr());
          vDest = Number(rows.find(r => r.sym === to)?.amt) || 0;
        } else vDest = await gwDsTokenBalanceOnChain(to, destCid);
      } catch (_) {}
      if (!current()) return;
      const balPart = vDest > 0
        ? `${gwDsLang().bal}: ${Number(vDest).toFixed(6).replace(/0+$/, '').replace(/\.$/, '')} ${to} · `
        : '';
      bTo.textContent = `${balPart}→ ${destLbl}`;
    } else {
      const v = await gwDsAvailableAmount(to);
      if (!current()) return;
      bTo.textContent = v > 0 ? `${gwDsLang().bal}: ${Number(v).toFixed(6).replace(/0+$/, '').replace(/\.$/, '')} ${to}` : '';
    }
  }
}

const gwDsRefreshBalancesDebounced = gwDebounce(() => {
  gwDsRefreshBalances().catch(() => {});
}, 900);

/* ============================================================================
 * INLINE ON-CHAIN SWAP — no external tabs, direct wallet signing.
 *
 * Chain 56 (BSC) → PancakeSwap V2 router (0x10ED4…4E)
 * Chain 1  (ETH) → Uniswap V2 router      (0x7a250…88D)
 * Others         → throw 'unsupported' so caller can fall back to 1inch tab.
 *
 * We hand-encode ABI calls to avoid pulling ethers.js at load time. The
 * encoded selectors + parameter layout come straight from the standard
 * UniswapV2Router02 interface (swapExactETHForTokens / swapExactTokensForETH /
 * swapExactTokensForTokens + getAmountsOut). ERC-20 approve is checked and
 * granted with MaxUint256 to avoid re-approvals on subsequent swaps.
 *
 * Slippage: 0.5% (hard-coded, matches DEX aggregator defaults). */
/* Every EVM chain we support has its native V2-style DEX router. Uniswap-V2
 * ABI is essentially identical across all of these (swapExactETHForTokens,
 * getAmountsOut, approve(MaxUint256)), so the same hand-encoded calldata
 * works for every one — we only differ in router address, wrapped-native
 * address and token addresses. */
