/* Note: Solana (`chainId 1151111081099710` in LiFi) is not in
 * GW_OC_SWAP because we don't have an inline V2-router fallback for it
 * (it isn't EVM). LiFi handles the swap end-to-end for Solana; when the
 * user connects a Phantom wallet we route them straight to LiFi's tx
 * signer. Bitcoin also goes fully through LiFi (via THORchain) — no
 * inline path possible. Tron uses its dedicated TronWeb + SunSwap path. */

/* ----- minimal ABI encoders ----- */
function gwHex(n) { return BigInt(n).toString(16); }
function gwPad32(hex) { return hex.replace(/^0x/, '').padStart(64, '0'); }
function gwUint256(n) { return gwPad32(gwHex(n)); }
function gwAddr(a) { return gwPad32(a.toLowerCase().replace(/^0x/, '')); }
function gwEncodeAddrArray(arr, base) {
  // address[] as a dynamic parameter, starting at offset `base`
  let out = gwUint256(arr.length);
  for (const a of arr) out += gwAddr(a);
  return out;
}

/* Call read-only method (eth_call) — routed to PUBLIC RPC, not the WC
 * provider. WalletConnect sessions only declare eth_sendTransaction /
 * personal_sign / signTypedData in their `methods` list, so calling
 * eth_call via provider.request throws "Missing or invalid. request()
 * method: eth_call". Public RPCs answer read-only queries fine and
 * gwRpcTry has fallback chain (publicnode/Ankr/llama). */
async function gwEthCall(provider, to, data, chainIdHint) {
  let chainId = Number(chainIdHint) || null;
  if (!chainId) {
    try {
      const ui = typeof gwGetActiveUiChainId === 'function' ? gwGetActiveUiChainId() : null;
      if (ui) chainId = ui;
    } catch (_) {}
  }
  if (!chainId) {
    try {
      const hex = await provider.request({ method: 'eth_chainId' });
      chainId = parseInt(hex, 16);
    } catch (_) { chainId = currentChainId || 42161; }
  }
  try {
    return await gwRpcTry(chainId, 'eth_call', [{ to, data }, 'latest']);
  } catch (_) {
    // Last resort — try the wallet provider (some Trust builds do
    // support eth_call). If wallet rejects, throw the more helpful msg.
    try { return await provider.request({ method: 'eth_call', params: [{ to, data }, 'latest'] }); }
    catch (e) { throw new Error(`read-only call failed: ${e?.message || e}`); }
  }
}

/* getAmountsOut(uint256 amountIn, address[] path) -> uint256[] */
async function gwGetAmountsOut(provider, router, amountIn, path, chainId) {
  const selector = '0xd06ca61f';
  // Params: uint256 amountIn, uint256 offset_to_path (0x40), then dynamic array
  const data = selector
    + gwUint256(amountIn)
    + gwUint256(0x40)
    + gwEncodeAddrArray(path, 0);
  const raw = await gwEthCall(provider, router, data, chainId);
  // Parse array: skip head (0x20 offset), read length, then N * 32 bytes
  const hex = raw.replace(/^0x/, '');
  const arrayLen = parseInt(hex.slice(64, 128), 16);
  const outs = [];
  for (let i = 0; i < arrayLen; i++) {
    const start = 128 + i * 64;
    outs.push(BigInt('0x' + hex.slice(start, start + 64)));
  }
  return outs;
}

/* ERC-20 allowance(owner, spender) -> uint256 */
async function gwErc20Allowance(provider, token, owner, spender, chainId) {
  const data = '0xdd62ed3e' + gwAddr(owner) + gwAddr(spender);
  const raw = await gwEthCall(provider, token, data, chainId);
  return BigInt(raw || '0x0');
}

/* Send: ERC-20 approve(spender, MaxUint256). Waits for receipt.
 * Skip entirely when allowance already covers `needed` (fewer Trust prompts).
 * USDT mainnet reset-to-0 only when existing allowance is positive but too low. */
async function gwErc20ApproveMax(provider, token, spender, from, chainId, needed) {
  try { window.__gwSwapSigPrompted = true; } catch (_) {}
  const tokenLc = String(token || '').toLowerCase();
  const need = (needed != null && BigInt(needed) > 0n) ? BigInt(needed) : null;
  let allow = 0n;
  try { allow = await gwErc20Allowance(provider, token, from, spender, chainId); } catch (_) { allow = 0n; }
  if (need != null && allow >= need) return null;
  /* Already unlimited — nothing to do. */
  if (allow >= (2n ** 200n)) return null;

  const USDT_RESET = new Set(['0xdac17f958d2ee523a2206206994597c13d831ec7']);
  if (USDT_RESET.has(tokenLc) && allow > 0n) {
    try {
      gwWakeWalletForSigning({ action: 'approve', step: '1/2' });
    } catch (_) {}
    const data0 = '0x095ea7b3' + gwAddr(spender) + '0'.repeat(64);
    const hash0 = await gwProviderSendTx(provider, { from, to: token, data: data0, value: '0x0' }, 180000, chainId);
    await gwWaitReceipt(provider, hash0, 90000, true, chainId);
  }
  try {
    gwWakeWalletForSigning({ action: 'approve', step: USDT_RESET.has(tokenLc) && allow > 0n ? '2/2' : '' });
  } catch (_) {}
  const MAX = 'f'.repeat(64);
  const data = '0x095ea7b3' + gwAddr(spender) + MAX;
  const hash = await gwProviderSendTx(provider, { from, to: token, data, value: '0x0' }, 180000, chainId);
  await gwWaitReceipt(provider, hash, 90000, true, chainId);
  return hash;
}
/* Other modules (Hyperliquid deposit) need these — without the export they
 * silently fell back to a hand-rolled approve with a wrong selector. */
try {
  window.gwErc20ApproveMax = gwErc20ApproveMax;
  window.gwErc20Allowance = gwErc20Allowance;
} catch (_) {}

async function gwWaitReceipt(provider, hash, timeoutMs = 60000, isApprove = false, chainIdHint) {
  const start = Date.now();
  const chainId = Number(chainIdHint) || Number(currentChainId) || (typeof gwGetActiveUiChainId === 'function' ? gwGetActiveUiChainId() : null) || 42161;
  /* One quiet wait — no 1.5s toast spam while coach already says "confirm in wallet". */
  let tickId = null;
  const quiet = !!window.__gwSignCoachVisible;
  if (!quiet) {
    try { gwToast(isApprove ? 'Waiting for approve…' : 'Waiting for confirmation…', 'info'); } catch (_) {}
  }

  while (Date.now() - start < timeoutMs) {
    try {
      const r = await gwRpcTry(chainId, 'eth_getTransactionReceipt', [hash]);
      if (r && (r.status === '0x1' || r.status === 1 || r.status === true)) {
        if (tickId) clearInterval(tickId);
        if (!quiet) {
          try { gwToast(isApprove ? 'Approved ✓' : 'Confirmed ✓', 'success'); } catch (_) {}
        }
        return r;
      }
      if (r && (r.status === '0x0' || r.status === 0)) {
        if (tickId) clearInterval(tickId);
        throw new Error('Transaction reverted on-chain');
      }
    } catch (e) {
      if (String(e?.message || '').includes('reverted')) { if (tickId) clearInterval(tickId); throw e; }
    }
    await new Promise((r) => setTimeout(r, 500));
  }
  if (tickId) clearInterval(tickId);
  throw new Error('Transaction timed out — check your wallet');
}
try { window.gwWaitReceipt = gwWaitReceipt; } catch (_) {}

