function gwChainGasSymbol(chainId) {
  const c = Number(chainId);
  if (c === 56) return 'BNB';
  if (c === 137) return 'POL';
  if (c === 43114) return 'AVAX';
  return 'ETH';
}

/** Min native USD on the swap source chain before an ERC-20 / bridge tx. */
const GW_GAS_MIN_USD = 0.20;
/** Target native top-up size when source gas is empty (~covers several txs). */
const GW_GAS_TOPUP_USD = 1.25;
/** Absolute USD ceiling — never ask Trust for more than this as a "gas top-up". */
const GW_GAS_TOPUP_MAX_USD = 2.00;
/** Donor must keep at least this much USD of native after top-up (own gas). */
const GW_GAS_DONOR_KEEP_USD = 0.80;
/** Hard caps in native units — blocks bad prices / min-bridge quote blowups (~$900 ETH). */
const GW_GAS_TOPUP_MAX_NATIVE = {
  ETH: 0.002, WETH: 0.002, BNB: 0.01, AVAX: 0.08, POL: 4, MATIC: 4, TRX: 8, SOL: 0.02,
};
/** Tron: need ~1+ TRX for approve + SunSwap (energy/bandwidth). */
const GW_TRON_GAS_MIN_TRX = 1.0;
const GW_TRON_GAS_TOPUP_TRX = 2.5;
/** Solana: keep a little SOL for fees. */
const GW_SOL_GAS_MIN_SOL = 0.008;
const GW_SOL_GAS_TOPUP_SOL = 0.02;

function gwGasUiRu() {
  try {
    const lang = localStorage.getItem('grom_lang') || document.documentElement.lang || 'en';
    return String(lang).toLowerCase().startsWith('ru');
  } catch (_) { return false; }
}

const GW_GAS_ETH_HUBS = [1, 42161, 10, 8453, 59144];
const GW_GAS_ALL_HUBS = [1, 56, 42161, 137, 10, 8453, 43114, 59144];

async function gwGasNativeUsdPrice(sym) {
  const s = String(sym || 'ETH').toUpperCase();
  const floors = { ETH: 500, WETH: 500, BNB: 50, AVAX: 5, POL: 0.05, MATIC: 0.05, SOL: 20, TRX: 0.05 };
  const fallbacks = { ETH: 2400, WETH: 2400, BNB: 600, AVAX: 20, POL: 0.25, MATIC: 0.25, SOL: 140, TRX: 0.25 };
  let px = 0;
  try {
    if (typeof gwDsPriceUsd === 'function') {
      px = Number(await gwDsPriceUsd(s)) || 0;
    }
  } catch (_) {}
  const floor = floors[s] || 0;
  const fb = fallbacks[s] != null ? fallbacks[s] : 2400;
  if (!(px > 0) || (floor > 0 && px < floor)) px = fb;
  return px;
}

async function gwGasNativeBal(chainId) {
  const gas = gwChainGasSymbol(chainId);
  try {
    if (typeof gwDsTokenBalanceOnChain === 'function') {
      return Number(await gwDsTokenBalanceOnChain(gas, chainId)) || 0;
    }
  } catch (_) {}
  return 0;
}

/**
 * Find another EVM hub with enough of the same gas token to fund a top-up.
 * ETH on Base is topped up from ETH on Ethereum/Arb/OP — never from BNB.
 */
async function gwGasFindDonor(destChainId, gasSym) {
  const dest = Number(destChainId);
  const sym = String(gasSym || 'ETH').toUpperCase();
  const hubs = (sym === 'ETH' ? GW_GAS_ETH_HUBS : GW_GAS_ALL_HUBS)
    .filter((c) => c && c !== dest && GW_OC_SWAP[c]);
  const px = await gwGasNativeUsdPrice(sym);
  const need = (GW_GAS_TOPUP_USD + GW_GAS_DONOR_KEEP_USD) / (px > 0 ? px : 1);
  let best = null;
  for (const c of hubs) {
    if (gwChainGasSymbol(c) !== sym) continue;
    const bal = await gwGasNativeBal(c);
    if (!(bal >= need)) continue;
    if (!best || bal > best.bal) best = { chainId: c, bal, sym, px };
  }
  return best;
}

async function gwGasQuoteNativeBridge({ fromChainId, toChainId, sym, amtNum, account }) {
  const jobs = [];
  if (typeof gwAggQuoteLifi === 'function') {
    jobs.push(gwAggQuoteLifi({
      chainId: fromChainId, fromSym: sym, toSym: sym, amtNum, account, toChainId,
      slippage: String(typeof gwSwapSlippageFraction === 'function' ? gwSwapSlippageFraction() : 0.005),
    }).catch(() => null));
  }
  if (typeof gwAggQuoteSquid === 'function') {
    jobs.push(gwAggQuoteSquid({
      chainId: fromChainId, fromSym: sym, toSym: sym, amtNum, account, toChainId,
    }).catch(() => null));
  }
  if (!jobs.length) return null;
  const settled = await Promise.all(jobs);
  const ok = settled.filter((q) => q && typeof q.toAmount === 'bigint' && q.toAmount > 0n);
  ok.sort((a, b) => (b.toAmount > a.toAmount ? 1 : b.toAmount < a.toAmount ? -1 : 0));
  return ok[0] || null;
}

async function gwGasTokenUsdPrice(sym) {
  const s = String(sym || '').toUpperCase();
  if (/^(USDT|USDC|DAI|BUSD|FDUSD|TUSD|USDD)$/.test(s)) return 1;
  try {
    if (typeof gwDsPriceUsd === 'function') {
      const px = Number(await gwDsPriceUsd(s)) || 0;
      if (px > 0) return px;
    }
  } catch (_) {}
  if (s === 'TRX') return 0.25;
  if (s === 'SOL') return 140;
  return 0;
}

/** How much of `fromSym` to spend to buy ~`topUpUsd` of gas (with pad + caps). */
async function gwGasComputeSpendAmt(fromSym, topUpUsd) {
  const s = String(fromSym || '').toUpperCase();
  const usd = Math.min(GW_GAS_TOPUP_MAX_USD, Math.max(0.4, Number(topUpUsd) || GW_GAS_TOPUP_USD));
  const px = await gwGasTokenUsdPrice(s);
  if (!(px > 0)) {
    const err = new Error(gwGasUiRu()
      ? ('Не удалось оценить ' + s + ' для догрузки газа')
      : ('Cannot price ' + s + ' for gas top-up'));
    err.code = 'GAS_TOPUP_BAD_AMT';
    throw err;
  }
  let amt = (usd / px) * 1.1;
  if (px >= 0.9 && amt > 5) amt = Math.min(amt, usd * 1.25);
  if (px < 0.9 && amt > 500) amt = Math.min(amt, 500);
  return Number(amt.toPrecision(6));
}

/**
 * Same-chain: swap a slice of fromSym → native gas (extra Trust Confirm),
 * then the main swap continues in the same Start click.
 */
async function gwGasExecSameChainTokenTopUp({ chainId, fromSym, gasSym, account, provider }) {
  const dest = Number(chainId);
  const from = String(fromSym || '').toUpperCase();
  const gas = String(gasSym || '').toUpperCase();
  if (!dest || !from || !gas || from === gas) return null;
  let spend = await gwGasComputeSpendAmt(from, GW_GAS_TOPUP_USD);
  let bal = 0;
  try { bal = Number(await gwDsTokenBalanceOnChain(from, dest)) || 0; } catch (_) {}
  if (!(bal > 0)) return null;
  if (spend > bal * 0.45) spend = Math.max(bal * 0.2, Math.min(spend, bal * 0.35));
  if (!(spend > 0) || spend > bal * 0.95) return null;

  const ru = gwGasUiRu();
  try {
    gwToast(ru
      ? ('Нет газа — Confirm в Trust: маленький своп ' + from + ' → ' + gas + ', потом основной')
      : ('Need gas — Confirm in Trust: small ' + from + '→' + gas + ' top-up, then main swap'), 'info');
  } catch (_) {}

  const quoteFn = (typeof gwMetaAggQuoteBest === 'function') ? gwMetaAggQuoteBest : gwMetaAggQuoteAll;
  if (typeof quoteFn !== 'function') return null;
  const quotes = await quoteFn({
    chainId: dest, fromSym: from, toSym: gas, amtNum: spend, account,
  });
  const list = Array.isArray(quotes) ? quotes : [];
  const winner = list.find((q) => q && (q.transactionRequest || q.raw?.transactionRequest || q.aggregator))
    || list[0];
  if (!winner) {
    const err = new Error(ru
      ? ('Нет маршрута ' + from + ' → ' + gas + ' для догрузки газа')
      : ('No ' + from + '→' + gas + ' route for gas top-up'));
    err.code = 'GAS_TOPUP_NO_ROUTE';
    throw err;
  }
  const isLifi = /lifi/i.test(String(winner.aggregator || winner.tool || ''));
  if (isLifi && typeof gwOnChainSwapExecLifi === 'function') {
    await gwOnChainSwapExecLifi({
      chainId: dest, fromSym: from, toSym: gas, amtNum: spend,
      quote: winner, provider, account,
    });
  } else if (typeof gwOnChainSwapExecMeta === 'function') {
    await gwOnChainSwapExecMeta({
      chainId: dest, fromSym: from, toSym: gas, amtNum: spend,
      quote: winner, provider, account,
    });
  } else {
    return null;
  }
  return { ok: true, spend, gas };
}

/** Bridge same native from another EVM hub (1–2 min) — then user taps Start again. */
async function gwGasExecDonorBridgeTopUp({ destChainId, gasSym, account, provider }) {
  const dest = Number(destChainId);
  const gas = String(gasSym || '').toUpperCase();
  const donor = await gwGasFindDonor(dest, gas);
  if (!donor) return null;
  const px = donor.px || await gwGasNativeUsdPrice(gas);
  let amtNum = GW_GAS_TOPUP_USD / (px > 0 ? px : 1);
  const maxN = GW_GAS_TOPUP_MAX_NATIVE[gas];
  if (maxN && amtNum > maxN) amtNum = maxN;
  if (!(amtNum > 0) || amtNum > Number(donor.bal || 0) * 0.5) return null;

  const quote = await gwGasQuoteNativeBridge({
    fromChainId: donor.chainId,
    toChainId: dest,
    sym: gas,
    amtNum,
    account,
  });
  if (!quote) return null;

  const ru = gwGasUiRu();
  const fromLbl = (typeof gwChainLabel === 'function') ? gwChainLabel(donor.chainId) : String(donor.chainId);
  const toLbl = (typeof gwChainLabel === 'function') ? gwChainLabel(dest) : String(dest);
  try {
    gwToast(ru
      ? ('Догружаем ' + gas + ' мостом ' + fromLbl + ' → ' + toLbl + ' — Confirm в Trust')
      : ('Topping up ' + gas + ' via bridge ' + fromLbl + ' → ' + toLbl + ' — Confirm in Trust'), 'info');
  } catch (_) {}

  if (typeof gwOnChainSwapExecLifi === 'function') {
    await gwOnChainSwapExecLifi({
      chainId: donor.chainId,
      fromSym: gas,
      toSym: gas,
      amtNum,
      quote,
      provider,
      account,
    });
  } else {
    return null;
  }
  const err = new Error(ru
    ? ('Газ отправлен мостом — подожди 1–2 мин и нажми «Начать» снова')
    : ('Gas top-up submitted — wait 1–2 min, then tap Start again'));
  err.code = 'GAS_TOPUP_PENDING';
  throw err;
}

/**
 * If the swap source chain has near-zero native gas:
 *  1) same-chain swap fromSym → gas (extra Confirm), then continue main swap
 *  2) else bridge native from another hub (Confirm), then tap Start again
 */
async function gwEnsureGasTopUpBeforeSwap({ chainId, fromSym, account, provider }) {
  if (window.__gwGasTopUpInFlight) return { ok: true, skipped: 'inflight' };
  const dest = Number(chainId);
  if (!dest || !GW_OC_SWAP[dest]) return { ok: true };
  const gasSym = gwChainGasSymbol(dest);
  const from = String(fromSym || '').toUpperCase();
  if (from === gasSym || from === 'W' + gasSym) return { ok: true, skipped: 'native-pay' };

  const bal = await gwGasNativeBal(dest);
  const px = await gwGasNativeUsdPrice(gasSym);
  const balUsd = bal * (px > 0 ? px : 0);
  if (balUsd >= GW_GAS_MIN_USD) return { ok: true, bal, balUsd };

  const ru = gwGasUiRu();
  const lbl = (typeof gwChainLabel === 'function') ? gwChainLabel(dest) : String(dest);
  window.__gwGasTopUpInFlight = true;
  try {
    /* Dust left (≥~$0.05): can pay 1–2 top-up txs — buy gas from fromSym first. */
    if (balUsd >= 0.05 && account && provider?.request) {
      try {
        const done = await gwGasExecSameChainTokenTopUp({
          chainId: dest, fromSym: from, gasSym, account, provider,
        });
        if (done?.ok) {
          const bal2 = await gwGasNativeBal(dest);
          const balUsd2 = bal2 * (px > 0 ? px : 0);
          if (balUsd2 >= GW_GAS_MIN_USD * 0.85) return { ok: true, toppedUp: 'same-chain', bal: bal2 };
        }
      } catch (e) {
        if (e?.code === 'GAS_TOPUP_PENDING') throw e;
        console.warn('[GROM] same-chain gas top-up', e?.message || e);
      }
    }

    /* Near-zero gas: bridge native from another hub the user already holds. */
    if (account && provider?.request) {
      try {
        await gwGasExecDonorBridgeTopUp({
          destChainId: dest, gasSym, account, provider,
        });
      } catch (e) {
        if (e?.code === 'GAS_TOPUP_PENDING') throw e;
        console.warn('[GROM] donor gas bridge', e?.message || e);
      }
    }

    /* Last try: same-chain even with tiny dust (may still fail in wallet). */
    if (account && provider?.request && from) {
      try {
        const done = await gwGasExecSameChainTokenTopUp({
          chainId: dest, fromSym: from, gasSym, account, provider,
        });
        if (done?.ok) return { ok: true, toppedUp: 'same-chain-retry' };
      } catch (e) {
        if (e?.code === 'GAS_TOPUP_PENDING') throw e;
      }
    }

    const err = new Error(ru
      ? ('Нужен ' + gasSym + ' на ' + lbl + ' для комиссии — догрузи газ или держи ' + gasSym + ' на другой EVM-сети')
      : ('Need ' + gasSym + ' on ' + lbl + ' for fees — add gas, or hold ' + gasSym + ' on another EVM hub'));
    err.code = 'GAS_TOPUP_NO_DONOR';
    throw err;
  } finally {
    try { window.__gwGasTopUpInFlight = false; } catch (_) {}
  }
}
try { window.gwEnsureGasTopUpBeforeSwap = gwEnsureGasTopUpBeforeSwap; } catch (_) {}

/**
 * Tron: if TRX too low for SunSwap fees, buy a little TRX from fromSym first
 * (extra Trust Confirm), then continue. True zero TRX → try EVM→TRX via LiFi.
 */
async function gwEnsureTronGasTopUp({ fromSym, user, tw }) {
  if (window.__gwGasTopUpInFlight) return { ok: true, skipped: 'inflight' };
  const from = String(fromSym || '').toUpperCase();
  if (!from || from === 'TRX') return { ok: true, skipped: 'native-pay' };

  let trxBal = 0;
  try {
    const rows = await gwTronFetchAllBalances(user);
    trxBal = Number((rows || []).find((r) => String(r.sym).toUpperCase() === 'TRX')?.amt) || 0;
  } catch (_) {}
  if (!(trxBal > 0) && tw?.trx?.getBalance) {
    try {
      const sun = await tw.trx.getBalance(user);
      trxBal = Number(sun) / 1e6;
    } catch (_) {}
  }
  if (trxBal >= GW_TRON_GAS_MIN_TRX) return { ok: true, bal: trxBal };

  const needTrx = Math.max(GW_TRON_GAS_TOPUP_TRX - trxBal, 2.5);
  const trxPx = await gwGasTokenUsdPrice('TRX');
  const topUpUsd = Math.min(GW_GAS_TOPUP_MAX_USD, needTrx * (trxPx > 0 ? trxPx : 0.25) * 1.15);
  let spend = await gwGasComputeSpendAmt(from, topUpUsd);
  const ru = gwGasUiRu();

  window.__gwGasTopUpInFlight = true;
  try {
    /* Enough dust TRX to pay energy for a micro USDT→TRX — do that first. */
    if (trxBal >= 0.4) {
      try {
        gwToast(ru
          ? ('Мало TRX на комиссию — Confirm в Trust: ' + from + ' → TRX (~' + needTrx.toFixed(1) + '), потом своп')
          : ('Low TRX for fees — Confirm in Trust: ' + from + '→TRX (~' + needTrx.toFixed(1) + '), then main swap'), 'info');
      } catch (_) {}
      await gwTronSwapExec({ fromSym: from, toSym: 'TRX', amtHuman: spend, skipGasCheck: true });
      return { ok: true, toppedUp: 'tron-same' };
    }

    /* True ~0 TRX: buy TRX via LiFi from EVM (uses EVM gas the user already has). */
    try {
      let provider = (typeof gwActiveSigningProvider === 'function' && gwActiveSigningProvider())
        || window.gromWallet?.wcProvider || window.ethereum;
      let account = '';
      try {
        account = (provider?.accounts && provider.accounts[0])
          || (typeof gwDisplayAddress === 'function' && gwDisplayAddress())
          || (typeof gwReadOnlyAddress === 'function' && gwReadOnlyAddress())
          || (typeof currentAccount !== 'undefined' && currentAccount)
          || localStorage.getItem('grom_wallet_label')
          || '';
      } catch (_) {}
      /* Multi-ns Trust: eip155 lives on the same session as Tron WC. */
      if (!/^0x[a-fA-F0-9]{40}$/i.test(String(account || ''))) {
        try {
          const sess = window.__gwTronWc?.session
            || (typeof wcProvider !== 'undefined' && (wcProvider?.session || wcProvider?.signer?.session))
            || window.__gwWcSession;
          const eip = sess?.namespaces?.eip155?.accounts || [];
          for (const a of eip) {
            const bare = String(a || '').split(':').pop();
            if (/^0x[a-fA-F0-9]{40}$/i.test(bare)) { account = bare; break; }
          }
        } catch (_) {}
      }
      if ((!provider?.request || !/^0x[a-fA-F0-9]{40}$/i.test(String(account || '')))
        && typeof gwEnsureSigningForSwap === 'function') {
        try {
          provider = await gwEnsureSigningForSwap({ silent: true }) || provider;
          account = provider?.accounts?.[0] || account;
        } catch (_) {}
      }
      if (provider?.request && /^0x[a-fA-F0-9]{40}$/i.test(String(account || ''))
        && typeof gwAggQuoteLifi === 'function') {
        const hubs = [42161, 56, 1, 8453, 137, 10, 43114];
        const paySyms = ['USDT', 'USDC', 'ETH', 'BNB', from]
          .filter((s, i, a) => s && a.indexOf(s) === i && !/^SUN|JST|BTT$/i.test(s));
        const foundPay = [];
        const foundGasless = [];
        for (const cid of hubs) {
          const gasSym = (typeof gwChainGasSymbol === 'function') ? gwChainGasSymbol(cid) : 'ETH';
          let gasBal = 0;
          try {
            gasBal = Number(await gwDsTokenBalanceOnChain(gasSym, cid, { account })) || 0;
          } catch (_) { gasBal = 0; }
          const gasPx = await gwGasNativeUsdPrice(gasSym).catch(() => 0);
          const gasUsd = gasBal * (gasPx > 0 ? gasPx : 0);
          for (const pay of paySyms) {
            let bal = 0;
            try {
              bal = Number(await gwDsTokenBalanceOnChain(pay, cid, { account })) || 0;
            } catch (_) { bal = 0; }
            if (!(bal > 0.001)) continue;
            const lbl = (typeof gwChainLabel === 'function') ? gwChainLabel(cid) : String(cid);
            if (gasUsd < 0.12 && pay !== gasSym) {
              foundGasless.push(pay + ' on ' + lbl + ' (no ' + gasSym + ')');
              continue;
            }
            foundPay.push({ cid, pay, bal, gasSym, gasUsd });
          }
        }
        for (const hit of foundPay) {
          let amt = await gwGasComputeSpendAmt(hit.pay, topUpUsd);
          /* Small EVM dust (e.g. $0.47 USDT): spend most of it on TRX gas, not 25%. */
          const payPx = await gwGasTokenUsdPrice(hit.pay).catch(() => 1);
          const balUsd = hit.bal * (payPx > 0 ? payPx : 1);
          if (balUsd > 0 && balUsd < 3) {
            amt = Math.min(hit.bal * 0.92, Math.max(amt, hit.bal * 0.85));
          } else if (amt > hit.bal * 0.4) {
            amt = hit.bal * 0.35;
          }
          if (!(amt > 0) || amt > hit.bal * 0.98) amt = hit.bal * 0.9;
          if (!(amt > 0)) continue;
          let quote = null;
          try {
            quote = await gwAggQuoteLifi({
              chainId: hit.cid, fromSym: hit.pay, toSym: 'TRX', amtNum: amt,
              account, toChainId: GW_TRON_CHAIN_ID,
              slippage: String(typeof gwSwapSlippageFraction === 'function' ? gwSwapSlippageFraction() : 0.005),
            });
          } catch (_) { quote = null; }
          if (!quote || !(typeof quote.toAmount === 'bigint' ? quote.toAmount > 0n : Number(quote.toAmount) > 0)) {
            continue;
          }
          try {
            gwToast(ru
              ? ('Нет TRX — Confirm в Trust: мост ' + hit.pay + ' → TRX, потом снова «Начать»')
              : ('No TRX — Confirm in Trust: bridge ' + hit.pay + '→TRX, then tap Start again'), 'info');
          } catch (_) {}
          await gwOnChainSwapExecLifi({
            chainId: hit.cid, fromSym: hit.pay, toSym: 'TRX', amtNum: amt,
            quote, provider, account,
          });
          const err = new Error(ru
            ? 'TRX в пути мостом — подожди 1–2 мин и нажми «Начать» снова'
            : 'TRX bridging in — wait 1–2 min, then tap Start again');
          err.code = 'GAS_TOPUP_PENDING';
          throw err;
        }
        if (foundGasless.length) {
          const tip = foundGasless[0];
          const err = new Error(ru
            ? ('Есть ' + tip + ' — докинь газ на эту сеть ИЛИ ~' + GW_TRON_GAS_TOPUP_TRX + ' TRX на Tron, затем «Начать»')
            : ('Have ' + tip + ' — add gas on that chain OR ~' + GW_TRON_GAS_TOPUP_TRX + ' TRX on Tron, then Start'));
          err.code = 'GAS_TOPUP_NO_DONOR';
          throw err;
        }
      }
    } catch (e) {
      if (e?.code === 'GAS_TOPUP_PENDING' || e?.code === 'GAS_TOPUP_NO_DONOR') throw e;
      console.warn('[GROM] tron gas via EVM bridge', e?.message || e);
    }

    const err = new Error(ru
      ? ('Нужно ~' + GW_TRON_GAS_TOPUP_TRX + ' TRX на комиссию Tron — докинь TRX на кошелёк и нажми «Начать»')
      : ('Need ~' + GW_TRON_GAS_TOPUP_TRX + ' TRX for Tron fees — add TRX, then tap Start'));
    err.code = 'GAS_TOPUP_NO_DONOR';
    throw err;
  } finally {
    try { window.__gwGasTopUpInFlight = false; } catch (_) {}
  }
}
try { window.gwEnsureTronGasTopUp = gwEnsureTronGasTopUp; } catch (_) {}

/** Solana: if SOL too low, Jupiter-swap a slice of fromSym → SOL first. */
async function gwEnsureSolGasTopUp({ fromSym }) {
  if (window.__gwGasTopUpInFlight) return { ok: true, skipped: 'inflight' };
  const from = String(fromSym || '').toUpperCase();
  if (!from || from === 'SOL') return { ok: true, skipped: 'native-pay' };
  let solBal = 0;
  try {
    solBal = Number(await gwSolAvailableAmount('SOL')) || 0;
  } catch (_) {}
  if (solBal >= GW_SOL_GAS_MIN_SOL) return { ok: true, bal: solBal };

  const need = Math.max(GW_SOL_GAS_TOPUP_SOL - solBal, 0.012);
  const solPx = await gwGasTokenUsdPrice('SOL');
  const topUpUsd = Math.min(GW_GAS_TOPUP_MAX_USD, need * (solPx > 0 ? solPx : 140) * 1.15);
  const spend = await gwGasComputeSpendAmt(from, topUpUsd);
  const ru = gwGasUiRu();

  if (solBal < 0.001) {
    const err = new Error(ru
      ? 'Нужен SOL на комиссию Solana — докинь ~0.02 SOL и нажми «Начать»'
      : 'Need SOL for Solana fees — add ~0.02 SOL, then tap Start');
    err.code = 'GAS_TOPUP_NO_DONOR';
    throw err;
  }

  window.__gwGasTopUpInFlight = true;
  try {
    try {
      gwToast(ru
        ? ('Мало SOL — Confirm в кошельке: ' + from + ' → SOL, потом основной своп')
        : ('Low SOL — Confirm in wallet: ' + from + '→SOL, then main swap'), 'info');
    } catch (_) {}
    await gwSolExec({ fromSym: from, toSym: 'SOL', amtHuman: spend, skipGasCheck: true });
    return { ok: true, toppedUp: 'sol-same' };
  } finally {
    try { window.__gwGasTopUpInFlight = false; } catch (_) {}
  }
}
try { window.gwEnsureSolGasTopUp = gwEnsureSolGasTopUp; } catch (_) {}

async function gwEnsureChain(provider, targetChainId) {
  const target = Number(targetChainId);
  if (!target) throw new Error('Invalid chain');
  currentChainId = target;
  let current = 0;
  try {
    current = parseInt(await provider.request({ method: 'eth_chainId' }), 16);
  } catch (_) {}
  if (current === target) return;
  const hex = '0x' + target.toString(16);
  const lbl = (typeof gwChainLabel === 'function') ? gwChainLabel(target) : String(target);
  const gas = gwChainGasSymbol(target);
  const remote = typeof gwIsRemoteWcSigner === 'function' && gwIsRemoteWcSigner(provider);
  const walletLbl = typeof gwConnectedWalletLabel === 'function' ? gwConnectedWalletLabel() : 'wallet';
  const wakeOpts = { action: 'switch', chainLabel: lbl, gasSymbol: gas };
  try {
    if (typeof provider.setDefaultChain === 'function') {
      provider.setDefaultChain('eip155:' + target);
    }
  } catch (_) {}
  /* WalletConnect tags each request with chainId. A separate
   * wallet_switchEthereumChain re-opens Trust's Connect sheet on every swap.
   * If the paired session already includes this chain, skip that popup —
   * the swap tx is the only confirmation the user should see. */
  if (remote) {
    const session = provider?.session || (typeof wcProvider !== 'undefined' && wcProvider?.session) || null;
    const ids = sessionEip155ChainIds(session);
    if (!ids.length || ids.includes(target)) {
      currentChainId = target;
      try { gwHideRemoteSignCoach(); } catch (_) {}
      return;
    }
  }
  try {
    gwToast(remote
      ? `Open ${walletLbl} on your phone · switch to ${lbl} (gas in ${gas})`
      : `Switch to ${lbl} · network fee in ${gas}`, 'info');
  } catch (_) {}
  const req = (args) => (typeof gwProviderRequestWithWake === 'function'
    ? gwProviderRequestWithWake(provider, args, wakeOpts)
    : provider.request(args));
  try {
    await req({ method: 'wallet_switchEthereumChain', params: [{ chainId: hex }] });
  } catch (e) {
    const msg = String(e?.message || e || '');
    if (e?.code === 4902 || /unrecognized chain|not added|unknown chain/i.test(msg)) {
      const add = GW_EVM_CHAIN_PARAMS[target];
      if (add) {
        try {
          await req({ method: 'wallet_addEthereumChain', params: [add] });
          // add ≠ switch — must switch and re-read eth_chainId (F20)
          try {
            await req({ method: 'wallet_switchEthereumChain', params: [{ chainId: hex }] });
          } catch (_) {}
          try {
            current = parseInt(await provider.request({ method: 'eth_chainId' }), 16);
            if (current === target) {
              try { gwHideRemoteSignCoach(); } catch (_) {}
              return;
            }
          } catch (_) {}
        } catch (_) {}
      }
    }
  }
  try {
    current = parseInt(await provider.request({ method: 'eth_chainId' }), 16);
    if (current === target) {
      try { gwHideRemoteSignCoach(); } catch (_) {}
      return;
    }
  } catch (_) {}
  try { gwHideRemoteSignCoach(); } catch (_) {}
  if (remote) {
    throw new Error(
      `Open ${walletLbl} on your phone → Networks → ${lbl} (fees in ${gas}), then tap Swap again`,
    );
  }
  throw new Error(`Switch your wallet to ${lbl} — fee is paid in ${gas}, not ETH`);
}

/* =========================================================================
 * xStocks / Backed Phase 1 — thin helpers for #page-xstocks (Cursor boot).
 * Register token addrs into GW_OC_SWAP so meta-agg can quote, then buy/sell.
 * ========================================================================= */
window.GWX_NET_TO_ID = {
  Ethereum: 1, Arbitrum: 42161, Optimism: 10, BinanceSmartChain: 56,
  Base: 8453, Polygon: 137, Avalanche: 43114, Mantle: 5000,
};
window.GWX_ID_TO_LABEL = {
  1: 'Ethereum', 42161: 'Arbitrum', 10: 'Optimism', 56: 'BNB Chain',
  8453: 'Base', 137: 'Polygon', 43114: 'Avalanche', 5000: 'Mantle',
};

window.gwXstocksRegisterToken = function ({ chainId, sym, address, decimals, name, logo }) {
  const cid = Number(chainId);
  const s = String(sym || '').toUpperCase();
  const addr = String(address || '');
  if (!cid || !s || !/^0x[a-fA-F0-9]{40}$/i.test(addr)) return false;
  try {
    if (typeof GW_OC_SWAP !== 'undefined' && GW_OC_SWAP[cid]) {
      GW_OC_SWAP[cid].tokens[s] = addr;
      GW_OC_SWAP[cid].decimals[s] = Number(decimals) || 18;
    }
  } catch (_) {}
  try {
    if (typeof GW_DS_ASSETS !== 'undefined' && !GW_DS_ASSETS.find((a) => a.sym === s)) {
      GW_DS_ASSETS.push({
        sym: s,
        name: name || s,
        logo: logo || '',
        custom: true,
        address: addr,
        chainId: cid,
        decimals: Number(decimals) || 18,
      });
    }
  } catch (_) {}
  return true;
};

window.gwXstocksPickChain = function (addrsByChain, preferredChainId) {
  const map = addrsByChain || {};
  const pref = Number(preferredChainId) || 0;
  if (pref && map[pref]) return pref;
  const order = [1, 42161, 10, 56, 8453, 137];
  for (const id of order) if (map[id]) return id;
  const keys = Object.keys(map).map(Number).filter(Boolean);
  return keys[0] || null;
};

async function gwXstocksPrepChain(chainId) {
  const cid = Number(chainId);
  if (!cid) throw new Error('No supported chain for this stock token');
  try { currentChainId = cid; } catch (_) {}
  try {
    window.__gwDsUserPickedFrom = Object.assign({}, window.__gwDsUserPickedFrom || {}, {
      chainId: cid, sym: 'USDT',
    });
  } catch (_) {}
  try {
    document.querySelectorAll('.gw-ds-chain').forEach((el) => {
      el.classList.toggle('on', Number(el.dataset.cid) === cid);
    });
  } catch (_) {}
  const provider = gwActiveSigningProvider() || window.gromWallet?.wcProvider || window.ethereum;
  if (provider?.request) {
    try { await gwEnsureChain(provider, cid); } catch (e) {
      const label = (window.GWX_ID_TO_LABEL && window.GWX_ID_TO_LABEL[cid]) || ('chain ' + cid);
      throw new Error('Switch to ' + label + ' to trade this stock token');
    }
  }
  return cid;
}

async function gwXstocksQuoteSolana({ fromSym, toSym, amtNum, solMint, solDecimals }) {
  const mint = String(solMint || '');
  if (!mint || mint.length < 32) return null;
  const from = String(fromSym || '').toUpperCase();
  const to = String(toSym || '').toUpperCase();
  const amt = Number(amtNum);
  if (!(amt > 0)) return null;
  const buy = from === 'USDT' || from === 'USDC';
  const stable = buy ? from : to;
  if (stable !== 'USDT' && stable !== 'USDC') return null;
  const inMint = buy ? GW_SOL_TOKENS[stable] : mint;
  const outMint = buy ? mint : GW_SOL_TOKENS[stable];
  const inDec = buy ? (GW_SOL_DECIMALS[stable] ?? 6) : (Number(solDecimals) || 8);
  const outDec = buy ? (Number(solDecimals) || 8) : (GW_SOL_DECIMALS[stable] ?? 6);
  const amountBaseUnits = (typeof gwAmtToBaseUnits === 'function'
    ? gwAmtToBaseUnits(amtNum, inDec)
    : gwParseAmountToUnits(amtNum, inDec, { truncate: true })).toString();
  try {
    const jq = await gwSolQuote({ inMint, outMint, amountBaseUnits });
    if (!jq?.outAmount) return null;
    return {
      aggregator: 'Jupiter',
      tool: 'Jupiter',
      venue: 'solana',
      toAmount: BigInt(jq.outAmount),
      outDecimals: outDec,
      gasUsd: 0,
      _gromFeeBps: Number(jq._gromFeeBps) === 0 || jq._gromFeeMode === 'free'
        ? 0
        : (Number(jq._gromFeeBps) > 0 ? Number(jq._gromFeeBps) : (_gwFeeCfg.jupiterFeeBps || 0)),
      _solQuote: jq,
      _solMint: mint,
      _solInMint: inMint,
      _solOutMint: outMint,
    };
  } catch (e) {
    console.warn('[GROM] xstocks Jupiter quote', e?.message || e);
    return null;
  }
}

function gwIsSolAddr(s) {
  return /^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(String(s || '').trim());
}
function gwXstocksSolDest() {
  try {
    const live = typeof gwSolPubkey === 'function' ? gwSolPubkey() : '';
    if (gwIsSolAddr(live)) return String(live).trim();
  } catch (_) {}
  try {
    const mem = window.__gwXstocksSolDest || window.__gwSolAddr
      || localStorage.getItem('grom_xstocks_sol_dest')
      || localStorage.getItem('grom_sol_addr') || '';
    if (gwIsSolAddr(mem)) return String(mem).trim();
  } catch (_) {}
  try {
    const p = window.solana || window.phantom?.solana;
    const pk = p?.publicKey?.toString?.() || '';
    if (gwIsSolAddr(pk)) return pk;
  } catch (_) {}
  return '';
}
function gwXstocksSetSolDest(addr) {
  const a = String(addr || '').trim();
  if (!gwIsSolAddr(a)) throw new Error('Invalid Solana address');
  window.__gwXstocksSolDest = a;
  window.__gwSolAddr = a;
  try {
    localStorage.setItem('grom_xstocks_sol_dest', a);
    localStorage.setItem('grom_sol_addr', a);
  } catch (_) {}
  return a;
}
try {
  window.gwXstocksSolDest = gwXstocksSolDest;
  window.gwXstocksSetSolDest = gwXstocksSetSolDest;
  window.gwIsSolAddr = gwIsSolAddr;
} catch (_) {}

async function gwXstocksQuoteLifiToSol({ chainId, fromSym, amtNum, account, solMint, solAddr, solDecimals }) {
  const cid = Number(chainId);
  const mint = String(solMint || '');
  const from = String(fromSym || '').toUpperCase();
  if (!cid || !mint || !account || !solAddr) return null;
  if (from !== 'USDT' && from !== 'USDC') return null;
  const cfg = GW_OC_SWAP[cid];
  if (!cfg) return null;
  const inAddr = (typeof gwOcTokenAddr === 'function') ? gwOcTokenAddr(cfg, from) : cfg.tokens?.[from];
  if (!inAddr) return null;
  const inDec = cfg.decimals[from] ?? 6;
  const fromAmount = (typeof gwAmtToBaseUnits === 'function'
    ? gwAmtToBaseUnits(amtNum, inDec)
    : gwParseAmountToUnits(amtNum, inDec, { truncate: true })).toString();
  const qs = new URLSearchParams({
    fromChain: String(cid),
    toChain: String(GW_LIFI_SOL_CHAIN),
    fromToken: inAddr,
    toToken: mint,
    fromAmount,
    fromAddress: account,
    toAddress: solAddr,
    slippage: String(typeof gwSwapSlippageFraction === 'function' ? gwSwapSlippageFraction() : 0.005),
    integrator: GW_LIFI_INTEGRATOR,
    order: 'RECOMMENDED',
  });
  if (GW_LIFI_FEE_ADDR && !/^0x0{40}$/i.test(GW_LIFI_FEE_ADDR)) {
    qs.set('fee', String(GW_LIFI_FEE_PCT));
    qs.set('feeAddress', GW_LIFI_FEE_ADDR);
  }
  try {
    const r = await fetch(`${GW_LIFI_ENDPOINT}/quote?${qs}`, { headers: { accept: 'application/json' } });
    if (!r.ok) {
      const t = await r.text().catch(() => '');
      if (gwLifiIsFeeConfigErr(r.status, t)) {
        gwLifiMarkFeeUnavailable('xstocks-lifi');
        return null;
      }
      return null;
    }
    const q = await r.json();
    const toAmt = q?.estimate?.toAmount;
    if (!toAmt || !q.transactionRequest) return null;
    return {
      aggregator: 'LiFi',
      tool: q.tool || q.toolDetails?.name || 'Mayan',
      venue: 'bridge-sol',
      toAmount: BigInt(toAmt),
      outDecimals: Number(solDecimals) || 8,
      gasUsd: Number(q.estimate?.gasCosts?.[0]?.amountUSD || 0),
      approvalAddress: q.estimate?.approvalAddress || q.transactionRequest.to,
      transactionRequest: q.transactionRequest,
      raw: q,
      _bridgeChainId: cid,
      _fromSym: from,
      _gromFeeBps: gwSwapFeeBps(),
    };
  } catch (e) {
    console.warn('[GROM] xstocks LiFi→Sol quote', e?.message || e);
    return null;
  }
}

async function gwXstocksExecSolanaBuy({ quote, amtNum }) {
  let solPk = gwSolPubkey();
  if (!solPk) {
    solPk = await gwSolConnect();
    if (solPk) window.__gwSolAddr = solPk;
  }
  if (!solPk) throw new Error('Connect Phantom to buy xStocks on Solana');
  const q = quote?._solQuote || await (async () => {
    const inMint = quote?._solInMint || GW_SOL_TOKENS.USDC;
    const outMint = quote?._solMint;
    const inDec = inMint === GW_SOL_TOKENS.USDT || inMint === GW_SOL_TOKENS.USDC ? 6 : 8;
    const amountBaseUnits = (typeof gwAmtToBaseUnits === 'function'
      ? gwAmtToBaseUnits(amtNum, inDec)
      : gwParseAmountToUnits(amtNum, inDec, { truncate: true })).toString();
    return gwSolQuote({ inMint, outMint, amountBaseUnits });
  })();
  if (!q) throw new Error('No Jupiter route for this xStock on Solana');
  const p = window.solana || window.phantom?.solana;
  if (!p) throw new Error('Phantom not connected');
  gwToast('Jupiter · confirm in Phantom', 'info');
  const txB64 = await gwSolSwap({ quoteResponse: q, userPubkey: solPk });
  const signature = await gwSolSignAndSendBase64(p, txB64);
  gwToast('Submitted on Solana…', 'info');
  return signature;
}

async function gwXstocksExecLifiBridge({ quote, chainId, fromSym, amtNum }) {
  const provider = gwActiveSigningProvider() || window.gromWallet?.wcProvider || window.ethereum;
  const account = gwReadOnlyAddress();
  if (!provider?.request || !account) throw new Error('Connect EVM wallet first');
  const cid = Number(quote?._bridgeChainId || chainId);
  await gwXstocksPrepChain(cid);
  return await gwOnChainSwapExecLifi({
    chainId: cid,
    fromSym: quote?._fromSym || fromSym || 'USDT',
    toSym: 'SOL', // label only for toast; LiFi tx already encodes Solana dest
    amtNum,
    quote: quote.raw || quote,
    provider,
    account,
  });
}

/** Max USD price impact allowed for xStocks (P0 money guard). */
const GW_XSTOCKS_MAX_IMPACT = 0.05;

function gwXstocksQuoteScore(q, opts) {
  if (window.GromSwapCore?.xstockQuoteValueScore) {
    return window.GromSwapCore.xstockQuoteValueScore(q, opts || {});
  }
  if (!q || typeof q.toAmount !== 'bigint' || q.toAmount <= 0n) return 0;
  const outUsd = Number(q.amountOutUsd ?? q.outUsd);
  if (outUsd > 0 && Number.isFinite(outUsd)) return outUsd;
  const dec = Number(q.outDecimals) > 0 ? Number(q.outDecimals) : 18;
  return Number(q.toAmount) / (10 ** dec);
}

/** Attach amountInUsd / amountOutUsd / priceImpact; prefer provider USD fields (Kyber). */
function gwXstocksEnrichUsd(q, { amtNum, buy, refPrice } = {}) {
  if (!q) return null;
  let inUsd = Number(q.amountInUsd ?? q._inUsd);
  let outUsd = Number(q.amountOutUsd ?? q._outUsd ?? q.outUsd);
  const amt = Number(amtNum);
  const px = Number(refPrice);
  const dec = Number(q.outDecimals) > 0 ? Number(q.outDecimals) : 18;
  let tokens = 0;
  if (typeof q.toAmount === 'bigint' && q.toAmount > 0n) {
    tokens = Number(q.toAmount) / (10 ** dec);
  } else if (q.toAmount != null && Number(q.toAmount) > 0) {
    tokens = Number(q.toAmount) / (10 ** dec);
  }
  if (!(inUsd > 0) && amt > 0) {
    inUsd = buy ? amt : (px > 0 ? amt * px : 0);
  }
  /* Equity fair value of received tokens (UI stock price) — NOT Kyber pool USD.
   * Pool USD can look "fair" while user loses 50–90% vs the listed share price. */
  let equityOutUsd = 0;
  if (buy && px > 0 && tokens > 0) equityOutUsd = tokens * px;
  if (!(outUsd > 0)) {
    if (buy && equityOutUsd > 0) outUsd = equityOutUsd;
    else if (!buy && tokens > 0) outUsd = tokens; // stable out ≈ USD
  }
  if (inUsd > 0) q.amountInUsd = inUsd;
  if (outUsd > 0) q.amountOutUsd = outUsd;
  if (equityOutUsd > 0) q.amountOutUsdEquity = equityOutUsd;
  if (buy && tokens > 0 && inUsd > 0) q.execPrice = inUsd / tokens;
  const impactOut = (buy && equityOutUsd > 0) ? equityOutUsd : outUsd;
  const imp = window.GromSwapCore?.quoteUsdImpact
    ? window.GromSwapCore.quoteUsdImpact({
      amountInUsd: inUsd,
      amountOutUsd: impactOut,
      maxImpact: GW_XSTOCKS_MAX_IMPACT,
    })
    : { impact: NaN, blocked: false, inUsd, outUsd: impactOut };
  q.priceImpact = imp.impact;
  q.impactBlocked = !!imp.blocked;
  q.outTokens = tokens;
  return q;
}

function gwXstocksPickBestQuote(list, { refPrice, buy } = {}) {
  let bestOk = null;
  let bestOkSc = -1;
  let bestAny = null;
  let bestAnySc = -1;
  for (const q of list) {
    if (!q || typeof q.toAmount !== 'bigint' || q.toAmount <= 0n) continue;
    const sc = gwXstocksQuoteScore(q, { refPrice, buy });
    if (sc > bestAnySc) { bestAny = q; bestAnySc = sc; }
    if (!q.impactBlocked && sc > bestOkSc) { bestOk = q; bestOkSc = sc; }
  }
  return bestOk || bestAny;
}

async function gwXstocksQuoteEvmOnChain({ chainId, fromSym, toSym, amtNum, account, address, decimals, name, logo, tokenSym }) {
  const cid = Number(chainId);
  if (!cid) return null;
  const from = String(fromSym || '').toUpperCase();
  const to = String(toSym || '').toUpperCase();
  if (address) window.gwXstocksRegisterToken({ chainId: cid, sym: tokenSym, address, decimals, name, logo });
  try {
    const quoteFn = (typeof gwMetaAggQuoteBest === 'function') ? gwMetaAggQuoteBest : gwMetaAggQuoteAll;
    const quotes = await quoteFn({ chainId: cid, fromSym: from, toSym: to, amtNum, account });
    if (quotes && quotes[0]) {
      return Object.assign({
        venue: quotes[0]._crossChain ? 'bridge' : 'evm',
        outDecimals: Number(quotes[0].outDecimals) || Number(decimals) || 18,
        _execChainId: cid,
        _fromSym: from,
        _toSym: to,
      }, quotes[0]);
    }
  } catch (_) {}
  return null;
}

async function gwXstocksQuoteEvmBest({ fromSym, toSym, amtNum, chainId, address, decimals, name, logo, addrsByChain, tokenSym, account, refPrice }) {
  const from = String(fromSym || '').toUpperCase();
  const to = String(toSym || '').toUpperCase();
  const buy = from === 'USDT' || from === 'USDC';
  const sell = to === 'USDT' || to === 'USDC';
  const stables = buy
    ? (from === 'USDC' ? ['USDC', 'USDT'] : ['USDT', 'USDC'])
    : (to === 'USDC' ? ['USDC', 'USDT'] : ['USDT', 'USDC']);
  const map = addrsByChain || {};
  const pref = Number(chainId) || 0;
  const order = [pref, 1, 42161, 10, 8453, 56, 137].filter(Boolean);
  const seen = new Set();
  const chainJobs = [];
  for (const id of order) {
    if (seen.has(id)) continue;
    seen.add(id);
    const addr = (id === pref && address) ? address : map[id];
    if (!addr) continue;
    chainJobs.push({ cid: id, addr });
    if (chainJobs.length >= 4) break;
  }
  Object.keys(map).map(Number).filter(Boolean).forEach((id) => {
    if (seen.has(id) || chainJobs.length >= 4) return;
    seen.add(id);
    chainJobs.push({ cid: id, addr: map[id] });
  });
  if (!chainJobs.length) return null;

  const pairAttempts = (job) => stables.map((st) => {
    const f = buy ? st : from;
    const t = buy ? to : (sell ? st : to);
    return gwXstocksQuoteEvmOnChain({
      chainId: job.cid, fromSym: f, toSym: t, amtNum, account,
      address: job.addr, decimals, name, logo, tokenSym,
    });
  });
  const pickBest = (list) => {
    const enriched = list
      .map((q) => gwXstocksEnrichUsd(q, { amtNum, buy, refPrice }))
      .filter(Boolean);
    return gwXstocksPickBestQuote(enriched, { buy, refPrice });
  };

  // Scan preferred + other catalog chains in parallel — do not early-return a thin pool.
  const all = await Promise.all(
    chainJobs.flatMap(pairAttempts).map((p) => p.catch(() => null)),
  );
  return pickBest(all);
}

window.gwXstocksBuy = async function ({ tokenSym, usdtAmount, chainId, address, decimals, name, logo, solMint, solDecimals, addrsByChain, refPrice }) {
  const sym = String(tokenSym || '').toUpperCase();
  const amt = Number(usdtAmount);
  if (!sym || !(amt > 0)) throw new Error('Invalid buy amount');
  const addr = gwReadOnlyAddress();
  const solPk = gwSolPubkey();
  if (!addr && !solPk) {
    try { if (typeof openConnectModal === 'function') openConnectModal(); } catch (_) {}
    throw new Error('Connect wallet first');
  }
  if (address && chainId) window.gwXstocksRegisterToken({ chainId, sym, address, decimals, name, logo });

  // Live quote: Jupiter Solana ∥ EVM mega-agg ∥ LiFi bridge — pick best USD out
  const q = await window.gwXstocksQuote({
    fromSym: 'USDT', toSym: sym, amtNum: amt, chainId, address, decimals, name, logo,
    solMint, solDecimals, addrsByChain, refPrice,
  });
  if (!q) {
    if (solMint) {
      try {
        let solPk = gwSolPubkey() || await gwSolConnect();
        if (solPk) window.__gwSolAddr = solPk;
        const sq = await window.gwXstocksQuote({
          fromSym: 'USDT', toSym: sym, amtNum: amt, solMint, solDecimals, refPrice,
          probeLite: true,
        });
        if (sq && !sq.impactBlocked) {
          return await gwXstocksExecSolanaBuy({ quote: sq, amtNum: amt });
        }
      } catch (e) {
        throw new Error(
          e?.message || 'Connect Phantom with USDC/USDT — xStocks liquidity is on Solana.'
        );
      }
    }
    throw new Error(
      'No route for ' + sym + '. Strongest liquidity is Solana (Phantom + USDC/USDT). '
      + 'EVM routes use 1inch/Paraswap/Kyber/Odos/LiFi when pools exist — try AAPL/NVDA or connect Phantom.'
    );
  }
  if (q.impactBlocked) {
    if (solMint && q.venue !== 'solana') {
      try {
        let solPk = gwSolPubkey() || await gwSolConnect();
        if (solPk) window.__gwSolAddr = solPk;
        const sq = await window.gwXstocksQuote({
          fromSym: 'USDT', toSym: sym, amtNum: amt, solMint, solDecimals, refPrice,
          probeLite: true,
        });
        if (sq && !sq.impactBlocked) {
          return await gwXstocksExecSolanaBuy({ quote: sq, amtNum: amt });
        }
      } catch (_) {}
    }
    const equity = Number(q.amountOutUsdEquity || q.amountOutUsd);
    const imp = Number(q.priceImpact);
    const loss = Number.isFinite(imp) ? (imp * 100).toFixed(1) + '%' : '>5%';
    const outLbl = equity > 0 ? ('≈$' + equity.toFixed(2) + ' of stock value') : 'too little';
    throw new Error(
      'Insufficient liquidity: you would get ' + outLbl + ' for $' + amt.toFixed(2)
      + ' (lose ' + loss + '). Trade blocked (impact >' + Math.round(GW_XSTOCKS_MAX_IMPACT * 100) + '%).'
    );
  }
  if (q.venue === 'solana') return await gwXstocksExecSolanaBuy({ quote: q, amtNum: amt });
  if (q.venue === 'bridge-sol') {
    return await gwXstocksExecLifiBridge({
      quote: q, chainId: q._bridgeChainId || chainId, fromSym: q._fromSym || 'USDT', amtNum: amt,
    });
  }
  const execCid = Number(q._execChainId || chainId);
  if (!execCid) throw new Error('No EVM market for this ticker');
  await gwXstocksPrepChain(execCid);
  const fromStable = String(q._fromSym || 'USDT').toUpperCase();
  return await gwOnChainSwapExec(fromStable, sym, amt);
};

window.gwXstocksSell = async function ({ tokenSym, tokenAmount, chainId, address, decimals, name, logo, solMint, solDecimals, addrsByChain, refPrice }) {
  const sym = String(tokenSym || '').toUpperCase();
  const amt = Number(tokenAmount);
  if (!sym || !(amt > 0)) throw new Error('Invalid sell amount');
  const addr = gwReadOnlyAddress();
  if (!addr && !gwSolPubkey()) {
    try { if (typeof openConnectModal === 'function') openConnectModal(); } catch (_) {}
    throw new Error('Connect wallet first');
  }
  if (address && chainId) window.gwXstocksRegisterToken({ chainId, sym, address, decimals, name, logo });
  const q = await window.gwXstocksQuote({
    fromSym: sym, toSym: 'USDT', amtNum: amt, chainId, address, decimals, name, logo,
    solMint, solDecimals, addrsByChain, refPrice,
  });
  if (!q) {
    throw new Error(
      'No sell route for ' + sym + '. Use Phantom on Solana, or an EVM chain where this xStock has DEX liquidity.'
    );
  }
  if (q.impactBlocked) {
    const out = Number(q.amountOutUsd);
    const outLbl = out > 0 ? ('≈$' + out.toFixed(2)) : 'too little';
    throw new Error(
      'Insufficient liquidity on sell: you would get ' + outLbl
      + '. Trade blocked (impact >' + Math.round(GW_XSTOCKS_MAX_IMPACT * 100) + '%).'
    );
  }
  if (q.venue === 'solana') {
    // Sell xStock → USDT/USDC on Solana via Jupiter
    let solPk = gwSolPubkey() || await gwSolConnect();
    if (solPk) window.__gwSolAddr = solPk;
    if (!solPk) throw new Error('Connect Phantom to sell xStocks on Solana');
    const jq = q._solQuote;
    const p = window.solana || window.phantom?.solana;
    gwToast('Jupiter sell · confirm in Phantom', 'info');
    const txB64 = await gwSolSwap({ quoteResponse: jq, userPubkey: solPk });
    return await gwSolSignAndSendBase64(p, txB64);
  }
  const execCid = Number(q._execChainId || chainId);
  if (!execCid) throw new Error('No EVM market for this ticker');
  await gwXstocksPrepChain(execCid);
  const toStable = String(q._toSym || 'USDT').toUpperCase();
  return await gwOnChainSwapExec(sym, toStable, amt);
};

window.gwXstocksQuote = async function ({ fromSym, toSym, amtNum, chainId, address, decimals, name, logo, solMint, solDecimals, addrsByChain, refPrice, probeLite }) {
  const from = String(fromSym || '').toUpperCase();
  const to = String(toSym || '').toUpperCase();
  const amt = Number(amtNum);
  if (!from || !to || !(amt > 0)) return null;
  const tokenSym = from === 'USDT' || from === 'USDC' ? to : from;
  if (address && chainId) window.gwXstocksRegisterToken({ chainId, sym: tokenSym, address, decimals, name, logo });
  const account = gwReadOnlyAddress() || '0x0000000000000000000000000000000000000001';
  const buy = from === 'USDT' || from === 'USDC';
  const px = Number(refPrice) || 0;
  const enrich = (q) => gwXstocksEnrichUsd(q, { amtNum: amt, buy, refPrice: px });

  /* Probe path: Solana only — skip the 280ms retry sleep when first attempt works. */
  if (probeLite && solMint && buy) {
    for (const st of (from === 'USDC' ? ['USDC', 'USDT'] : ['USDT', 'USDC'])) {
      try {
        const sq = enrich(await gwXstocksQuoteSolana({
          fromSym: st, toSym: to, amtNum: amt, solMint, solDecimals,
        }));
        if (sq && !sq.impactBlocked) return sq;
      } catch (_) {}
    }
    /* One short retry only if nothing came back (Jupiter 429). */
    await new Promise((r) => setTimeout(r, 120));
    for (const st of (from === 'USDC' ? ['USDC', 'USDT'] : ['USDT', 'USDC'])) {
      try {
        const sq = enrich(await gwXstocksQuoteSolana({
          fromSym: st, toSym: to, amtNum: amt, solMint, solDecimals,
        }));
        if (sq) return sq;
      } catch (_) {}
    }
    return null;
  }

  // Parallel: Solana Jupiter (best xStocks liquidity) + EVM mega-agg across catalog chains
  const jobs = [
    gwXstocksQuoteEvmBest({
      fromSym: from, toSym: to, amtNum: amt, chainId, address, decimals, name, logo,
      addrsByChain, tokenSym, account, refPrice: px,
    }).then(enrich).catch(() => null),
  ];
  if (buy) {
    for (const st of (from === 'USDC' ? ['USDC', 'USDT'] : ['USDT', 'USDC'])) {
      jobs.push(
        gwXstocksQuoteSolana({ fromSym: st, toSym: to, amtNum: amt, solMint, solDecimals })
          .then(enrich).catch(() => null),
      );
    }
  } else {
    for (const st of (to === 'USDC' ? ['USDC', 'USDT'] : ['USDT', 'USDC'])) {
      jobs.push(
        gwXstocksQuoteSolana({ fromSym: from, toSym: st, amtNum: amt, solMint, solDecimals })
          .then(enrich).catch(() => null),
      );
    }
  }
  const parallel = await Promise.all(jobs);
  let best = gwXstocksPickBestQuote(parallel, { refPrice: px, buy });
  if (best && !best.impactBlocked) return best;

  /* Jupiter often 429s during list probes — one quiet retry before accepting thin EVM. */
  if (buy && solMint) {
    await new Promise((r) => setTimeout(r, 350));
    for (const st of (from === 'USDC' ? ['USDC', 'USDT'] : ['USDT', 'USDC'])) {
      try {
        const sq = enrich(await gwXstocksQuoteSolana({
          fromSym: st, toSym: to, amtNum: amt, solMint, solDecimals,
        }));
        if (sq && !sq.impactBlocked) return sq;
        if (sq && (!best || gwXstocksQuoteScore(sq, { refPrice: px, buy }) > gwXstocksQuoteScore(best, { refPrice: px, buy }))) {
          best = sq;
        }
      } catch (_) {}
    }
    if (best && !best.impactBlocked) return best;
  }

  // LiFi Mayan bridge: EVM USDT/USDC → Solana mint (Sol dest = Phantom OR pasted address)
  const solDest = (typeof gwXstocksSolDest === 'function' ? gwXstocksSolDest() : '') || '';
  if (solDest && buy && solMint) {
    const map = addrsByChain || {};
    const srcChains = [];
    const pref = Number(chainId) || 0;
    if (pref) srcChains.push(pref);
    /* Prefer chains where the wallet actually holds stables (Arb USDC etc.). */
    try {
      const rows = (typeof gwTkLoadHoldings === 'function') ? await gwTkLoadHoldings(false) : [];
      for (const r of rows || []) {
        const sym = String(r.sym || '').toUpperCase();
        if ((sym === 'USDT' || sym === 'USDC') && Number(r.amt) > 0.5 && Number(r.chainId)) {
          const cid = Number(r.chainId);
          if (!srcChains.includes(cid)) srcChains.push(cid);
        }
      }
    } catch (_) {}
    [1, 42161, 10, 8453, 56, 137].forEach((id) => {
      if (!srcChains.includes(id) && (map[id] || id === pref)) srcChains.push(id);
    });
    const bridgeAttempts = [];
    for (const cid of srcChains.slice(0, 4)) {
      for (const st of ['USDC', 'USDT']) {
        bridgeAttempts.push(gwXstocksQuoteLifiToSol({
          chainId: cid, fromSym: st, amtNum: amt, account: gwReadOnlyAddress() || account,
          solMint, solAddr: solDest, solDecimals,
        }).then(enrich));
      }
    }
    const bridged = await Promise.all(bridgeAttempts.map((p) => p.catch(() => null)));
    const bridgeBest = gwXstocksPickBestQuote(bridged.concat(parallel), { refPrice: px, buy });
    if (bridgeBest && !bridgeBest.impactBlocked) return bridgeBest;
    if (bridgeBest) best = bridgeBest;
  }
  /* Never surface thin EVM as a buyable route when Solana mint exists —
   * UI should ask for Sol dest / Phantom instead of "impact blocked" on a bad pool. */
  if (best && best.impactBlocked && solMint
      && best.venue !== 'solana' && best.venue !== 'bridge-sol') {
    return null;
  }
  return best || null;
};

window.gwXstocksBalanceOf = async function ({ chainId, tokenAddress, account, decimals }) {
  const cid = Number(chainId);
  const tok = String(tokenAddress || '');
  const acc = String(account || gwReadOnlyAddress() || '');
  if (!cid || !/^0x[a-fA-F0-9]{40}$/i.test(tok) || !/^0x[a-fA-F0-9]{40}$/i.test(acc)) return 0;
  try {
    const raw = await gwRpcTry(cid, 'eth_call', [{ to: tok, data: padAddressData(acc) }, 'latest']);
    const dec = Number(decimals) || 18;
    return Number(BigInt(raw || '0x0')) / (10 ** dec);
  } catch (_) { return 0; }
};

window.gwXstocksUsdtBalance = async function (chainId) {
  const cid = Number(chainId) || (typeof gwGetActiveUiChainId === 'function' ? gwGetActiveUiChainId() : 1) || 1;
  const addr = (typeof gwReadOnlyAddress === 'function') ? gwReadOnlyAddress() : null;
  if (!addr) return 0;
  try {
    const rows = (typeof gwTkLoadHoldings === 'function') ? await gwTkLoadHoldings(false) : [];
    const hit = (rows || []).find((r) => r.sym === 'USDT' && Number(r.chainId) === cid)
      || (rows || []).find((r) => r.sym === 'USDT');
    if (hit) return Number(hit.amt) || 0;
  } catch (_) {}
  try {
    const bal = await window.gromFetchOnchainBalances(addr, cid);
    return Number(bal?.tokens?.USDT) || 0;
  } catch (_) { return 0; }
};

/** USDT + USDC across chains for xStocks pay / LiFi bridge UI. */
window.gwXstocksStableBalances = async function () {
  const empty = { usdt: 0, usdc: 0, best: 0, lines: [], rows: [] };
  const addr = (typeof gwReadOnlyAddress === 'function') ? gwReadOnlyAddress()
    : ((typeof gwDisplayAddress === 'function') ? gwDisplayAddress() : null);
  if (!addr) return empty;
  const CHAIN = {
    1: 'Ethereum', 10: 'Optimism', 56: 'BSC', 137: 'Polygon',
    8453: 'Base', 42161: 'Arbitrum', 43114: 'Avalanche',
  };
  let rows = [];
  try {
    rows = (typeof gwTkLoadHoldings === 'function') ? await gwTkLoadHoldings(false) : [];
  } catch (_) {}
  const stables = [];
  for (const r of rows || []) {
    const sym = String(r.sym || '').toUpperCase();
    if (sym !== 'USDT' && sym !== 'USDC') continue;
    const amt = Number(r.amt) || 0;
    if (!(amt > 0.0001)) continue;
    const cid = Number(r.chainId) || 0;
    const chain = r.chain || CHAIN[cid] || String(cid || '');
    stables.push({
      sym, amt, usd: Number(r.usd) > 0 ? Number(r.usd) : amt,
      chainId: cid, chain,
    });
  }
  /* Fallback: probe common chains if holdings cache empty. */
  if (!stables.length) {
    for (const cid of [42161, 56, 1, 137, 8453, 10]) {
      try {
        const bal = await window.gromFetchOnchainBalances?.(addr, cid);
        if (!bal?.tokens) continue;
        for (const sym of ['USDC', 'USDT']) {
          const amt = Number(bal.tokens[sym]) || 0;
          if (amt > 0.0001) {
            stables.push({ sym, amt, usd: amt, chainId: cid, chain: CHAIN[cid] || String(cid) });
          }
        }
      } catch (_) {}
    }
  }
  stables.sort((a, b) => b.usd - a.usd);
  let usdt = 0;
  let usdc = 0;
  for (const s of stables) {
    if (s.sym === 'USDT') usdt += s.amt;
    if (s.sym === 'USDC') usdc += s.amt;
  }
  const best = Math.max(usdt, usdc, ...stables.map((s) => s.amt), 0);
  const lines = stables.slice(0, 4).map((s) => (
    s.sym + ' ' + (s.amt >= 1 ? s.amt.toFixed(2) : s.amt.toPrecision(3)) + ' · ' + s.chain
  ));
  return { usdt, usdc, best, lines, rows: stables };
};

