function gwAiLang() { let l = 'en'; try { const s = localStorage.getItem('grom_lang'); if (s && GW_AI_TR[s]) l = s; else { const n = (navigator.language || '').toLowerCase(); for (const c of Object.keys(GW_AI_TR)) if (n.indexOf(c) === 0) { l = c; break; } } } catch (_) {} return GW_AI_TR[l] || GW_AI_TR.en; }
function gwAiLangCode() {
  try {
    const s = localStorage.getItem('grom_lang');
    if (s && GW_AI_TR[s]) return s;
  } catch (_) {}
  return 'en';
}
function gwAiStorageScope() {
  try {
    if (typeof gwJwtValid === 'function' && gwJwtValid()) {
      const jwt = localStorage.getItem('grom_jwt') || '';
      const mid = jwt.split('.')[1];
      if (mid) {
        const payload = JSON.parse(atob(mid.replace(/-/g, '+').replace(/_/g, '/')));
        if (payload?.sub) return 'u:' + String(payload.sub).slice(0, 36);
      }
    }
  } catch (_) {}
  try {
    const a = (typeof gwDisplayAddress === 'function' && gwDisplayAddress()) || window.GROM_CONN?.label || '';
    if (a && String(a).length >= 8) return 'w:' + String(a).toLowerCase();
  } catch (_) {}
  return 'guest';
}
function gwAiStorageKey(base) {
  return base + ':' + gwAiStorageScope();
}

/** Personal memory — scoped per wallet/user; server auth required to persist. */
function gwAiMemoryLoad() {
  try {
    const scoped = JSON.parse(localStorage.getItem(gwAiStorageKey('gw_ai_memory_v2')) || 'null');
    if (scoped && typeof scoped === 'object') return scoped;
    // migrate legacy only into current scope once
    const legacy = JSON.parse(localStorage.getItem('gw_ai_memory_v1') || 'null');
    if (legacy && typeof legacy === 'object' && gwAiStorageScope() !== 'guest') {
      localStorage.setItem(gwAiStorageKey('gw_ai_memory_v2'), JSON.stringify(legacy));
      return legacy;
    }
    return {};
  } catch (_) { return {}; }
}
function gwAiMemorySave(m) {
  try { localStorage.setItem(gwAiStorageKey('gw_ai_memory_v2'), JSON.stringify(m)); } catch (_) {}
}
function gwAiMemoryMergeRemote(remote) {
  if (!remote || typeof remote !== 'object') return;
  try {
    if (remote.memoryEnabled === false) {
      gwAiMemorySave({
        events: [],
        topTypes: [],
        notes: [],
        preferences: remote.preferences || {},
        memoryEnabled: false,
        updatedAt: Date.now(),
      });
      return;
    }
    const m = gwAiMemoryLoad();
    if (m.memoryEnabled === false) return;
    const localEvents = Array.isArray(m.events) ? m.events : [];
    const remoteEvents = Array.isArray(remote.recent) ? remote.recent : [];
    const key = (e) => `${e.t || e.at || 0}|${e.kind || ''}|${e.type || ''}|${e.q || ''}`;
    const seen = new Set(localEvents.map(key));
    const merged = localEvents.slice();
    for (const e of remoteEvents) {
      const row = {
        at: Number(e.t || e.at) || Date.now(),
        kind: e.kind,
        type: e.type,
        ok: e.ok,
        q: e.q,
      };
      if (!seen.has(key(row))) {
        seen.add(key(row));
        merged.push(row);
      }
    }
    merged.sort((a, b) => (a.at || 0) - (b.at || 0));
    m.events = merged.slice(-100);
    const top = [...(Array.isArray(m.topTypes) ? m.topTypes : []), ...(Array.isArray(remote.topTypes) ? remote.topTypes : [])];
    const counts = {};
    for (const e of m.events) {
      if (!e.type) continue;
      counts[e.type] = (counts[e.type] || 0) + (e.ok ? 2 : 1);
    }
    for (const t of top) {
      if (t) counts[t] = (counts[t] || 0) + 2;
    }
    m.topTypes = Object.keys(counts).sort((a, b) => counts[b] - counts[a]).slice(0, 6);
    m.notes = [...new Set([
      ...(Array.isArray(m.notes) ? m.notes : []),
      ...(Array.isArray(remote.notes) ? remote.notes : []),
    ].filter(Boolean))].slice(0, 8);
    if (remote.preferences) m.preferences = remote.preferences;
    m.memoryEnabled = true;
    m.updatedAt = Date.now();
    gwAiMemorySave(m);
  } catch (_) {}
}
async function gwAiMemoryPull() {
  try {
    if (typeof gwJwtValid === 'function' && !gwJwtValid()) return;
    const jwt = localStorage.getItem('grom_jwt') || '';
    if (!jwt) return;
    const r = await fetch('/api/ai/memory', { headers: { Authorization: `Bearer ${jwt}` } });
    if (!r.ok) return;
    const j = await r.json();
    gwAiMemoryMergeRemote(j);
    try { gwAiRefreshSuggest(); } catch (_) {}
  } catch (_) {}
}
function gwAiMemoryPushEvent(ev) {
  try {
    if (typeof gwJwtValid === 'function' && !gwJwtValid()) return;
    const jwt = localStorage.getItem('grom_jwt') || '';
    if (!jwt) return;
    fetch('/api/ai/memory/event', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${jwt}` },
      body: JSON.stringify({
        kind: String(ev?.kind || 'note').slice(0, 24),
        type: ev?.type ? String(ev.type).slice(0, 40) : undefined,
        ok: !!ev?.ok,
        q: ev?.q ? String(ev.q).slice(0, 160) : undefined,
        t: Date.now(),
      }),
    }).then(async (r) => {
      if (!r.ok) return;
      try {
        const j = await r.json();
        gwAiMemoryMergeRemote(j);
      } catch (_) {}
    }).catch(() => {});
  } catch (_) {}
}
function gwAiLearn(ev) {
  try {
    const m = gwAiMemoryLoad();
    if (m.memoryEnabled === false) return;
    const events = Array.isArray(m.events) ? m.events : [];
    events.push({
      at: Date.now(),
      kind: String(ev?.kind || 'note').slice(0, 24),
      type: ev?.type ? String(ev.type).slice(0, 40) : undefined,
      ok: !!ev?.ok,
      q: ev?.q ? String(ev.q).slice(0, 160) : undefined,
    });
    m.events = events.slice(-100);
    const counts = {};
    for (const e of m.events) {
      if (!e.type) continue;
      counts[e.type] = (counts[e.type] || 0) + (e.ok ? 2 : 1);
    }
    m.topTypes = Object.keys(counts).sort((a, b) => counts[b] - counts[a]).slice(0, 6);
    const notes = [];
    if (m.topTypes.includes('predict.bet')) notes.push('User often uses prediction markets');
    if (m.topTypes.includes('futures.open')) notes.push('User often opens futures');
    if (m.topTypes.includes('swap.buy')) notes.push('User often swaps tokens');
    if (m.topTypes.includes('xstocks.buy')) notes.push('User looks at tokenized stocks');
    if (m.topTypes.includes('advise')) notes.push('User asks for recommendations');
    if (m.topTypes.includes('trade.plan')) notes.push('User uses trade-plan / bot helper mode');
    m.notes = notes.slice(0, 6);
    m.updatedAt = Date.now();
    gwAiMemorySave(m);
    // Persist meaningful outcomes server-side (skip noisy ask spam).
    const kind = String(ev?.kind || '');
    if (kind === 'confirm' || kind === 'cancel' || kind === 'exec' || kind === 'advise') {
      gwAiMemoryPushEvent(ev);
    }
  } catch (_) {}
}
function gwAiMemoryForApi() {
  const m = gwAiMemoryLoad();
  if (m.memoryEnabled === false) {
    return { topTypes: [], notes: [], recent: [], preferences: m.preferences || {}, memoryEnabled: false };
  }
  return {
    topTypes: Array.isArray(m.topTypes) ? m.topTypes.slice(0, 6) : [],
    notes: Array.isArray(m.notes) ? m.notes.slice(0, 6) : [],
    recent: (Array.isArray(m.events) ? m.events : []).slice(-8).map((e) => ({
      kind: e.kind, type: e.type, ok: e.ok, q: e.q, t: e.at,
    })),
    preferences: m.preferences || {},
    memoryEnabled: true,
  };
}
async function gwAiMemoryForget() {
  try {
    gwAiMemorySave({ events: [], topTypes: [], notes: [], preferences: {}, memoryEnabled: false, updatedAt: Date.now() });
    const jwt = localStorage.getItem('grom_jwt') || '';
    if (jwt && typeof gwJwtValid === 'function' && gwJwtValid()) {
      await fetch('/api/ai/memory/forget', {
        method: 'POST',
        headers: { Authorization: `Bearer ${jwt}`, 'Content-Type': 'application/json' },
        body: '{}',
      });
    }
  } catch (_) {}
}
