function gwDeviceTrustUrl(signUrl) {
  return 'https://link.trustwallet.com/open_url?coin_id=60&url=' + encodeURIComponent(signUrl || location.href);
}
function gwInWalletBrowser() {
  try {
    const ua = navigator.userAgent || '';
    return !!(window.ethereum?.request || window.trustwallet?.ethereum?.request
      || window.trustwallet?.request || /TrustWallet|Trust/i.test(ua));
  } catch (_) { return false; }
}
async function gwWaitInjectedProvider(maxMs) {
  const deadline = Date.now() + (maxMs || 4000);
  while (Date.now() < deadline) {
    const p = window.ethereum || window.trustwallet?.ethereum || window.trustwallet || null;
    if (p?.request) return p;
    await new Promise((r) => setTimeout(r, 180));
  }
  return null;
}

/** Trust DApp Browser: ?grom_device=CODE → sign SIWE with injected ethereum, complete on server. */
async function gwRunDeviceSiweIfNeeded() {
  let code = '';
  try {
    const u = new URL(location.href);
    code = String(u.searchParams.get('grom_device') || '').toLowerCase();
  } catch (_) {}
  if (!code || !/^[a-f0-9]{8}$/.test(code)) return false;

  const signUrl = (location.origin || 'https://grom.exchange') + '/?grom_device=' + code;
  const trustUrl = gwDeviceTrustUrl(signUrl);

  let overlay = document.getElementById('gwDeviceSiwe');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'gwDeviceSiwe';
    overlay.innerHTML = `
      <div class="gw-dev-siwe-card">
        <div class="t" id="gwDeviceSiweT">Вход GROM</div>
        <div class="s" id="gwDeviceSiweS">Подготовка…</div>
        <button type="button" id="gwDeviceSiweTrustBtn" class="gw-dev-siwe-btn gw-dev-siwe-trust">Открыть в Trust Wallet</button>
        <button type="button" id="gwDeviceSiweBtn" class="gw-dev-siwe-btn" style="display:none;margin-top:8px;background:#1a2838;color:#e7eef8;border:1px solid rgba(0,194,255,.35)">Подписать вход</button>
      </div>`;
    const css = document.createElement('style');
    css.textContent = `
      #gwDeviceSiwe{position:fixed;inset:0;z-index:100000;background:rgba(4,10,18,.94);display:flex;align-items:center;justify-content:center;padding:24px}
      #gwDeviceSiwe .gw-dev-siwe-card{max-width:420px;width:100%;padding:22px 20px;border-radius:16px;background:linear-gradient(160deg,#142030,#0c1420);border:1px solid rgba(0,194,255,.35);color:#e7eef8;text-align:center}
      #gwDeviceSiwe .t{font-size:18px;font-weight:800;margin-bottom:8px}
      #gwDeviceSiwe .s{font-size:13px;color:#98a8c0;line-height:1.45;margin-bottom:16px}
      #gwDeviceSiwe .gw-dev-siwe-btn{width:100%;padding:14px;border:0;border-radius:10px;font-weight:800;font-size:15px;cursor:pointer}
      #gwDeviceSiwe .gw-dev-siwe-trust{background:#00c2ff;color:#041018}
      #gwDeviceSiwe .gw-dev-siwe-btn:disabled{opacity:.5}`;
    document.head.appendChild(css);
    document.body.appendChild(overlay);
  }

  const setMsg = (t, s) => {
    const te = document.getElementById('gwDeviceSiweT');
    const se = document.getElementById('gwDeviceSiweS');
    if (te && t) te.textContent = t;
    if (se && s) se.textContent = s;
  };
  const trustBtn = document.getElementById('gwDeviceSiweTrustBtn');
  const signBtn = document.getElementById('gwDeviceSiweBtn');
  trustBtn.onclick = () => { try { location.href = trustUrl; } catch (_) {} };

  async function doSign() {
    try {
      if (signBtn) { signBtn.disabled = true; signBtn.style.display = ''; }
      setMsg('Вход GROM', 'Загрузка запроса…');
      const st = await fetch('/auth/device/' + encodeURIComponent(code), { cache: 'no-store' });
      const body = await st.json().catch(() => ({}));
      if (st.status === 410) throw new Error('Код истёк — создайте новый QR на компьютере');
      if (!st.ok) throw new Error(body.error || 'Код не найден');
      if (body.status === 'done') {
        setMsg('Готово ✓', 'Вернитесь на компьютер — админка откроется сама.');
        if (trustBtn) trustBtn.style.display = 'none';
        if (signBtn) signBtn.style.display = 'none';
        return;
      }
      const message = body.message;
      const expect = String(body.address || '').toLowerCase();
      if (!message) throw new Error('Нет сообщения для подписи');

      setMsg('Вход GROM', 'Подключение кошелька…');
      let provider = await gwWaitInjectedProvider(5000);
      if (!provider?.request) {
        setMsg('Нужен Trust Browser', 'Safari не может подписать. Нажмите «Открыть в Trust Wallet».');
        if (trustBtn) trustBtn.style.display = '';
        if (signBtn) signBtn.disabled = false;
        return;
      }
      if (trustBtn) trustBtn.style.display = 'none';

      const accs = await provider.request({ method: 'eth_requestAccounts' });
      const addr = String(accs?.[0] || '').toLowerCase();
      if (!addr) throw new Error('Кошелёк не подключён');
      if (expect && addr !== expect) {
        throw new Error('Нужен ' + expect.slice(0, 10) + '… — сейчас ' + addr.slice(0, 10) + '…');
      }

      setMsg('Вход GROM', 'Подтвердите подпись (без газа)…');
      const signature = await provider.request({ method: 'personal_sign', params: [message, addr] });
      setMsg('Вход GROM', 'Проверяем…');
      const done = await fetch('/auth/device/complete', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code, signature }),
      });
      const dj = await done.json().catch(() => ({}));
      if (!done.ok) throw new Error(dj.error === 'unauthorized' ? 'Подпись не принята — обновите страницу и попробуйте снова' : (dj.error || 'Ошибка проверки'));
      try {
        if (dj.token) {
          localStorage.setItem('grom_jwt', dj.token);
          localStorage.setItem('grom_wallet_label', addr);
        }
      } catch (_) {}
      setMsg('Готово ✓', 'Вернитесь на компьютер — админка загрузится автоматически.');
      if (signBtn) signBtn.style.display = 'none';
    } catch (e) {
      setMsg('Ошибка', String(e?.message || e).slice(0, 180));
      if (signBtn) { signBtn.disabled = false; signBtn.textContent = 'Повторить'; }
      if (trustBtn && !gwInWalletBrowser()) trustBtn.style.display = '';
    }
  }

  if (signBtn) signBtn.onclick = () => { doSign(); };

  if (gwInWalletBrowser()) {
    if (trustBtn) trustBtn.style.display = 'none';
    if (signBtn) signBtn.style.display = '';
    setTimeout(() => { doSign(); }, 350);
  } else {
    setMsg('Вход GROM', 'Нажмите «Открыть в Trust Wallet» — Safari не может подписать.');
    if (trustBtn) trustBtn.style.display = '';
  }
  return true;
}
try { window.gwRunDeviceSiweIfNeeded = gwRunDeviceSiweIfNeeded; } catch (_) {}
try { window.gwDeviceTrustUrl = gwDeviceTrustUrl; } catch (_) {}
try { window.gwInWalletBrowser = gwInWalletBrowser; } catch (_) {}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', function () {
    try { if (gwShouldWarmWcLibs()) gwPrefetchWcLibs({ force: true }); } catch (_) {}
    try { gwRunDeviceSiweIfNeeded(); } catch (_) {}
    hook();
  });
} else {
  try { if (gwShouldWarmWcLibs()) gwPrefetchWcLibs({ force: true }); } catch (_) {}
  try { gwRunDeviceSiweIfNeeded(); } catch (_) {}
  hook();
}



